shader_type spatial;
uniform vec4 tint : source_color = vec4(0.68, 0.49, 0.27, 1.0);
varying vec3 world_pos;
float hash(vec3 p) { p=fract(p*0.1031); p+=dot(p,p.yzx+33.33); return fract((p.x+p.y)*p.z); }
float noise(vec3 p) {
 vec3 i=floor(p), f=fract(p); f=f*f*(3.0-2.0*f);
 return mix(mix(mix(hash(i),hash(i+vec3(1,0,0)),f.x),mix(hash(i+vec3(0,1,0)),hash(i+vec3(1,1,0)),f.x),f.y),mix(mix(hash(i+vec3(0,0,1)),hash(i+vec3(1,0,1)),f.x),mix(hash(i+vec3(0,1,1)),hash(i+vec3(1,1,1)),f.x),f.y),f.z);
}
void vertex() { world_pos = (MODEL_MATRIX * vec4(VERTEX,1.0)).xyz; }
void fragment() {
 float grain=noise(world_pos*8.0), patch=noise(world_pos*1.5);
 float strata=pow(abs(sin(world_pos.y*12.0+noise(world_pos*2.2)*4.0)),16.0);
 ALBEDO=tint.rgb * (0.79 + patch*0.33 + grain*0.12 - strata*0.055);
 ROUGHNESS=0.83;
}

extends SceneTree
var failures: PackedStringArray=[]
var finished := false
func _initialize() -> void:
	run.call_deferred()
func run() -> void:
	var stage := load("res://hub/open_lagoon.tscn").instantiate() as GameSession
	stage.profile_path=""
	root.add_child(stage)
	current_scene=stage
	for i in range(5):
		await physics_frame
	var hub := stage.get_node("OpenLagoon") as OpenLagoon
	var body := stage.get_node("Axolotl") as AxolotlBody
	hub.world_completed.connect(func(id: String) -> void: finished=id=="coral_cove")
	if not hub.enter_world("coral_cove"):
		print("CORAL WALK: FAIL — world unavailable")
		quit(1)
		return
	for i in range(30):
		await physics_frame
	var pilot := RoutePilot.new(CoralRoute.waypoints(),hub._active_world.global_position)
	var frames := 0
	for i in range(18000):
		await physics_frame
		frames=i
		if finished:
			break
		pilot.step(body)
		if not pilot.stuck_reason().is_empty():
			break
	pilot.release_all()
	for i in range(10):
		await physics_frame
	if not finished or hub.is_in_world():
		failures.append("finish must return to hub: "+pilot.stuck_reason())
	var data := stage.get_save_system().get_world_data("coral_cove")
	if not bool(data.get("completed",false)):
		failures.append("completion was not saved")
	if (data.get("resourceInstances",{}) as Dictionary).size()!=7:
		failures.append("route must collect seven unique seeds")
	if not hub.enter_world("coral_cove"):
		failures.append("completed world cannot be revisited")
	for i in range(10):
		await physics_frame
	var systems: Node = hub._active_world.get_children().back()
	if not (systems is WorldSystems) or not (systems as WorldSystems).get_restoration().all_restored():
		failures.append("restoration must survive hub return")
	print("CORAL WALK: ","PASS" if failures.is_empty() else "FAIL"," (",frames," frames)")
	for failure in failures:
		print("  ",failure)
	quit(0 if failures.is_empty() else 1)

extends RefCounted
## One height/flow field shared by every unrotated chute water Area.
## Using the same field makes the selected Area irrelevant at overlaps.
static var points: Array[Vector3] = []
static var distances: Array[float] = []
static func initialize() -> void:
	if not points.is_empty():
		return
	var raw: Dictionary = JSON.parse_string(FileAccess.get_file_as_string("res://dev/living_cascade/chute_profile.json")) as Dictionary
	var s := 0.0
	for row: Array in raw["points"]:
		var p := Vector3(float(row[0]),float(row[1]),float(row[2]))
		if not points.is_empty():
			var d: Vector3 = p-points.back()
			s += Vector2(d.x,d.z).length()
		points.append(p)
		distances.append(s)

static func sample(p: Vector3) -> Dictionary:
	initialize()
	var best := INF
	for i in range(points.size()-1):
		var a := points[i]
		var b := points[i+1]
		var d := Vector2(b.x-a.x,b.z-a.z)
		var delta := Vector2(p.x-a.x,p.z-a.z)
		var t := clampf(delta.dot(d)/d.length_squared(),0,1)
		best=minf(best,(delta-d*t).length_squared())
	var weight_sum := 0.0
	var height_sum := 0.0
	var height_gradient := Vector2.ZERO
	var weight_gradient := Vector2.ZERO
	var direction_sum := Vector2.ZERO
	var distance_sum := 0.0
	var lateral_sum := 0.0
	# Blend nearby segment planes, so the inside of a rounded bend has one
	# continuous height field. Straight sections retain their exact linear grade.
	for i in range(points.size()-1):
		var a := points[i]
		var b := points[i+1]
		var d := Vector2(b.x-a.x,b.z-a.z)
		var delta := Vector2(p.x-a.x,p.z-a.z)
		var projection := delta.dot(d)/d.length_squared()
		var t := clampf(projection,0,1)
		var offset := delta-d*t
		var weight := exp(-2.0*maxf(0,offset.length_squared()-best))
		if weight<0.000001:
			continue
		var direction := d.normalized()
		var slope := direction*((b.y-a.y)/d.length())
		var height := a.y+(b.y-a.y)*projection
		var derivative := -4.0*offset*weight
		weight_sum+=weight
		height_sum+=weight*height
		height_gradient+=weight*slope+derivative*height
		weight_gradient+=derivative
		direction_sum+=direction*weight
		distance_sum+=lerpf(distances[i],distances[i+1],t)*weight
		lateral_sum+=offset.dot(Vector2(-direction.y,direction.x))*weight
	var height := height_sum/weight_sum
	var direction := direction_sum.normalized()
	return {"surface":height,"slope":(height_gradient-height*weight_gradient)/weight_sum,"direction":Vector3(direction.x,0,direction.y),"s":distance_sum/weight_sum,"lateral":lateral_sum/weight_sum,"distance":sqrt(best)}

extends GdUnitTestSuite
func tuning() -> TuningData:
	return TuningData.load_from_file("res://core/tuning/tuning.json")
func simulate(controller: AxolotlController, seconds: float, hz: int, water: bool, direction: Vector3) -> void:
	for i in roundi(seconds * hz): controller.physics_step(1.0 / hz, water, PlayerIntent.new(direction))
func test_motion_starts_immediately_but_builds_to_speed_on_land_and_in_water() -> void:
	for water: bool in [false,true]:
		var c := AxolotlController.new(tuning())
		c.physics_step(1.0/60, water, PlayerIntent.new(Vector3.FORWARD))
		var first := c.get_velocity().length()
		assert_float(first).is_greater(0.0)
		assert_float(first).is_less(1.0)
		simulate(c,0.5,60,water,Vector3.FORWARD)
		assert_float(c.get_velocity().length()).is_greater(first * 4.0)
func test_acceleration_is_consistent_at_30_60_and_120_hz() -> void:
	for water: bool in [false,true]:
		var speeds: Array[float] = []
		for hz: int in [30,60,120]:
			var c := AxolotlController.new(tuning())
			simulate(c,0.1,hz,water,Vector3.FORWARD)
			speeds.append(c.get_velocity().length())
		assert_float(speeds[0]).is_equal_approx(speeds[1],0.001)
		assert_float(speeds[1]).is_equal_approx(speeds[2],0.001)
func test_reversal_brakes_without_a_one_frame_velocity_flip() -> void:
	var c := AxolotlController.new(tuning())
	simulate(c,0.5,60,false,Vector3.RIGHT)
	c.physics_step(1.0/60,false,PlayerIntent.new(Vector3.LEFT))
	assert_float(c.get_velocity().x).is_greater(0.0)
	simulate(c,0.3,60,false,Vector3.LEFT)
	assert_float(c.get_velocity().x).is_less(-4.0)
func test_analog_deflection_survives_input_and_controller() -> void:
	var input := InputSystem.new(BindingTable.load_from_file(BindingTable.DEFAULTS_PATH))
	input.set_grammar(MovementGrammar.Grammar.LAND)
	var event := InputEventJoypadMotion.new(); event.axis = JOY_AXIS_LEFT_X; event.axis_value = 0.59
	input.handle_event(event)
	var direction := input.poll_intent().direction
	assert_float(direction.length()).is_equal_approx(0.5,0.001)
	var c := AxolotlController.new(tuning())
	simulate(c,0.5,60,false,direction)
	assert_float(c.get_velocity().length()).is_equal_approx(2.1,0.001)
	event.axis_value = 0.1; input.handle_event(event)
	assert_float(input.poll_intent().direction.length()).is_equal_approx(0.0,0.001)
func test_jump_release_cuts_once_then_leaves_gravity_in_control() -> void:
	var jump := JumpFeel.new(tuning()); jump.consume()
	var cut := jump.cut_rise(9.0,false)
	assert_float(cut).is_less(9.0)
	for i in 30: assert_float(jump.cut_rise(cut,false)).is_equal_approx(cut,0.0001)
	jump.consume()
	assert_float(jump.cut_rise(9.0,false)).is_equal_approx(cut,0.0001)
func test_suit_mount_does_not_replace_the_existing_character_or_collision() -> void:
	var body := load("res://core/controller/axolotl_body.tscn").instantiate() as AxolotlBody
	assert_object(body.get_suit_mount()).is_not_null()
	assert_int(body.get_suit_mount().get_child_count()).is_equal(0)
	assert_float((body.get_node("Collision").shape as CapsuleShape3D).radius).is_equal_approx(0.5,0.001)
	body.free()
func test_swim_turn_builds_angular_speed_instead_of_snapping() -> void:
	var motion := HeroMotion.new(); motion.reset_pose(0.0)
	motion.prepare(1.0/60,true,false,Vector3.RIGHT*6,PI/2,0,Vector3.UP)
	var first := motion.visual_rotation.y
	assert_float(first).is_greater(0.0)
	assert_float(first).is_less(deg_to_rad(1.0))
	motion.prepare(1.0/60,true,false,Vector3.RIGHT*6,PI/2,0,Vector3.UP)
	assert_float(motion.visual_rotation.y-first).is_greater(first)
	motion.free()
func test_swim_turn_settles_without_overshoot_and_limits_neck_twist() -> void:
	var motion := HeroMotion.new(); motion.reset_pose(0.0)
	var previous := 0.0
	for i in 180:
		motion.prepare(1.0/60,true,false,Vector3.RIGHT*6,PI/2,0,Vector3.UP)
		assert_float(motion.visual_rotation.y).is_less(PI/2+0.001)
		assert_float(absf(motion.visual_rotation.y-previous)).is_less(deg_to_rad(4.01))
		assert_float(absf(motion._head_lead)).is_less(0.551)
		previous=motion.visual_rotation.y
	assert_float(motion.visual_rotation.y).is_equal_approx(PI/2,0.005)
	assert_float(absf(motion.bank)).is_less(0.01)
	motion.free()
func test_respawn_clears_swim_turn_momentum() -> void:
	var motion := HeroMotion.new(); motion.reset_pose(0.0)
	for i in 20:motion.prepare(1.0/60,true,false,Vector3.RIGHT*6,PI/2,0,Vector3.UP)
	motion.reset_pose(0.0)
	motion.prepare(1.0/60,true,false,Vector3.ZERO,0.0,0,Vector3.UP)
	assert_float(motion.visual_rotation.y).is_equal_approx(0.0,0.0001)
	assert_float(motion.bank).is_equal_approx(0.0,0.0001)
	motion.free()

class_name WaterTrail
extends Node

var _distance: float = 0.0
var _side: float = 1.0

func _ready() -> void:
	process_physics_priority = 10

func _physics_process(delta: float) -> void:
	var body := get_parent() as AxolotlBody
	if body == null:
		return
	var volume: WaterVolume = body.get_water_volume()
	if volume == null:
		RenderingServer.global_shader_parameter_set("water_actor",Vector4.ZERO)
		_distance = 0.0
		return
	var surface: float = volume.surface_at(body.global_position)
	# Drifting with the stream does not displace water like swimming against it.
	var relative_velocity: Vector3 = body.velocity-volume.flow_at(body.global_position)
	var speed: float = Vector2(relative_velocity.x,relative_velocity.z).length()
	var near_surface: bool = body.global_position.y-0.8 < surface and absf(body.global_position.y-surface) < 0.95
	var strength: float = clampf(speed/7.0,0.0,1.0) if near_surface else 0.0
	RenderingServer.global_shader_parameter_set("water_actor",Vector4(body.global_position.x,surface,body.global_position.z,strength))
	RenderingServer.global_shader_parameter_set("water_motion",Vector4(relative_velocity.x,0.0,relative_velocity.z,0.0))
	if not near_surface or speed < 0.65:
		_distance = 0.0
		return
	# Rigged footfalls own shallow-water splashes; this layer owns swimming wakes.
	if not body.is_in_water() and body.get_visual_motion() != null:
		return
	_distance += speed*delta
	var spinning: bool = body.get_controller().get_spin_sprint().is_active()
	if _distance < (0.40 if spinning else (1.15 if body.is_in_water() else 0.85)):
		return
	_distance = 0.0
	var direction := Vector3(relative_velocity.x,0,relative_velocity.z).normalized()
	var at := Vector3(body.global_position.x,surface+0.035,body.global_position.z)
	if not body.is_in_water():
		at += Vector3(-direction.z,0,direction.x)*_side*0.3
		_side = -_side
	WaterSplash.trail(self,at,relative_velocity,body.is_in_water())

func _exit_tree() -> void:
	RenderingServer.global_shader_parameter_set("water_actor",Vector4.ZERO)

