class_name FleetEncounter
extends Area3D
## One placed machine: local awareness, visible attack timing, and bounded movement.
const Breakup = preload("res://core/enemies/visuals/fleet_breakup.gd")
@export var underwater := false
@export var notice_range := 6.0
@export var leash_radius := 2.0
@export var patrol_radius := .55
var state: StringName = &"idle"
var home := Vector3.ZERO
var visual: FleetEnemyVisual
var systems: Node
var fleet: DriftFleetSystem
var _clock := 0.0
var _scan := 0.0
var _lost := 0.0
var _cooldown := 0.0
var _player: AxolotlBody
var _hit := false
var _previous_tips: Array[Vector3] = []
var _debris: Node3D
var _home_yaw := 0.0
# Movement is accelerated in metres/second, independent of animation and scan clocks.
var _move_velocity := Vector3.ZERO
var _yaw_velocity := 0.0
var _patrol_clock := 0.0
var _alert: Label3D

func _ready() -> void:
	home=global_position; _home_yaw=rotation.y
	visual=get_node("Visual") as FleetEnemyVisual
	visual.state_finished.connect(_finished)
	add_to_group("fleet_encounters")
	_alert=Label3D.new(); _alert.text="!"; _alert.font_size=72; _alert.pixel_size=.008; _alert.position.y=1.0; _alert.billboard=BaseMaterial3D.BILLBOARD_ENABLED; _alert.modulate=Color(1,.72,.16); _alert.visible=false; add_child(_alert)
	_patrol_clock=float(abs(String(name).hash())%100)/13.0
	visual.set_locomotion(Vector3.ZERO,0.0,underwater,0.0)

func bind_encounter(owner_systems: Node, model: DriftFleetSystem) -> void:
	systems=owner_systems; fleet=model
	fleet.enemy_staggered.connect(_on_staggered)
	fleet.enemy_recovered.connect(_on_recovered)

func _on_staggered(id: String,_kind: String,_seconds: float) -> void:
	if id==String(name): _set_state(&"stagger")

func _on_recovered(id: String) -> void:
	if id==String(name) and state==&"stagger": _set_state(&"idle")

func _exit_tree() -> void:
	if fleet!=null:
		if fleet.enemy_staggered.is_connected(_on_staggered): fleet.enemy_staggered.disconnect(_on_staggered)
		if fleet.enemy_recovered.is_connected(_on_recovered): fleet.enemy_recovered.disconnect(_on_recovered)
	fleet=null; systems=null

func _set_state(next: StringName) -> void:
	state=next; _clock=0.0
	_alert.visible=next in [&"notice",&"warn"]
	if next==&"attack": _hit=false; _move_velocity=Vector3.ZERO; _yaw_velocity=0.0; _previous_tips=_tips()
	visual.play_state(next if next not in [&"pursue",&"return"] else &"idle")

func _finished(clip: StringName) -> void:
	if state==&"disabled": return
	if clip==&"notice" and state==clip: _set_state(&"pursue")
	elif clip==&"warn" and state==clip:
		if _eligible() and _visible_player() and global_position.distance_to(_player.global_position)<=attack_range()+.25:
			visual.lock_attack_target(_player.global_position); _set_state(&"attack")
		else: _set_state(&"return")
	elif clip==&"attack" and state==clip: _set_state(&"recover")
	elif clip==&"recover" and state==clip: _cooldown=1.3; _set_state(&"idle")

func attack_range() -> float: return 2.8 if visual.enemy_kind==&"hookline_rig" else 1.5

func _eligible() -> bool:
	if not is_instance_valid(_player) or systems==null: return false
	if _player.is_in_water()!=underwater or systems._net_capture.active(): return false
	if _player.global_position.distance_to(home)>notice_range+leash_radius: return false
	# Protected checkpoint pads, arrival, crown and downhill finale.
	var local_player: Vector3=systems.get_parent().to_local(_player.global_position)
	if local_player.z>-19.5 or local_player.z < -91.0: return false
	for checkpoint: Node3D in systems._checkpoint_nodes:
		if checkpoint.global_position.distance_to(_player.global_position)<3.5: return false
	return absf(_player.global_position.y-global_position.y)<(2.5 if underwater else 1.5)

func _visible_player() -> bool:
	if not is_instance_valid(_player): return false
	return clear_line(global_position,_player.global_position)

func clear_line(from: Vector3,to: Vector3) -> bool:
	var q:=PhysicsRayQueryParameters3D.create(from,to,1)
	if is_instance_valid(_player): q.exclude=[_player.get_rid()]
	return get_world_3d().direct_space_state.intersect_ray(q).is_empty()

func _owns_attack() -> bool:
	for other: Node in get_tree().get_nodes_in_group("fleet_encounters"):
		if other!=self and other.systems==systems and other.state in [&"notice",&"warn",&"attack",&"recover"]:
			if other.global_position.distance_to(global_position)<10.0: return false
	return true

func _physics_process(delta: float) -> void:
	if fleet==null or state==&"disabled": return
	if not is_instance_valid(_player): _player=get_tree().get_first_node_in_group("player") as AxolotlBody
	_clock+=delta; _patrol_clock+=delta; _cooldown=maxf(0,_cooldown-delta)
	visual.set_locomotion(global_basis.inverse()*_move_velocity,_yaw_velocity,underwater,delta)
	if state==&"stagger": _move_velocity=Vector3.ZERO; _yaw_velocity=0.0; return
	if state==&"attack":
		if not _eligible(): _set_state(&"recover"); return
		_contact_tips(); return
	if state==&"recover": _move_velocity=Vector3.ZERO; _yaw_velocity=0.0; return
	if state==&"return":
		_move_toward(home,delta)
		if global_position.distance_to(home)<.12:
			_turn_toward(_home_yaw,delta)
			if absf(angle_difference(rotation.y,_home_yaw))<.04 and _move_velocity.length()<.05: _set_state(&"idle")
		return
	_scan-=delta
	if _scan<=0:
		_scan=.12
		var sees:=_eligible() and global_position.distance_to(_player.global_position)<notice_range and _visible_player()
		_lost=0.0 if sees else _lost+.12
		if state==&"idle" and sees and _cooldown<=0 and _owns_attack(): _set_state(&"notice")
		elif state in [&"notice",&"pursue",&"warn"] and (not _eligible() or _lost>.24): _set_state(&"return")
	if state in [&"notice",&"pursue",&"warn"] and is_instance_valid(_player):
		var direction:=_player.global_position-global_position
		_turn_toward(atan2(-direction.x,-direction.z),delta)
		if state==&"pursue":
			if direction.length()<=attack_range():
				_move_toward(global_position,delta)
				# Finish aiming before winding up, rather than throwing sideways mid-turn.
				if absf(angle_difference(rotation.y,atan2(-direction.x,-direction.z)))<.18 and _owns_attack(): _set_state(&"warn")
			else: _move_toward(_player.global_position,delta)
		else: _move_toward(global_position,delta)
	elif state==&"idle":
		# A short maintenance patrol; remote machines avoid per-frame physics queries.
		if is_instance_valid(_player) and global_position.distance_squared_to(_player.global_position)<225:
			_move_toward(home+Vector3(sin(_patrol_clock*.4),0,cos(_patrol_clock*.4)) * patrol_radius,delta,.35)
		else: _move_velocity=Vector3.ZERO; _yaw_velocity=0.0

func _turn_toward(yaw: float,delta: float) -> void:
	var error:=angle_difference(rotation.y,yaw)
	# A bounded angular acceleration removes the snap when acquisition reverses a patrol.
	var desired:=clampf(error*4.0,-2.2,2.2)
	_yaw_velocity=move_toward(_yaw_velocity,desired,7.5*delta)
	var turn:=_yaw_velocity*delta
	if absf(turn)>absf(error) and signf(turn)==signf(error): turn=error; _yaw_velocity=0.0
	rotation.y+=turn

func _move_toward(target: Vector3,delta: float,speed_scale: float=1.0) -> void:
	if leash_radius<=0.0: _move_velocity=Vector3.ZERO; return
	var offset:=target-home
	offset.y=clampf(offset.y,-.45,.45) if underwater else 0.0
	var flat:=Vector3(offset.x,0,offset.z).limit_length(leash_radius)
	var destination:=home+Vector3(flat.x,offset.y,flat.z)
	var direction:=destination-global_position
	if not underwater: direction.y=0.0
	var top_speed: float=(.8 if underwater else .95)*speed_scale
	var desired_velocity:=direction.normalized()*minf(top_speed,direction.length()*2.8)
	var acceleration: float=1.8 if underwater else 2.8
	_move_velocity=_move_velocity.move_toward(desired_velocity,acceleration*delta)
	if state in [&"idle",&"return"] and _move_velocity.length()>.04 and direction.length()>.12:
		_turn_toward(atan2(-_move_velocity.x,-_move_velocity.z),delta)
	if _move_velocity.length()<.002: _move_velocity=Vector3.ZERO; return
	var desired:=global_position+_move_velocity*delta
	var leash_offset:=desired-home; leash_offset.y=0.0
	if leash_offset.length()>leash_radius+.01: _move_velocity=Vector3.ZERO; return
	if underwater:
		desired.y=clampf(desired.y,home.y-.45,home.y+.45)
		var inside:=false
		for water: Node in get_tree().get_nodes_in_group("water_volumes"):
			if water.contains_point(desired,-.7): inside=true; break
		if not inside: _move_velocity=Vector3.ZERO; return
	else:
		var floor_y:=global_position.y
		for foot: Vector3 in [Vector3.ZERO,Vector3(.38,0,0),Vector3(-.38,0,0),Vector3(0,0,.38),Vector3(0,0,-.38)]:
			var q:=PhysicsRayQueryParameters3D.create(desired+foot+Vector3.UP*.2,desired+foot-Vector3.UP*1.0,1)
			if is_instance_valid(_player): q.exclude=[_player.get_rid()]
			var hit:=get_world_3d().direct_space_state.intersect_ray(q)
			if hit.is_empty() or hit.normal.y<.8 or absf((hit.position.y+.54)-global_position.y)>.2: _move_velocity=Vector3.ZERO; return
			if foot==Vector3.ZERO: floor_y=hit.position.y+.54
		# Follow small dressed-terrain undulations without a one-frame vertical jump.
		desired.y=move_toward(global_position.y,floor_y,.8*delta)
		for water: Node in get_tree().get_nodes_in_group("water_volumes"):
			if water.contains_point(desired-Vector3.UP*.4,-.2): _move_velocity=Vector3.ZERO; return
	var query:=PhysicsShapeQueryParameters3D.new(); var sphere:=SphereShape3D.new(); sphere.radius=.38; query.shape=sphere; query.collision_mask=1; query.transform=Transform3D(Basis.IDENTITY,global_position); query.motion=desired-global_position
	if is_instance_valid(_player): query.exclude=[_player.get_rid()]
	var sweep:=get_world_3d().direct_space_state.cast_motion(query)
	if sweep[0]<1.0: _move_velocity=Vector3.ZERO; return
	global_position=desired

func _tips() -> Array[Vector3]:
	var result: Array[Vector3]=[]
	if visual.enemy_kind==&"netbot":
		result.append((visual.get_node("Facing/Body/CaptureArm/NetBasket/AttackSocket") as Node3D).global_position)
	else:
		for side: String in ["Left","Right"]: result.append((visual.get_node("Facing/Body/Hook"+side) as Node3D).global_position)
	return result

func _contact_tips() -> void:
	var tips:=_tips()
	if visual.attack_active and not _hit and _visible_player():
		for i: int in tips.size():
			var near:=Geometry3D.get_closest_point_to_segment(_player.global_position,_previous_tips[i],tips[i])
			if near.distance_to(_player.global_position)<(.72 if visual.enemy_kind==&"netbot" else .55):
				_hit=true; systems._on_enemy_contact(self); break
	_previous_tips=tips

func defeat(direction: Vector3) -> void:
	if state==&"disabled": return
	_move_velocity=Vector3.ZERO; _yaw_velocity=0.0
	visual.attack_active=false; visual.get_node("AnimationPlayer").stop(); state=&"disabled"; _alert.visible=false
	_debris=Breakup.new(); get_parent().add_child(_debris); _debris.burst(visual,underwater,direction)
	visual.hide(); set_deferred("monitoring",false); set_deferred("monitorable",false)

func reset_encounter() -> void:
	if is_instance_valid(_debris): _debris.queue_free()
	_move_velocity=Vector3.ZERO; _yaw_velocity=0.0
	visual.reset_locomotion()
	global_position=home; rotation.y=_home_yaw; _hit=false; _lost=0; _cooldown=1.5
	visual.show(); visual.play_state(&"reset"); _set_state(&"idle")
	set_deferred("monitoring",true); set_deferred("monitorable",true)

@tool
class_name TerrainShell
extends Node3D

## The VISUAL skin wrapped around a greybox collision proxy (REQ-030, REQ-034).
##
## Gameplay owns the BoxShape3D. This node owns only the thing the player sees.
## The separation is deliberate: measured jump distances, walk probes and world
## contracts keep addressing the collision proxy while the final-facing art can
## become organic without moving a single gameplay surface.
##
## The walkable cap stays EXACTLY on the proxy's top plane. The final edge now
## has three zones rather than one flat overhang:
##
##   * CAP — follows the collision footprint exactly and stays perfectly flat;
##   * WEATHERED RIM — pushes OUTSIDE the collision and drops slightly, so the
##     eye sees an edge before the feet run out of floor instead of seeing a
##     walkable-looking shelf hanging over empty space;
##   * SKIRT — pulls inward as it descends, breaking the box silhouette below.
##
## That small dropped rim is a gameplay-readability detail, not decoration. A
## platformer feels fair when the visible lip and the physical lip agree.
##
## THE MESHY INTERFACE. `visual_kit` is a drop-in slot: set it to a PackedScene
## and that art is used instead of the generated shell, fitted to the proxy's
## bounds by the same anchor rule. The collision, route markers and tests never
## move.
##
## ADDS NO COLLISION, EVER.

@export var proxy_path: NodePath = ^"..":
	set(value):
		proxy_path = value
		_rebuild()

@export var visual_kit: PackedScene:
	set(value):
		visual_kit = value
		_rebuild()

@export var surface_material: Material:
	set(value):
		surface_material = value
		_rebuild()

## Maximum horizontal overhang beyond the collision footprint.
@export var rim_margin: float = 0.55:
	set(value):
		rim_margin = maxf(value, 0.0)
		_rebuild()

## Vertical drop of the cosmetic outer rim. It is clamped again against the
## proxy thickness while building, so a thin step can never bevel through its
## own underside.
@export var rim_drop: float = 0.14:
	set(value):
		rim_drop = maxf(value, 0.0)
		_rebuild()

## Cosmetic rock below the proxy.
@export var skirt_depth: float = 1.8:
	set(value):
		skirt_depth = maxf(value, 0.0)
		_rebuild()

## Target spacing between rim samples. A spacing works for both tiny steps and
## the lagoon floor; a fixed segment count does not.
@export var rim_spacing_m: float = 3.0:
	set(value):
		rim_spacing_m = maxf(value, 0.25)
		_rebuild()

const MIN_RIM_SEGMENTS := 8
const MAX_RIM_SEGMENTS := 64

@export var shell_seed: int = 0:
	set(value):
		shell_seed = value
		_rebuild()

var _visual: Node3D


func _ready() -> void:
	_rebuild()


func proxy_bounds() -> AABB:
	var proxy := get_node_or_null(proxy_path)
	if proxy == null:
		return AABB()
	for child: Node in proxy.find_children("*", "CollisionShape3D", true, false):
		var shape := (child as CollisionShape3D).shape as BoxShape3D
		if shape == null:
			continue
		var offset := (child as CollisionShape3D).position
		return AABB(offset - shape.size * 0.5, shape.size)
	return AABB()


func get_visual() -> Node3D:
	return _visual


## Triangles readable without adding the shell to the tree. The performance
## gate uses this when it counts a world before playing it.
func shell_triangles() -> int:
	var mesh := _build_mesh()
	if mesh == null:
		return 0
	var total := 0
	for surface: int in mesh.get_surface_count():
		var indices: Variant = mesh.surface_get_arrays(surface)[Mesh.ARRAY_INDEX]
		if indices != null:
			total += (indices as PackedInt32Array).size() / 3
	return total


func _rebuild() -> void:
	if _visual != null:
		remove_child(_visual)
		_visual.free()
		_visual = null

	var bounds := proxy_bounds()
	if bounds.size == Vector3.ZERO:
		return

	_visual = _kit_instance(bounds) if visual_kit != null else _generated(bounds)
	if _visual == null:
		return
	_visual.name = "Shell"
	add_child(_visual)


## Drop-in authored art. Its top face is fitted to the proxy top and its
## footprint covers the proxy plus the allowed cosmetic rim.
func _kit_instance(bounds: AABB) -> Node3D:
	var instance := visual_kit.instantiate() as Node3D
	if instance == null:
		return null
	var kit_bounds := _instance_bounds(instance)
	if kit_bounds.size.x <= 0.0 or kit_bounds.size.z <= 0.0:
		return instance

	var wanted := Vector3(bounds.size.x + rim_margin * 2.0,
		bounds.size.y + skirt_depth, bounds.size.z + rim_margin * 2.0)
	instance.scale = Vector3(
		wanted.x / kit_bounds.size.x,
		wanted.y / maxf(kit_bounds.size.y, 0.0001),
		wanted.z / kit_bounds.size.z)
	var scaled_top := (kit_bounds.position.y + kit_bounds.size.y) * instance.scale.y
	instance.position = Vector3(
		bounds.get_center().x, bounds.position.y + bounds.size.y - scaled_top,
		bounds.get_center().z)
	if surface_material != null:
		for node: Node in instance.find_children("*", "MeshInstance3D", true, false):
			(node as MeshInstance3D).material_override = surface_material
	return instance


func _generated(bounds: AABB) -> Node3D:
	var mesh := _build_mesh()
	if mesh == null:
		return null
	var instance := MeshInstance3D.new()
	instance.mesh = mesh
	if surface_material != null:
		instance.material_override = surface_material
	return instance


func _instance_bounds(instance: Node3D) -> AABB:
	var total := AABB()
	var first := true
	for node: Node in instance.find_children("*", "MeshInstance3D", true, false):
		var mesh := (node as MeshInstance3D).mesh
		if mesh == null:
			continue
		var box := mesh.get_aabb()
		total = box if first else total.merge(box)
		first = false
	return total


## Flat collision-matched cap -> lowered organic rim -> rocky skirt.
func _build_mesh() -> ArrayMesh:
	var bounds := proxy_bounds()
	if bounds.size == Vector3.ZERO:
		return null

	var centre := bounds.get_center()
	var top := bounds.position.y + bounds.size.y
	var half := Vector2(bounds.size.x * 0.5, bounds.size.z * 0.5)
	var floor_y := bounds.position.y - skirt_depth
	var segments := _segment_count(half)
	var safe_rim_drop := minf(rim_drop, bounds.size.y * 0.45)

	var vertices := PackedVector3Array()
	var colours := PackedColorArray()
	var indices := PackedInt32Array()

	# Hub of the walkable top.
	vertices.append(Vector3(centre.x, top, centre.z))
	colours.append(Color(0.86, 0.88, 0.82))

	# CAP RING: exactly the collision footprint. This is the important change
	# from the first shell pass: the last vertex that still looks walkable is
	# now exactly where the physical floor ends.
	var cap_start := vertices.size()
	for step: int in segments:
		var t := float(step) / float(segments)
		var edge := _perimeter_point(t, half)
		vertices.append(Vector3(centre.x + edge.x, top, centre.z + edge.y))
		colours.append(Color(0.84, 0.86, 0.79))

	# WEATHERED RIM: always outside, always a little lower. Variation is split
	# between horizontal overhang and drop so repeated shells do not share the
	# same silhouette or the same perfectly level ledge.
	var rim_start := vertices.size()
	for step: int in segments:
		var t := float(step) / float(segments)
		var edge := _perimeter_point(t, half)
		var outward := _perimeter_normal(t, half)
		var jitter := _noise(step, 0) * rim_margin
		var out := edge + outward * (rim_margin * 0.45 + jitter)
		var drop := safe_rim_drop * (0.72 + _noise(step, 3) * 0.56)
		vertices.append(Vector3(
			centre.x + out.x, top - drop, centre.z + out.y))
		colours.append(Color(0.74, 0.77, 0.70))

	# SKIRT: pulls inward as it descends. It is wholly cosmetic and may vary
	# freely because the player cannot stand on it.
	var skirt_start := vertices.size()
	for step: int in segments:
		var t := float(step) / float(segments)
		var edge := _perimeter_point(t, half)
		var pull := 0.74 + _noise(step, 1) * 0.20
		var out := edge * pull
		vertices.append(Vector3(
			centre.x + out.x,
			floor_y + _noise(step, 2) * skirt_depth * 0.3,
			centre.z + out.y))
		colours.append(Color(0.55, 0.56, 0.53))

	for step: int in segments:
		var next := (step + 1) % segments
		# Flat walkable cap.
		indices.append_array([0, cap_start + step, cap_start + next])
		# Bevel from the true collision edge down to the weathered overhang.
		indices.append_array([
			cap_start + next, cap_start + step, rim_start + step,
			rim_start + step, rim_start + next, cap_start + next])
		# Rock skirt.
		indices.append_array([
			rim_start + next, rim_start + step, skirt_start + step,
			skirt_start + step, skirt_start + next, rim_start + next])

	var surface := SurfaceTool.new()
	surface.begin(Mesh.PRIMITIVE_TRIANGLES)
	for index: int in vertices.size():
		surface.set_color(colours[index])
		surface.add_vertex(vertices[index])
	for index: int in indices:
		surface.add_index(index)
	# Shared vertices across cap/rim/skirt intentionally soften the edge under
	# light without moving it. Shape carries the silhouette; normals carry the
	# weathering.
	surface.generate_normals()
	return surface.commit()


func _segment_count(half: Vector2) -> int:
	var perimeter := 4.0 * (half.x + half.y)
	return clampi(int(round(perimeter / rim_spacing_m)),
		MIN_RIM_SEGMENTS, MAX_RIM_SEGMENTS)


## A point on the rectangle outline, spaced uniformly by perimeter length.
static func _perimeter_point(t: float, half: Vector2) -> Vector2:
	var width := half.x * 2.0
	var depth := half.y * 2.0
	var along := fposmod(t, 1.0) * (width + depth) * 2.0
	if along < width:
		return Vector2(-half.x + along, -half.y)
	along -= width
	if along < depth:
		return Vector2(half.x, -half.y + along)
	along -= depth
	if along < width:
		return Vector2(half.x - along, half.y)
	along -= width
	return Vector2(-half.x, half.y - along)


## Outward normal for the perimeter edge. At exact corners both face normals
## contribute, giving a diagonal rather than a one-axis spike.
static func _perimeter_normal(t: float, half: Vector2) -> Vector2:
	var point := _perimeter_point(t, half)
	var normal := Vector2.ZERO
	if is_equal_approx(point.y, -half.y):
		normal += Vector2(0.0, -1.0)
	if is_equal_approx(point.y, half.y):
		normal += Vector2(0.0, 1.0)
	if is_equal_approx(point.x, -half.x):
		normal += Vector2(-1.0, 0.0)
	if is_equal_approx(point.x, half.x):
		normal += Vector2(1.0, 0.0)
	return normal.normalized() if normal != Vector2.ZERO else Vector2(1.0, 0.0)


## Deterministic in (seed, index, channel).
func _noise(index: int, channel: int) -> float:
	var hashed := float(
		(shell_seed * 73856093) ^ (index * 19349663) ^ (channel * 83492791))
	return fposmod(sin(hashed) * 43758.5453, 1.0)

@tool
class_name CameraHintVolume
extends Area3D

## The node a world places to direct framing (REQ-005 AC-3, AC-4).
##
## This is the entire authoring surface for camera control in a world module:
## drop the node, set exported values in the inspector, done. There is no
## script to write, no callback to implement and no camera API to call — which
## is what makes "declaratively without custom camera code" true rather than
## aspirational, and what keeps world modules inside the sanctioned API surface.
##
## Every field is @export, so AC-4's "driven by exported configuration values"
## is satisfied structurally: there is nothing else here to drive it with.
##
## The volume does NOT hold a CameraRig reference and never calls it. It emits;
## the Game Client wires those signals to the rig. That keeps CameraRig free of
## the scene tree (so its criteria stay headlessly assertable) and means a world
## cannot reach the camera object even if it wanted to.

signal hint_entered(hint: CameraHint)
signal hint_exited(hint_id: String)

## Higher wins where volumes overlap. Declared, never inferred from enter order.
##
## NOT named `priority`: Area3D already has a `priority` property (its audio-bus
## processing order), and shadowing it is a parse error rather than a silent
## surprise — but only because GDScript catches it. The rename is the fix, and
## the prefix also reads better in the inspector next to the framing fields.
@export var hint_priority: int = 0

@export_group("Framing overrides")
## Leave false and the field below is not overridden at all — the camera keeps
## whatever the grammar default or a lower-priority hint gave it.
@export var override_distance: bool = false
@export_range(0.1, 30.0, 0.05) var distance_m: float = 3.0

@export var override_pitch: bool = false
@export_range(-80.0, 80.0, 0.5) var pitch_deg: float = 20.0

@export var override_yaw: bool = false
@export_range(-180.0, 180.0, 0.5) var yaw_deg: float = 0.0

@export_group("Axis locks")
## A locked axis HOLDS its current value while the player is inside the volume.
## Use it to stop the camera swinging in a tunnel; use an override above to point
## it somewhere specific.
@export var lock_pitch: bool = false
@export var lock_yaw: bool = false
@export var lock_distance: bool = false

## Group the player body must belong to for this volume to fire. A group rather
## than a class check or a name, for the same reason ClimbSurface uses one: it is
## inspectable, declarable per world, and checkable by static analysis.
const PLAYER_GROUP := "player"


func _ready() -> void:
	if Engine.is_editor_hint():
		return
	body_entered.connect(_on_body_entered)
	body_exited.connect(_on_body_exited)


## Stable id derived from the scene-unique path: two worlds may each hold a
## "TunnelCam", and an ambiguous id would let one volume evict the other from the
## hint stack.
func hint_id() -> String:
	# get_path() is only valid inside the tree, and outside it returns empty —
	# which CameraHintStack silently REFUSES, so a volume asked for its hint
	# before _ready would produce a hint that never applies and never errors.
	# Falling back to the node name keeps the object usable and inspectable.
	if is_inside_tree():
		return String(get_path())
	return name


## The declared overrides as data. Only the boxes actually ticked are declared,
## which is what lets a distance-only volume sit on top of a pitch-only one
## without either erasing the other.
func to_hint() -> CameraHint:
	var hint := CameraHint.new(hint_id(), hint_priority)

	if override_distance:
		hint.set_distance(distance_m)
	if override_pitch:
		hint.set_pitch_deg(pitch_deg)
	if override_yaw:
		hint.set_yaw_deg(yaw_deg)

	var locked := 0
	if lock_pitch:
		locked |= int(CameraFraming.Axis.PITCH)
	if lock_yaw:
		locked |= int(CameraFraming.Axis.YAW)
	if lock_distance:
		locked |= int(CameraFraming.Axis.DISTANCE)
	if locked != 0:
		hint.set_locked_axes(locked)

	return hint


func _on_body_entered(body: Node3D) -> void:
	if not body.is_in_group(PLAYER_GROUP):
		return
	hint_entered.emit(to_hint())


func _on_body_exited(body: Node3D) -> void:
	if not body.is_in_group(PLAYER_GROUP):
		return
	hint_exited.emit(hint_id())

shader_type spatial;
render_mode diffuse_burley;
uniform vec4 rock_tint: source_color = vec4(0.65,0.61,0.50,1.0);
uniform vec4 grass_tint: source_color = vec4(0.30,0.49,0.21,1.0);
uniform vec4 sand_tint: source_color = vec4(0.87,0.80,0.62,1.0);
uniform float surface_kind = 1.0;
uniform float water_level = 0.0;
varying vec3 terrain_position;
varying vec3 terrain_normal;
float hash(vec3 p){ p=fract(p*0.1031);p+=dot(p,p.yzx+33.33);return fract((p.x+p.y)*p.z); }
float noise(vec3 p){vec3 i=floor(p),f=fract(p);f=f*f*(3.0-2.0*f);return mix(mix(mix(hash(i),hash(i+vec3(1,0,0)),f.x),mix(hash(i+vec3(0,1,0)),hash(i+vec3(1,1,0)),f.x),f.y),mix(mix(hash(i+vec3(0,0,1)),hash(i+vec3(1,0,1)),f.x),mix(hash(i+vec3(0,1,1)),hash(i+vec3(1,1,1)),f.x),f.y),f.z);}
void vertex(){terrain_position=VERTEX;terrain_normal=NORMAL;}
void fragment(){
 float macro=noise(terrain_position*0.21);
 float detail=noise(terrain_position*6.5);
 float up=smoothstep(0.62,0.94,terrain_normal.y);
 float moss=smoothstep(0.29,0.64,macro+noise(terrain_position*1.1)*0.17);
 float weather=noise(terrain_position*1.25);
 float flecks=noise(terrain_position*18.0);
 vec3 stone=rock_tint.rgb*(0.66+macro*0.43+weather*0.18+detail*0.13);
 float band=sin(terrain_position.y*2.2+noise(terrain_position*0.65)*4.0);
 stone*=1.0-smoothstep(0.90,1.0,band)*0.13;
 stone*=0.95+flecks*0.1;
 float lichen=smoothstep(0.58,0.77,macro+weather*0.16)*(1.0-up)*0.28;
 stone=mix(stone,grass_tint.rgb*0.68,lichen);
 vec3 sand=sand_tint.rgb*(0.92+macro*0.11+detail*0.045);
 vec3 turf=grass_tint.rgb*(0.88+macro*0.22+detail*0.07);
 vec3 ground=stone;
 if(surface_kind<0.5){ground=sand;}
 else if(surface_kind<1.5){ground=mix(stone,mix(sand,turf,moss),up);}
 else {ground=mix(stone,turf,up*moss*0.55);}
 float wet=(1.0-smoothstep(water_level-0.1,water_level+0.24,terrain_position.y))*0.19;
 ALBEDO=ground*(1.0-wet);
 ROUGHNESS=0.87-wet*1.7;
 SPECULAR=0.18;
}

extends RefCounted
## Section-authored, volumetric GLB composition. No facade bakes or texture skins.
const ASSETS := "res://assets/environment/cascade_"
var world: Node3D
var holder: Node3D
var models: Dictionary = {}
var boxes: Dictionary = {}
var shapes: Dictionary = {}
var heights: Dictionary = {}
var shadow_hulls: Dictionary = {}
var shadow_meshes: Dictionary = {}
var placements: Array[Dictionary] = []
var section := ""
var terrain: RefCounted

func apply(target: Node3D) -> void:
	world=target
	terrain=preload("res://dev/living_cascade/cascade_landscape.gd").new()
	terrain.begin(world)
	DirAccess.make_dir_recursive_absolute("res://core/rendering/cascade_collision")
	shadow_hulls=JSON.parse_string(FileAccess.get_file_as_string("res://dev/living_cascade/cascade-shadow-hulls.json")) as Dictionary
	holder=Node3D.new()
	holder.name="SuppliedAssets"
	world.add_child(holder)
	# The generated prototype landmarks and large fern fields compete with the kit.
	var old := world.get_node("Dressing")
	for n: Node in old.get_children():
		var id := String(n.name)
		if id.begins_with("RootBridge") or id.begins_with("Crown") or id.begins_with("Cliff") or id.begins_with("Canopy") or id.begins_with("RisingRoot") or id.begins_with("CascadeCliff") or id=="CentralGrove" or id=="GardenRocks":
			erase(n)
		elif n is ScatterField:
			erase(n)
	# Banks retain the established route outline but are built from whole rocks.
	# Ramps and sand beds remain continuous terrain between these formations.
	for solid: StaticBody3D in world.find_children("*","StaticBody3D",true,false):
		var visual := solid.get_node_or_null("Mesh") as MeshInstance3D
		if visual==null or not visual.mesh is BoxMesh:
			continue
		var size := (visual.mesh as BoxMesh).size
		var id := String(solid.name)
		var path := String(world.get_path_to(solid))
		section=path.get_slice("/",1) if path.begins_with("Sections/") else "Perimeter"
		# The garden's front is a balcony over the preceding catch pools. The
		# old 16 m dividing boxes leave no room for a full-depth cliff on either
		# side without blocking the stair or seed loop. Its 2.4 m bank rise is
		# the actual edge; the west divider and restoration gate remain closed.
		if section=="S05" and id in ["NorthRidgeWest","NorthRidgeEast"]:
			hide_solid(solid,true)
			continue
		if id=="CheckpointPad":
			hide_solid(solid,true)
			continue
		if solid.rotation.length()>0.02 or "Bed" in id or "Foundation" in id or "Roof" in id or id=="Gate" or id=="DiveBrow":
			continue
		if (size.y<=2.9 or id in ["RewardWestBank","GateFloor"]) and size.x>=2 and size.z>=2:
			if id in ["P21","P22","P23","P24","O1","A1","A2","C1","C2","C3"]:
				landing(solid,3.65)
			else:
				bank(solid,size)
		elif is_wall(id,size):
			wall(solid,size)
	section="S01"
	arrival()
	section="S02"
	garden()
	section="S03"
	root_dive()
	section="S04"
	terraces()
	section="S05"
	crown()
	section="S06"
	chute()
	# Replace the remaining authored beds and sloping connectors with real
	# subdivided terrain meshes. The original paths and body groups stay stable.
	for solid: StaticBody3D in world.find_children("*","StaticBody3D",true,false):
		var visual := solid.get_node_or_null("Mesh") as MeshInstance3D
		if visual==null or not visual.mesh is BoxMesh: continue
		var id := String(solid.name)
		if "Roof" in id or id in ["DiveBrow","DiveBar"]: continue
		var path := String(world.get_path_to(solid))
		section=path.get_slice("/",1) if path.begins_with("Sections/") else "Perimeter"
		if id=="Gate":
			visual.material_override=terrain.material("S05","wall")
			continue
		var kind := "sand" if "Bed" in id or "Foundation" in id else "bank"
		terrain.replace(solid,(visual.mesh as BoxMesh).size,section,kind)
	terrain.waterfall_sources()
	terrain.finish()
	preload("res://dev/living_cascade/cascade_collision_polish.gd").new().apply(world)
	preload("res://dev/living_cascade/cascade_basin_seals.gd").new().apply(world)
	# Small whole-model stones remain decorative; the traversable assets above
	# own collision. Four batches keep the stream beds readable without clutter.
	for row: Array in [["ArrivalRocks","mossy_stone",Vector3(-5,-1.94,-9)], ["GardenRocks","mossy_stone",Vector3(-29,-1.94,-35)], ["GrottoRocks","reef_ledge",Vector3(-11,-3.12,-61)], ["FinishRocks","reef_ledge",Vector3(-25,-2.32,-102)]]:
		var field := ScatterField.new()
		field.name=String(row[0])
		field.prop_scene=load(ASSETS+String(row[1])+"/"+String(row[1])+".glb") as PackedScene
		var transforms := PackedFloat32Array()
		for i in range(4):
			var p: Vector3=(row[2] as Vector3)+Vector3(float(i%2)*1.3,0,float(i/2)*1.4)
			var s := 0.18+float(i%2)*0.04
			transforms.append_array(PackedFloat32Array([s,0,0,0,s,0,0,0,s,p.x,p.y,p.z]))
		field.transforms=transforms
		world.get_node("Dressing").add_child(field)
	FileAccess.open("res://review/cascade-asset-placements.json",FileAccess.WRITE).store_string(JSON.stringify(placements,"\t"))
	print("SOLID ASSETS: ",placements.size()," linked full-mesh placements")

