extends SceneTree
var failures: PackedStringArray = []
var scene: Node3D
var body: AxolotlBody
var session: Node
func _initialize() -> void:
	call_deferred("_run")
func _run() -> void:
	scene = (load("res://dev/living_cascade/blockout.tscn") as PackedScene).instantiate() as Node3D
	session=scene.get_node("PreviewSession")
	session.set("save_path","")
	root.add_child(scene)
	current_scene=scene
	body=scene.get_node("Axolotl") as AxolotlBody
	for frame in range(30):
		await physics_frame
	var space := body.get_world_3d().direct_space_state
	var probes := 0
	for x in range(-41,40,2):
		for z in range(-126,6,2):
			var q := PhysicsRayQueryParameters3D.create(Vector3(x,-3.5,z),Vector3(x,-7,z),1,[body.get_rid()])
			q.hit_from_inside=true
			check(not space.intersect_ray(q).is_empty(),"continuous foundation %d/%d" % [x,z])
			probes+=1
	print("foundation coverage probes: ",probes)
	# The outer perimeter connects below the foundation and above all supports.
	for y: float in [-3.8,0,7.8,10.5,15.5]:
		for z in range(-126,6,3):
			for pair: Vector2 in [Vector2(-41,-44),Vector2(39,42)]:
				check(not space.intersect_ray(PhysicsRayQueryParameters3D.create(Vector3(pair.x,y,z),Vector3(pair.y,y,z),1)).is_empty(),"outer east/west closure")
		for x in range(-41,40,3):
			for pair: Vector2 in [Vector2(5,8),Vector2(-126,-129)]:
				check(not space.intersect_ray(PhysicsRayQueryParameters3D.create(Vector3(x,y,pair.x),Vector3(x,y,pair.y),1)).is_empty(),"outer north/south closure")
	# Probe the full west dividing ridge at standing and boosted-jump heights.
	for z in range(-109,-94):
		for y: float in [7.8,9.5,11.5]:
			check(not space.intersect_ray(PhysicsRayQueryParameters3D.create(Vector3(12,y,z),Vector3(7,y,z),1)).is_empty(),"closed garden ridge/gate")
	for mode: String in ["walk","jump","climb"]:
		await reset_body(Vector3(12,7.85,-104))
		var pilot := RoutePilot.new([RoutePilot.at(mode,Vector3(7,7.8,-104),"closed gate attempt")])
		for frame in range(240):
			await physics_frame
			pilot.step(body)
		pilot.release_all()
		check(body.global_position.x>9.8 and body.global_position.y<11.3,"gate blocks "+mode)
		print("closed gate ",mode," / ",body.global_position)
	# Wide misses outside local pools hit the safety recovery, never the void.
	for p: Vector3 in [Vector3(7,1.5,-14),Vector3(-32,2,-22),Vector3(20,4,-72),Vector3(35,8,-109)]:
		await reset_body(p)
		for frame in range(150):
			await physics_frame
		check(body.global_position.y>=-3.1,"wide miss remains above fallback plane")
	print("LIVING CASCADE CONTAINMENT: ","PASS" if failures.is_empty() else "FAIL")
	for f in failures:
		print("  ",f)
	quit(0 if failures.is_empty() else 1)
func reset_body(p: Vector3) -> void:
	body.get_input_system().clear()
	body.clear_water_contacts()
	body.global_position=p
	body.velocity=Vector3.ZERO
	body.get_controller().set_velocity(Vector3.ZERO)
	body.resample_water_contacts()
	for frame in range(20):
		await physics_frame
func check(ok: bool,label: String) -> void:
	if not ok:
		failures.append(label)

shader_type spatial;
render_mode cull_back, diffuse_burley, specular_schlick_ggx;

// VEGETATION WIND — the cheapest large quality win available to this project.
//
// Every plant in the valley was FROZEN. Forty-eight identical canopy trees and
// fifty identical ferns, none of them moving, is most of why a forest full of
// geometry still read as a diorama: a still plant is indistinguishable from a
// prop, and the eye knows it. This costs no geometry, no textures and no draw
// calls — it is arithmetic in the vertex stage — and it is worth more than any
// amount of extra polygon detail on the same plants.
//
// THE SWAY IS A LEVER, NOT A TRANSLATION. Displacement scales with height
// above the plant's own base raised to `stiffness`, so the roots never move,
// the trunk bends a little and the canopy travels furthest. Translating the
// whole mesh would slide plants off their own ground, which reads instantly
// as wrong; shearing from a fixed floor is what a plant in wind actually does.
//
// PLANTS MUST NOT MOVE IN LOCKSTEP. The phase comes from the INSTANCE's world
// origin rather than from each vertex, which matters twice over: neighbouring
// plants are out of step with each other, and every vertex of one plant shares
// a phase so the plant sways as a single object instead of rippling internally.
//
// Works identically under MeshInstance3D and MultiMeshInstance3D, because
// MODEL_MATRIX carries the instance transform in both cases. Under MultiMesh,
// INSTANCE_CUSTOM adds a per-instance phase and tint so a scattered field of
// one mesh does not read as one mesh repeated.

// Albedo comes from COLOR_0: the whole environment kit is vertex-painted and
// ships no textures (docs/asset-contract.md's surface doctrine).
uniform float roughness_value : hint_range(0.0, 1.0) = 0.82;
uniform float specular_value : hint_range(0.0, 1.0) = 0.35;

// Wind direction on the ground plane. Normalised in the shader so a caller
// cannot accidentally scale the sway by feeding a non-unit vector.
uniform vec2 wind_direction = vec2(0.82, 0.57);

// Displacement at full height, as a FRACTION of the plant's own height.
//
// Not an absolute distance, because the kit's plants differ by a factor of
// thirty — a canopy tree is 21.9 model units tall and a fern is 0.74 — and one
// distance that suits a tree is invisible on a fern while one that suits a
// fern tears a tree apart. A fraction is the same LEAN ANGLE on both, which is
// what wind actually does to plants of different sizes.
uniform float sway_fraction : hint_range(0.0, 0.3) = 0.035;
uniform float sway_hz : hint_range(0.0, 4.0) = 0.30;

// A faster, smaller motion on top of the sway. Without it the movement reads
// as a single sine and the whole forest breathes in unison; with it, leaves
// have their own life at a different rate.
uniform float flutter_fraction : hint_range(0.0, 0.1) = 0.008;
uniform float flutter_hz : hint_range(0.0, 12.0) = 1.7;

// The plant's full height in MODEL space. SET PER FIELD from the mesh's own
// bounds (ScatterField does this), never left at the default: a shared value
// is wrong for every plant that is not exactly that tall, and being wrong
// upward is the worse direction — the lever saturates partway up the trunk and
// everything above it translates as a rigid block, which puts a visible kink
// in the tree instead of a bend.
uniform float model_height : hint_range(0.05, 60.0) = 2.2;

// Below this FRACTION of the plant's height nothing moves at all: roots, the
// trunk base, the part that is visibly in the ground. A fraction rather than a
// distance for the same reason the sway is.
uniform float anchor_fraction : hint_range(0.0, 0.5) = 0.06;

// Higher concentrates the motion in the top of the plant. 1.0 is a linear
// bend; above that the trunk stiffens and only the canopy really travels.
uniform float stiffness : hint_range(0.5, 4.0) = 1.6;

// How far a scattered instance may be tinted from the mesh's own colour, so a
// field of one mesh is not a field of one colour. Driven by INSTANCE_CUSTOM.y.
uniform vec3 tint_toward : source_color = vec3(0.72, 0.83, 0.55);
uniform float tint_amount : hint_range(0.0, 1.0) = 0.35;

varying float instance_tint;


void vertex() {
	// The instance's own origin. Identical for every vertex of one plant,
	// which is exactly the property the phase needs.
	vec3 anchor = MODEL_MATRIX[3].xyz;

	// Two irrational-ish multipliers so a grid-aligned scatter does not land
	// neighbouring plants on the same phase.
	float phase = anchor.x * 0.73 + anchor.z * 0.94 + INSTANCE_CUSTOM.x * TAU;
	instance_tint = INSTANCE_CUSTOM.y;

	float anchor_height = anchor_fraction * model_height;
	float height = max(VERTEX.y - anchor_height, 0.0);
	float span = max(model_height - anchor_height, 0.0001);
	float lever = pow(clamp(height / span, 0.0, 1.0), stiffness);

	float sway = sin(TIME * sway_hz * TAU + phase);
	// The flutter is additionally offset along the mesh's own X so opposite
	// sides of a canopy are not in step, which is what stops a wide tree
	// looking like a rigid cutout rocking.
	float flutter = sin(TIME * flutter_hz * TAU + phase * 3.1 + VERTEX.x * 2.3);

	vec2 push = normalize(wind_direction) * lever * model_height
		* (sway * sway_fraction + flutter * flutter_fraction);
	VERTEX.xz += push;
}


void fragment() {
	ALBEDO = mix(COLOR.rgb, tint_toward, instance_tint * tint_amount);
	ROUGHNESS = roughness_value;
	SPECULAR = specular_value;
	METALLIC = 0.0;
}

shader_type spatial;
render_mode diffuse_burley;
uniform sampler2D stone_top : source_color, filter_linear_mipmap_anisotropic, repeat_enable;
uniform sampler2D cliff_face : source_color, filter_linear_mipmap_anisotropic, repeat_enable;
varying vec3 placed;
varying vec3 facing;
void vertex() {
    placed = (MODEL_MATRIX * vec4(VERTEX,1.0)).xyz;
    facing = normalize(MODEL_NORMAL_MATRIX * NORMAL);
}
void fragment() {
    // Sample the rock's interior, not its silhouette. Mirrored tiling keeps
    // neighbouring samples continuous without painting fake boulders on floors.
    vec2 rock_uv = abs(fract(placed.xz * 0.10) * 2.0 - 1.0) * 0.42 + 0.29;
    vec4 top = texture(stone_top, rock_uv);
    vec4 side_x = texture(cliff_face, vec2(placed.z * 0.12, -placed.y * 0.12));
    vec4 side_z = texture(cliff_face, vec2(placed.x * 0.12, -placed.y * 0.12));
    float side_weight = abs(facing.x) / max(abs(facing.x) + abs(facing.z), 0.001);
    vec4 side = mix(side_z, side_x, side_weight);
    vec3 stone = mix(vec3(0.30,0.34,0.25), top.rgb, top.a);
    vec3 cliff = mix(vec3(0.28,0.31,0.24), side.rgb, side.a);
    ALBEDO = mix(cliff, stone, smoothstep(0.3,0.75,facing.y));
    ROUGHNESS = 0.91;
    SPECULAR = 0.16;
}

extends RefCounted
## Collision follows the large rock forms, excluding moss, coral and root fingers.
## Authored in each asset's normalized frame; visual meshes stay untouched.

func apply(world: Node3D) -> void:
	for asset: Node3D in world.get_node("SuppliedAssets").get_children():
		var id := String(asset.get_meta("source_asset", ""))
		if id not in ["reef_arch", "root_bridge", "crown_arch", "mossy_stone"]:
			continue
		var body := asset.get_node("AssetCollision") as StaticBody3D
		var bounds := AABB()
		var first := true
		for model: Node3D in asset.get_children():
			if not model.has_meta("cascade_asset_instance"): continue
			for mesh: MeshInstance3D in model.find_children("*", "MeshInstance3D", true, false):
				var pose := relative_pose(mesh, asset)
				var box := pose * mesh.get_aabb()
				bounds = box if first else bounds.merge(box)
				first = false
		if first: continue
		for child: Node in body.get_children():
			body.remove_child(child)
			child.free()
		if id == "mossy_stone":
			rock(body, bounds, asset)
		else:
			arch(body, bounds, id)
		asset.set_meta("collision_profile", "smooth_structure_v1")
		for child: Node in body.get_children(): child.owner = world

func relative_pose(node: Node3D, ancestor: Node3D) -> Transform3D:
	var pose := node.transform
	var parent := node.get_parent()
	while parent != ancestor and parent is Node3D:
		pose = (parent as Node3D).transform * pose
		parent = parent.get_parent()
	return pose

func hull(body: StaticBody3D, label: String, points: PackedVector3Array) -> void:
	var shape := ConvexPolygonShape3D.new()
	shape.points = points
	shape.margin = 0.01
	var collider := CollisionShape3D.new()
	collider.name = label + "_%02d" % body.get_child_count()
	collider.shape = shape
	body.add_child(collider)

func rock(body: StaticBody3D, b: AABB, asset: Node3D) -> void:
	var top := b.position.y + b.size.y * 0.86
	if asset.has_meta("landing_support_y"):
		top = float(asset.get_meta("landing_support_y")) - asset.position.y
	var points := PackedVector3Array()
	# One solid hull, a level crown and a broad bevel: no triangle seams or leaves.
	for ring: Vector2 in [Vector2(b.position.y, 0.88), Vector2(top - minf(0.18, b.size.y * 0.15), 0.94), Vector2(top, 0.79)]:
		for i in range(16):
			var angle := TAU * float(i) / 16.0
			points.append(Vector3(b.get_center().x + cos(angle) * b.size.x * 0.5 * ring.y, ring.x, b.get_center().z + sin(angle) * b.size.z * 0.5 * ring.y))
	hull(body, "SmoothRock", points)

func arch(body: StaticBody3D, b: AABB, id: String) -> void:
	var width := b.size.x
	var inner := width * (0.245 if id == "reef_arch" else 0.27)
	var spring := b.position.y + b.size.y * 0.40
	var rise := b.size.y * 0.26
	var outer := width * 0.43
	var roof := b.position.y + b.size.y * 0.89
	var depth := b.size.z * 0.35
	var center := b.get_center()
	# Wooden bridges have four separate feet and open sides. Never turn those
	# side openings into a long invisible wall beneath the canopy.
	var spans: Array[Vector2] = [Vector2(-depth, depth)]
	if id != "reef_arch":
		spans = [Vector2(-depth, -depth * 0.58), Vector2(depth * 0.58, depth)]
	for span: Vector2 in spans:
		arch_span(body, b, inner, spring, rise, outer, roof, center, width, span)

func arch_span(body: StaticBody3D, b: AABB, inner: float, spring: float, rise: float, outer: float, roof: float, center: Vector3, width: float, span: Vector2) -> void:
	var depth := (span.y - span.x) * 0.5
	var middle := (span.x + span.y) * 0.5
	# The entrance flares outward at both ends, so oblique approaches don't hook
	# on square jambs. The opening remains hollow at every depth.
	for side: float in [-1.0, 1.0]:
		var points := PackedVector3Array()
		for z: float in [-depth, -depth * 0.78, depth * 0.78, depth]:
			var inset := 0.15 * width if absf(z) > depth * 0.9 else 0.0
			for p: Vector2 in [Vector2(inner + inset, b.position.y), Vector2(outer, b.position.y), Vector2(outer, spring), Vector2(inner + inset, spring)]:
				points.append(arch_point(center, b, p.x * side, p.y, z + middle))
		hull(body, "PierLeft" if side < 0 else "PierRight", points)
	# Adjacent convex wedges describe a continuous rounded vault; a single convex
	# hull would incorrectly seal the tunnel.
	for i in range(8):
		var a := PI * float(i) / 8.0
		var c := PI * float(i + 1) / 8.0
		var points := PackedVector3Array()
		for z: float in [-depth, -depth * 0.65, depth * 0.65, depth]:
			var mouth := 0.14 * width if absf(z) > depth * 0.9 else 0.0
			for p: Vector2 in [Vector2(cos(a) * (inner + mouth), spring + sin(a) * rise + mouth * 0.45), Vector2(cos(c) * (inner + mouth), spring + sin(c) * rise + mouth * 0.45), Vector2(cos(c) * outer, spring + sin(c) * (roof - spring)), Vector2(cos(a) * outer, spring + sin(a) * (roof - spring))]:
				points.append(arch_point(center, b, p.x, p.y, z + middle))
		hull(body, "Vault%02d" % i, points)

func arch_point(center: Vector3, b: AABB, x: float, y: float, z: float) -> Vector3:
	# The scanned arch rises inward from its four broad feet. A straight
	# extrusion would project an invisible wall in front of the visible crown.
	var height := clampf((y - b.position.y) / b.size.y, 0.0, 1.0)
	return Vector3(center.x + x, y, center.z + z * (1.0 - height * 0.65))

