class_name LagoonStream
extends WaterVolume

const CAMERA_HINT_ID := "lagoon_downstream"
var _camera_rig: CameraRig

func _ready() -> void:
	explicit_surface = true
	shallow_wading_enabled = true
	depth_lighting_enabled = false
	water_priority = 30
	current_velocity = Vector3(0,-0.45,-3.2)
	if get_child_count() == 0:
		_build()
	super._ready()
	if not Engine.is_editor_hint():
		add_to_group("lighting_enclosures")

func surface_at(point: Vector3) -> float:
	return to_global(LagoonStreamPath.at_z(to_local(point).z)).y

func surface_slope_at(point: Vector3) -> Vector2:
	if to_local(point).z < -52.0:
		return Vector2.ZERO
	var direction: Vector3 = LagoonStreamPath.tangent(to_local(point).z)
	return Vector2(0,direction.y/minf(-0.001,direction.z))

func enclosure_at(point: Vector3) -> float:
	var p: Vector3 = to_local(point) if is_inside_tree() else point-position
	var center: Vector3 = LagoonStreamPath.at_z(p.z)
	if p.z > -9.0 or p.z < -53.0 or absf(p.x-center.x) > 3.3:
		return 0.0
	if p.y < center.y-2.8 or p.y > center.y+3.5:
		return 0.0
	return LagoonStreamPath.enclosure(p.z)

func contains_point(point: Vector3, margin: float = 0.0) -> bool:
	var p: Vector3 = to_local(point) if is_inside_tree() else point-position
	if p.z > -8.95+margin or p.z < -56.0-margin:
		return false
	var center: Vector3 = LagoonStreamPath.at_z(p.z)
	return absf(p.x-center.x) < LagoonStreamPath.HALF_WIDTH+margin and p.y > center.y-2.8 and p.y < center.y+0.85

func flow_at(point: Vector3) -> Vector3:
	if not contains_point(point):
		return Vector3.ZERO
	var p: Vector3 = to_local(point)
	var center: Vector3 = LagoonStreamPath.at_z(p.z)
	var direction: Vector3 = LagoonStreamPath.tangent(maxf(-51.8,p.z))
	if p.z < -52.0:
		direction = Vector3.FORWARD
	var strength: float = lerpf(1.8,3.4,smoothstep(9.0,15.0,-p.z))
	strength *= lerpf(1.0,0.24,smoothstep(48.0,52.0,-p.z))
	strength *= 1.0-smoothstep(53.0,56.0,-p.z)
	var result: Vector3 = direction*strength
	# A gentle cross-stream correction keeps a drifting swimmer off the banks.
	result.x += clampf((center.x-p.x)*1.1,-1.4,1.4)
	return global_basis*result

func _physics_process(_delta: float) -> void:
	if Engine.is_editor_hint():
		return
	var body := get_tree().get_first_node_in_group("player") as AxolotlBody
	# Curved containment is narrower than its overlapping broad-phase boxes.
	# Reconcile the analytical bank when a capsule moves within those boxes.
	if body != null and contains_point(body.global_position,0.55) and overlaps_body(body) and not _bodies.has(body):
		super._on_body_entered(body)
	if body == null or body.get_camera() == null:
		return
	_camera_rig = body.get_camera().get_rig()
	if contains_point(body.global_position,0.5):
		var hint := CameraHint.new(CAMERA_HINT_ID,40)
		hint.set_distance(4.5)
		hint.set_pitch_deg(28.0)
		_camera_rig.get_hint_stack().add(hint)
	else:
		_camera_rig.get_hint_stack().remove(CAMERA_HINT_ID)

func _on_body_entered(body: Node3D) -> void:
	if contains_point(body.global_position,0.55):
		super._on_body_entered(body)

func _exit_tree() -> void:
	release_camera_hint()
	super._exit_tree()

func release_camera_hint() -> void:
	if _camera_rig != null:
		_camera_rig.get_hint_stack().remove(CAMERA_HINT_ID)

func _build() -> void:
	var shell := SurfaceTool.new()
	var collision_shell := SurfaceTool.new()
	var water := SurfaceTool.new()
	shell.begin(Mesh.PRIMITIVE_TRIANGLES)
	collision_shell.begin(Mesh.PRIMITIVE_TRIANGLES)
	water.begin(Mesh.PRIMITIVE_TRIANGLES)
	var length: float = LagoonStreamPath.curve().get_baked_length()
	var segments: int = ceili(length/0.6)
	for i: int in segments:
		var d0: float = length*float(i)/segments
		var d1: float = length*float(i+1)/segments
		var a: Vector3 = LagoonStreamPath.point(d0)
		var b: Vector3 = LagoonStreamPath.point(d1)
		var right: Vector3 = _right_at(a.z)
		var next_right: Vector3 = _right_at(b.z)
		for j: int in 32:
			var angle0: float = TAU*float(j)/32
			var angle1: float = TAU*float(j+1)/32
			var points: Array[Vector3] = [_wall_point(a,right,angle0,d0),_wall_point(a,right,angle1,d0),_wall_point(b,next_right,angle0,d1),_wall_point(b,next_right,angle1,d1)]
			var collision_points: Array[Vector3] = [_wall_point(a,right,angle0,d0,true),_wall_point(a,right,angle1,d0,true),_wall_point(b,next_right,angle0,d1,true),_wall_point(b,next_right,angle1,d1,true)]
			var uvs: Array[Vector2] = [Vector2(angle0*1.1,d0*0.36),Vector2(angle1*1.1,d0*0.36),Vector2(angle0*1.1,d1*0.36),Vector2(angle1*1.1,d1*0.36)]
			for corner: int in [0,2,1,1,2,3]:
				var angle: float = angle0 if corner%2 == 0 else angle1
				shell.set_normal(-((right if corner < 2 else next_right)*cos(angle)+Vector3.UP*sin(angle)))
				shell.set_uv(uvs[corner])
				shell.add_vertex(points[corner])
				collision_shell.add_vertex(collision_points[corner])
		var water_points: Array[Vector3] = [a-right*2.9,a+right*2.9,b-next_right*2.9,b+next_right*2.9]
		for corner: int in [0,2,1,1,2,3]:
			water.set_normal(Vector3.UP)
			water.set_uv(Vector2(-2.9 if corner%2 == 0 else 2.9,-d0 if corner < 2 else -d1))
			water.add_vertex(water_points[corner])
		if i%3 == 0:
			var shape := BoxShape3D.new()
			shape.size = Vector3(5.3,5.5,2.2)
			var collision := CollisionShape3D.new()
			collision.shape = shape
			collision.position = a+Vector3.DOWN*1.5
			collision.rotation.y = atan2(-(b-a).x,-(b-a).z)
			add_child(collision)
	var outlet_shape := BoxShape3D.new()
	outlet_shape.size = Vector3(5.3,5.5,4.5)
	var outlet_collision := CollisionShape3D.new()
	outlet_collision.shape = outlet_shape
	outlet_collision.position = LagoonStreamPath.exit_position()+Vector3(0,-1.5,-2)
	add_child(outlet_collision)
	shell.generate_tangents()
	var shell_mesh: ArrayMesh = shell.commit()
	var original := LagoonRockKit.model("bank_rock")["material"] as BaseMaterial3D
	var stone := ShaderMaterial.new()
	stone.shader = preload("res://hub/lagoon_stream_rock.gdshader")
	stone.set_shader_parameter("color_map",original.albedo_texture)
	stone.set_shader_parameter("normal_map",original.normal_texture)
	stone.set_shader_parameter("roughness_map",original.roughness_texture)
	var backing := StandardMaterial3D.new()
	backing.albedo_color = Color("414a48")
	backing.roughness = 0.86
	backing.cull_mode = BaseMaterial3D.CULL_DISABLED
	_visual("CaveBacking",shell_mesh,backing)
	var lining := MultiMeshInstance3D.new()
	lining.name = "TexturedCave"
	lining.multimesh = _rock_lining(length)
	lining.material_override = stone
	add_child(lining)
	var solid := StaticBody3D.new()
	solid.name = "CaveWalls"
	solid.collision_layer = 1 | SceneOccluderProbe.CAMERA_COLLISION_LAYER_MASK
	var collision := CollisionShape3D.new()
	# A fitted inner shell blocks bodies and cameras without cooking every rock.
	var shape := collision_shell.commit().create_trimesh_shape()
	shape.backface_collision = true
	collision.shape = shape
	solid.add_child(collision)
	add_child(solid)
	var material := (load("res://core/rendering/water_surface.tres") as ShaderMaterial).duplicate() as ShaderMaterial
	material.set_shader_parameter("mesh_is_surface",true)
	material.set_shader_parameter("flow_uses_uv",true)
	material.set_shader_parameter("flow_exit_z",LagoonStreamPath.exit_position().z)
	material.set_shader_parameter("flow_velocity",Vector2(0,-3.2))
	material.set_shader_parameter("wave_height",0.045)
	material.set_shader_parameter("turbulence",0.5)
	_visual("ContinuousWater",water.commit(),material).cast_shadow = GeometryInstance3D.SHADOW_CASTING_SETTING_OFF
	for distance: float in [8.0,15.5,23.0,30.5,37.0]:
		var light := OmniLight3D.new()
		light.name = "MossLight%d" % int(distance)
		light.position = LagoonStreamPath.point(distance)+Vector3(1.65,0.8,0)
		light.light_color = Color("6adeae")
		light.light_energy = 1.15
		light.omni_range = 5.5
		add_child(light)
	for distance: float in [12.0,31.0]:
		var reflection := ReflectionProbe.new()
		reflection.position = LagoonStreamPath.point(distance)+Vector3.UP
		reflection.size = Vector3(11,10,22)
		reflection.max_distance = 18.0
		reflection.box_projection = true
		add_child(reflection)

func _right_at(z: float) -> Vector3:
	var direction: Vector3 = LagoonStreamPath.tangent(z)
	return Vector3(-direction.z,0,direction.x).normalized()

func _rock_lining(length: float) -> MultiMesh:
	var mesh := LagoonRockKit.model("bank_rock")["mesh"] as ArrayMesh
	var random := RandomNumberGenerator.new()
	random.seed = 18721
	var rings: int = ceili(length/2.4)
	var instances := MultiMesh.new()
	instances.transform_format = MultiMesh.TRANSFORM_3D
	instances.mesh = mesh
	instances.instance_count = rings*9
	for ring: int in rings:
		var distance: float = length*(ring+0.5)/rings
		var center: Vector3 = LagoonStreamPath.point(distance)
		var right: Vector3 = _right_at(center.z)
		for sector: int in 9:
			var angle: float = TAU*(sector+0.5*(ring%2))/9.0
			var radial: Vector3 = right*cos(angle)+Vector3.UP*sin(angle)
			var across: Vector3 = -right*sin(angle)+Vector3.UP*cos(angle)
			var inward: Vector3 = -radial
			var basis := Basis(across,inward,across.cross(inward))
			basis *= Basis(Vector3.UP,random.randf_range(-0.22,0.22))
			var size := Vector3(random.randf_range(1.0,1.35),random.randf_range(0.48,0.7),random.randf_range(1.4,1.7))
			var at: Vector3 = center+right*cos(angle)*3.12+Vector3.UP*(0.65+sin(angle)*3.28)
			instances.set_instance_transform(ring*9+sector,Transform3D(basis.scaled_local(size),at))
	return instances

func _wall_point(center: Vector3, right: Vector3, angle: float, distance: float, collision: bool = false) -> Vector3:
	var variation: float = 0.11*sin(angle*5.0+distance*1.3)+0.065*sin(angle*11-distance*2.4)
	# The backing must sit outside the textured lining, not obscure its faces.
	var horizontal: float = (2.4 if collision else 3.5)+variation
	var vertical: float = (2.65 if collision else 3.55)+variation
	return center+right*cos(angle)*horizontal+Vector3.UP*(0.65+sin(angle)*vertical)

func _visual(label: String, mesh: Mesh, material: Material) -> MeshInstance3D:
	var visual := MeshInstance3D.new()
	visual.name = label
	visual.mesh = mesh
	visual.material_override = material
	add_child(visual)
	return visual

class_name CameraHintStack
extends RefCounted

## The active camera hints and how they compose (REQ-005 AC-3).
##
## Resolution is by DECLARED PRIORITY, never by enter order. That is the whole
## reason this is a stack object rather than a "last one in wins" variable: a
## player can enter two overlapping volumes in either order, and a world whose
## framing depended on which way they walked in would be unreproducible to author
## and impossible to test.
##
## Equal priorities tie-break on hint id, so even a world that forgets to give
## its volumes distinct priorities gets one deterministic answer rather than a
## coin flip.

var _hints: Array[CameraHint] = []


## Adds or REPLACES the hint with this id. Replacing rather than stacking means a
## volume re-entered after a reload cannot accumulate duplicates of itself.
## Refuses an empty id, since an unnameable hint could never be removed again.
func add(hint: CameraHint) -> bool:
	if hint == null or hint.id.is_empty():
		return false
	remove(hint.id)
	_hints.append(hint)
	return true


func remove(hint_id: String) -> bool:
	for index: int in range(_hints.size()):
		if _hints[index].id == hint_id:
			_hints.remove_at(index)
			return true
	return false


func clear() -> void:
	_hints.clear()


func size() -> int:
	return _hints.size()


func has(hint_id: String) -> bool:
	for hint: CameraHint in _hints:
		if hint.id == hint_id:
			return true
	return false


func get_hint_ids() -> PackedStringArray:
	var out := PackedStringArray()
	for hint: CameraHint in _hints:
		out.append(hint.id)
	out.sort()
	return out


## The framing after every active hint has been applied. [param base] is left
## untouched; the caller gets a fresh object.
##
## Applied lowest priority first so the HIGHEST priority writes last and wins.
func resolve(base: CameraFraming) -> CameraFraming:
	var out := base.copy()

	var ordered := _hints.duplicate()
	ordered.sort_custom(func(a: CameraHint, b: CameraHint) -> bool:
		if a.priority != b.priority:
			return a.priority < b.priority
		return a.id < b.id)

	for hint: CameraHint in ordered:
		hint.apply_to(out)

	return out

@tool
extends WaterVolume
const Profile = preload("res://dev/living_cascade/chute_profile.gd")

func surface_at(point: Vector3) -> float:
	return float(Profile.sample((get_parent() as Node3D).to_local(point))["surface"]) + (get_parent() as Node3D).global_position.y

func surface_slope_at(point: Vector3) -> Vector2:
	return Profile.sample((get_parent() as Node3D).to_local(point))["slope"] as Vector2

func flow_at(point: Vector3) -> Vector3:
	if not contains_point(point):
		return Vector3.ZERO
	var local_point := (get_parent() as Node3D).to_local(point)
	var row := Profile.sample(local_point)
	var s := float(row["s"])
	# A still approach pocket prevents surface-following velocity from pushing
	# a blocked player down the bar. Diving remains an explicit player action.
	var bar_s := float(Profile.sample(Vector3(-12,3.6,-116))["s"])
	if absf(s-bar_s)<2.8 and local_point.y>2.15:
		return Vector3.ZERO
	# Smooth entry/exit current, with still side eddies inside the retaining banks.
	var speed := smoothstep(0,2,s) * smoothstep(0,4,Profile.distances.back()-s)
	speed *= 1.0-smoothstep(2.0,3.0,absf(float(row["lateral"])))
	return (row["direction"] as Vector3)*speed

class_name HeroActionClips
extends RefCounted

## Refine the imported actions without rewriting the mesh, skin, or source GLB.
static func install(player: AnimationPlayer, skeleton: Skeleton3D) -> void:
	for action: String in ["spin","roll","whack"]:
		if not player.has_animation(action):
			continue
		var source := player.get_animation(action)
		var clip := Animation.new()
		clip.length = 0.55 if action == "spin" else (0.38 if action == "roll" else 0.5)
		for track: int in source.get_track_count():
			if source.track_get_type(track) != Animation.TYPE_ROTATION_3D:
				continue
			var path := source.track_get_path(track)
			var bone_name: String = path.get_subname(0)
			var bone: int = skeleton.find_bone(bone_name)
			if bone < 0:
				continue
			var rest: Quaternion = skeleton.get_bone_rest(bone).basis.get_rotation_quaternion()
			var target: int = clip.add_track(Animation.TYPE_ROTATION_3D)
			clip.track_set_path(target,path)
			for sample: int in 65:
				var phase: float = float(sample)/64.0
				var rotation: Quaternion = (rest*pose(action,bone_name,phase)).normalized()
				if action == "whack" and bone_name == "root":
					# Turn on the ground plane, not the rig's slightly tilted local Z axis.
					rotation = Quaternion(Vector3.UP,whack_yaw(phase))*rest
				clip.rotation_track_insert_key(target,phase*clip.length,rotation)
		var library := player.get_animation_library(player.find_animation_library(source))
		library.remove_animation(action)
		library.add_animation(action,clip)

static func pose(action: String, bone: String, phase: float) -> Quaternion:
	var u: float = clampf(phase,0.0,1.0)
	var angles := Vector3.ZERO
	var side: float = 1.0 if bone.ends_with("l") else -1.0
	if action in ["spin","roll"]:
		var tuck: float = smoothstep(0.0,0.12,u)*(1.0-smoothstep(0.82,1.0,u))
		if bone == "root":
			# Dense quaternion keys retain every revolution; easing softens entry/exit.
			if action == "spin":
				angles.y = (u-sin(TAU*u)/TAU)*TAU*2.0
			else:
				# The land dodge stays low and slides; it no longer tumbles through the floor.
				angles.z = sin(u*TAU)*0.08*tuck
		elif bone.begins_with("leg_"):
			angles = Vector3(0.18*tuck,0,-0.65*side*tuck)
		elif bone.begins_with("tail_"):
			var index: float = float(bone.trim_prefix("tail_"))
			angles.z = sin(u*TAU-index*0.45)*0.07*tuck
		elif bone.begins_with("gill_"):
			angles.z = side*0.10*tuck
	else:
		var swing: float = whip(u)
		if bone.begins_with("tail_"):
			var index: float = float(bone.trim_prefix("tail_"))
			angles.z = whip(maxf(0,u-(index-1)*0.028))*[1.20,0.28,0.10][int(index)-1]
		elif bone == "root":
			angles.z = whack_yaw(u)
		elif bone == "spine":
			angles.z = swing*0.65
		elif bone == "head":
			angles.z = swing*0.45
		elif bone.begins_with("leg_"):
			angles.z = -swing*side*0.06
	return Quaternion.from_euler(angles)

static func whip(u: float) -> float:
	if u < 0.12:
		return lerpf(0,-0.65,smoothstep(0,0.12,u))
	if u < 0.32:
		return lerpf(-0.65,1.0,smoothstep(0.12,0.32,u))
	if u < 0.48:
		return lerpf(1.0,0.70,smoothstep(0.32,0.48,u))
	return lerpf(0.70,0,smoothstep(0.48,0.94,u))

static func whack_yaw(phase: float) -> float:
	var swing: float = whip(phase)
	# Small anticipation, then a hip-led pivot carrying the long tail in front.
	return -swing*(1.80 if swing > 0.0 else 0.30)

static func whack_root_position(rest_position: Vector3, phase: float) -> Vector3:
	# Orbit the hips about the character centre; rotating at the tail root alone
	# can only curl the fin beside the body and cannot reach a forward target.
	return rest_position.rotated(Vector3.UP,whack_yaw(phase))

extends RefCounted
## A 32-beat shore dance at the same 112 BPM as crayfish_groove.wav.
const BPM := 112.0
const LENGTH := 32.0 * 60.0 / BPM
static func install(player: AnimationPlayer, skeleton: Skeleton3D, feet: Dictionary) -> void:
	var clip:=Animation.new();clip.length=LENGTH
	var source:=player.get_animation("idle")
	var path_to_skeleton:=NodePath("")
	for track: int in source.get_track_count():
		var path:=source.track_get_path(track)
		if path.get_subname_count()>0:
			path_to_skeleton=NodePath(path.get_concatenated_names());break
	# Other clips must explicitly reset the translation introduced by this action.
	for name: StringName in player.get_animation_list():
		if name==&"dance":continue
		var other:=player.get_animation(name)
		var path:=NodePath(String(path_to_skeleton)+":root")
		if other.find_track(path,Animation.TYPE_POSITION_3D)<0:
			var track:=other.add_track(Animation.TYPE_POSITION_3D)
			other.track_set_path(track,path)
			other.position_track_insert_key(track,0.,skeleton.get_bone_rest(0).origin)
	var tracks: Dictionary={}
	for bone: int in skeleton.get_bone_count():
		var index:=clip.add_track(Animation.TYPE_ROTATION_3D)
		clip.track_set_path(index,NodePath(String(path_to_skeleton)+":"+skeleton.get_bone_name(bone)))
		tracks[bone]=index
	var root_track:=clip.add_track(Animation.TYPE_POSITION_3D)
	clip.track_set_path(root_track,NodePath(String(path_to_skeleton)+":root"))
	for sample: int in 513:
		var phase:=float(sample)/512.0
		var pose:=sample_pose(skeleton,feet,phase)
		for bone: int in skeleton.get_bone_count():clip.rotation_track_insert_key(int(tracks[bone]),phase*LENGTH,(pose[bone] as Transform3D).basis.get_rotation_quaternion().normalized())
		clip.position_track_insert_key(root_track,phase*LENGTH,(pose[0] as Transform3D).origin)
	var library:=player.get_animation_library(player.find_animation_library(source))
	if library.has_animation(&"dance"):library.remove_animation(&"dance")
	library.add_animation(&"dance",clip)

static func sample_pose(skeleton: Skeleton3D, feet: Dictionary, phase: float) -> Array[Transform3D]:
	var beat:=phase*32.0
	var stand:=smoothstep(0.,2.,beat)*(1.0-smoothstep(30.,32.,beat))
	var groove:=smoothstep(2.,3.,beat)*(1.0-smoothstep(29.,30.,beat))
	var step:=sin(TAU*(beat-2.)/8.)*.12*groove
	var bounce:=absf(sin(PI*beat))*.045*groove
	var twist:=sin(TAU*beat/8.)*.14*groove
	var rest_root:=skeleton.get_bone_rest(0)
	var rise:=Quaternion(Vector3.UP,twist)*Quaternion(Vector3.RIGHT,.20*stand)
	var root_position:=rest_root.origin+Vector3(step,-.10*stand+bounce*.30,0.)
	var local: Array[Transform3D]=[]
	var global: Array[Transform3D]=[]
	for bone: int in skeleton.get_bone_count():
		var name:=skeleton.get_bone_name(bone)
		var rest:=skeleton.get_bone_rest(bone)
		var parent:=skeleton.get_bone_parent(bone)
		var parent_pose:=global[parent] if parent>=0 else Transform3D.IDENTITY
		var pose:=rest
		if name=="root":pose=Transform3D(Basis(rise)*rest.basis,root_position)
		elif name=="spine":
			# Rise through the waist; the pelvis stays over the supporting hind feet.
			var desired:=Basis(Quaternion(Vector3.UP,twist)*Quaternion(Vector3.RIGHT,1.10*stand))*skeleton.get_bone_global_rest(bone).basis
			pose.basis=parent_pose.basis.inverse()*desired
		elif name=="head":
			var desired:=Basis(Quaternion(Vector3.UP,twist*.5)*Quaternion(Vector3.RIGHT,.23*stand+.06*sin(TAU*beat)*groove))*skeleton.get_bone_global_rest(bone).basis
			pose.basis=parent_pose.basis.inverse()*desired
		elif name=="tail_1":
			var desired:=Basis(Quaternion(Vector3.UP,-.22*sin(TAU*beat/4.)*groove)*Quaternion(Vector3.RIGHT,-.035*stand))*skeleton.get_bone_global_rest(bone).basis
			pose.basis=parent_pose.basis.inverse()*desired
		elif name.begins_with("tail_"):
			pose.basis=rest.basis*Basis(Vector3.FORWARD,.08*sin(TAU*beat/4.-bone*.35)*groove)
		elif name.begins_with("leg_b") and feet.has(name):
			var side:=1.0 if name.ends_with("l") else -1.0
			var rest_tip:=skeleton.get_bone_global_rest(bone)*(feet[name] as Vector3)
			# Alternating side steps, heel taps, and a short forward/back shuffle.
			var lift:=maxf(0.,sin(PI*beat+side*PI*.5))*.11*groove
			var target:=rest_tip+Vector3(step*1.15,lift,sin(TAU*beat/4.+side)*.10*groove)
			var start:=parent_pose*rest.origin
			var from: Vector3=parent_pose.basis*rest.basis*(feet[name] as Vector3)
			var correction:=Basis(Quaternion(from.normalized(),(target-start).normalized()))
			pose.basis=parent_pose.basis.inverse()*correction*parent_pose.basis*rest.basis
		elif name.begins_with("leg_f"):
			var side:=1.0 if name.ends_with("l") else -1.0
			var desired:=Basis(Quaternion(Vector3.FORWARD,side*(.36*stand+.30*sin(PI*beat)*groove))*Quaternion(Vector3.RIGHT,-.2*stand))*skeleton.get_bone_global_rest(bone).basis
			pose.basis=parent_pose.basis.inverse()*desired
		elif name.begins_with("gill_"):
			pose.basis=rest.basis*Basis(Vector3.FORWARD,.06*sin(PI*beat)*groove)
		local.append(pose);global.append(parent_pose*pose)
	return local

extends SceneTree
const Visual = preload("res://core/enemies/visuals/fleet_enemy_visual.gd")
