extends Node3D
## Local habitat-aware wandering. The pickup Area moves with the visible animal.
enum Habitat { AUTO, SHORE, WATER }
@export var phase: float = 0.0
@export var habitat: Habitat = Habitat.AUTO
@export_range(.25,2.0) var roam_radius: float = 1.15
var _actor: Area3D
var _home:=Vector3.ZERO
var _goal:=Vector3.ZERO
var _time:=0.0
var _wait:=0.0
var _moving:=false
var _water:=false
var _initialized:=false
var _speed:=0.0
var _heading:=0.0
var _escape:=0.0
var _escape_cooldown:=0.0
var _stride:=0.0
var _normal:=Vector3.UP
var _rng:=RandomNumberGenerator.new()
var _waters: Array[WaterVolume]=[]
var _skeleton: Skeleton3D
var _bones: Dictionary={}
var _rest: Dictionary={}
var _axes: Dictionary={}
var _clearance:=SphereShape3D.new()

func _ready() -> void:
	position=Vector3.ZERO # Discard the old preview bob saved into scene instances.
	_actor=get_parent() as Area3D
	var skeletons:=find_children("*","Skeleton3D",true,false)
	if not skeletons.is_empty():
		_skeleton=skeletons[0] as Skeleton3D
		for i: int in _skeleton.get_bone_count():
			var name:=_skeleton.get_bone_name(i)
			_bones[name]=i;_rest[name]=_skeleton.get_bone_rest(i).basis.get_rotation_quaternion()
			_axes[name]=_skeleton.get_bone_global_rest(i).basis.inverse()
	_heading=phase*1.73
	_rng.seed=abs(int(phase*10007.0))+19427

func _physics_process(delta: float) -> void:
	_time+=delta
	if not _initialized and _time>.07:_initialize_habitat()
	if _initialized and _actor!=null:_wander(delta)
	_animate(delta)

func _initialize_habitat() -> void:
	for node: Node in get_tree().get_nodes_in_group("water_volumes"):
		if node is WaterVolume:_waters.append(node as WaterVolume)
	_home=_actor.global_position if _actor!=null else global_position
	_rng.seed=absi(hash(_home)+int(phase*10007.))+19427
	_water=habitat==Habitat.WATER or (habitat==Habitat.AUTO and _water_at(_home)!=null)
	_clearance.radius=.28 if _water else .15
	_goal=_home;_wait=_rng.randf_range(.4,2.4)
	if not _water and _actor!=null:
		var ground:=_ground_at(_home)
		if not ground.is_empty():
			_actor.global_position.y=(ground["position"] as Vector3).y-.012
			_home=_actor.global_position;_normal=ground["normal"]
	for mesh: MeshInstance3D in find_children("*","MeshInstance3D",true,false):
		mesh.set_instance_shader_parameter("wetness",1.0 if _water else 0.0)
	_initialized=true

func _water_at(point: Vector3) -> WaterVolume:
	for water: WaterVolume in _waters:
		if is_instance_valid(water) and water.contains_point(point,-.18) and point.y<water.surface_at(point)-.10:return water
	return null

func _excluded() -> Array[RID]:
	var out: Array[RID]=[]
	var hero:=get_tree().get_first_node_in_group("player") as CollisionObject3D
	if hero!=null:out.append(hero.get_rid())
	return out

func _ground_at(point: Vector3) -> Dictionary:
	var query:=PhysicsRayQueryParameters3D.create(point+Vector3.UP*.5,point+Vector3.DOWN*.85,1,_excluded())
	var hit:=get_world_3d().direct_space_state.intersect_ray(query)
	if hit.is_empty() or not hit["collider"] is StaticBody3D or (hit["normal"] as Vector3).y<.82:return {}
	return hit

func _safe_point(point: Vector3) -> Dictionary:
	if Vector2(point.x-_home.x,point.z-_home.z).length()>roam_radius+.001:return {}
	if _water:
		if absf(point.y-_home.y)>.26 or _water_at(point)==null:return {}
	else:
		var ground:=_ground_at(point)
		if ground.is_empty():return {}
		point.y=(ground["position"] as Vector3).y-.012
		if absf(point.y-_home.y)>.28 or _water_at(point+Vector3.DOWN*.13)!=null:return {}
		# Four feet-support samples reject banks and narrow rock lips.
		for offset: Vector3 in [Vector3(.21,0,.22),Vector3(-.21,0,.22),Vector3(.21,0,-.22),Vector3(-.21,0,-.22)]:
			var edge:=_ground_at(point+offset)
			if edge.is_empty() or absf((edge["position"] as Vector3).y-point.y)>.14:return {}
	var query:=PhysicsShapeQueryParameters3D.new();query.shape=_clearance;query.collision_mask=1;query.exclude=_excluded();query.transform.origin=point+Vector3.UP*(.12 if _water else .18)
	if not get_world_3d().direct_space_state.intersect_shape(query,1).is_empty():return {}
	return {"point":point}

func _clear_path(from: Vector3,to: Vector3) -> bool:
	var query:=PhysicsShapeQueryParameters3D.new();query.shape=_clearance;query.collision_mask=1;query.exclude=_excluded();query.transform.origin=from+Vector3.UP*(.12 if _water else .18);query.motion=to-from
	var travel:=get_world_3d().direct_space_state.cast_motion(query)
	return travel[0]>.995

func _choose_goal() -> void:
	for attempt: int in 14:
		var angle:=_rng.randf()*TAU;var radius:=sqrt(_rng.randf())*roam_radius*.9
		var candidate:=_home+Vector3(cos(angle)*radius,_rng.randf_range(-.19,.19) if _water else 0.,sin(angle)*radius)
		var result:=_safe_point(candidate)
		if result.is_empty():continue
		candidate=result["point"]
		if _actor.global_position.distance_to(candidate)<.22 or not _clear_path(_actor.global_position,candidate):continue
		_goal=candidate;_moving=true;return
	_wait=_rng.randf_range(.7,1.5)

func _wander(delta: float) -> void:
	_escape_cooldown=maxf(0.,_escape_cooldown-delta)
	_escape=maxf(0.,_escape-delta)
	var hero:=get_tree().get_first_node_in_group("player") as Node3D
	var distance:=hero.global_position.distance_to(_actor.global_position) if hero!=null else INF
	# Never turn a friendly pickup into a frustrating chase at collection distance.
	if distance<.95:
		_moving=false;_wait=maxf(_wait,.65)
	elif _water and distance<1.9 and _escape_cooldown<=0.:
		var away:=(_actor.global_position-hero.global_position).normalized()
		var result:=_safe_point(_actor.global_position+away*.38)
		if not result.is_empty() and _clear_path(_actor.global_position,result["point"]):
			_goal=result["point"];_moving=true;_escape=.50;_escape_cooldown=7.
	if not _moving:
		_speed=move_toward(_speed,0.,delta*1.4);_wait-=delta
		if _wait<=0. and distance>=.95:_choose_goal()
		return
	var difference:=_goal-_actor.global_position
	if difference.length()<.045:
		_moving=false;_wait=_rng.randf_range(1.0,3.3);return
	var desired_speed:=.27 if _water else .17
	if _escape>0.:desired_speed=.70
	_speed=move_toward(_speed,desired_speed,delta*.8)
	var step:=difference.normalized()*minf(_speed*delta,difference.length())
	var candidate:=_safe_point(_actor.global_position+step)
	if candidate.is_empty() or not _clear_path(_actor.global_position,candidate.get("point",_actor.global_position)):
		_moving=false;_wait=.65;_speed=0.;return
	_actor.global_position=candidate["point"]
	var direction:=difference.normalized()*(-1. if _escape>0. else 1.)
	_heading=rotate_toward(_heading,atan2(-direction.x,-direction.z),delta*1.8)
	if not _water:
		var ground:=_ground_at(_actor.global_position)
		if not ground.is_empty():_normal=_normal.lerp(ground["normal"],1.-exp(-delta*8.)).normalized()

func _rotate_bone(name: String,axis: Vector3,angle: float) -> void:
	if not _bones.has(name):return
	var local_axis: Vector3=(_axes[name] as Basis)*axis
	_skeleton.set_bone_pose_rotation(int(_bones[name]),(_rest[name] as Quaternion)*Quaternion(local_axis.normalized(),angle))

func _animate(delta: float) -> void:
	_stride+=delta*(_speed*36. if not _water else 4.2+_speed*5.)
	var forward:=Vector3(-sin(_heading),0,-cos(_heading))
	var up:=Vector3.UP if _water else _normal
	var right:=forward.cross(up).normalized();basis=Basis(right,up,right.cross(up)).orthonormalized().scaled(scale)
	# Small swimming pitch comes from the tail cycle; shore bodies remain grounded.
	if _water:rotate_object_local(Vector3.RIGHT,sin(_time*1.6+phase)*.028)
	for side: String in ["L","R"]:
		var sign_value: float=1. if side=="L" else -1.
		for i: int in 4:
			var cycle:=_stride+float(i)*PI*.72+(PI if side=="R" else 0.)
			var swing:=sin(cycle)*(.17 if _water else .27)*clampf(_speed/.13,0.,1.)
			if _water:swing+=sin(cycle)*.085
			var bone:="Leg"+side+str(i)
			_rotate_bone(bone,Vector3.UP,swing)
			if _bones.has(bone):
				var lift:=maxf(0.,cos(cycle))*(.22 if _water else .18)*clampf(_speed/.10,0.,1.)
				var axis: Vector3=(_axes[bone] as Basis)*Vector3.FORWARD
				_skeleton.set_bone_pose_rotation(int(_bones[bone]),_skeleton.get_bone_pose_rotation(int(_bones[bone]))*Quaternion(axis.normalized(),sign_value*lift))
		var forage:=.5+.5*sin(_time*1.1+phase+sign_value)
		_rotate_bone("Claw"+side,Vector3.UP,sign_value*(.04+.09*sin(_time*1.7+phase+sign_value)))
		_rotate_bone("Pincer"+side,Vector3.UP,sign_value*(.035+.19*forage))
		_rotate_bone("Antenna"+side,Vector3.UP,sign_value*(.07*sin(_time*1.8+phase)+.045*sin(_time*3.1)))
		_rotate_bone("Eye"+side,Vector3.UP,.10*sin(_time*.75+phase+sign_value))
	for i: int in 6:
		var curl:=sin(_time*2.2+phase-float(i)*.45)*(.025 if _water else .006)
		if _escape>0.:curl+=sin((_escape/.5)*PI)*.19
		_rotate_bone("Tail%d"%i,Vector3.RIGHT,curl)

func is_swimming() -> bool:return _water
func home_position() -> Vector3:return _home
func movement_speed() -> float:return _speed

extends SceneTree
## Real input through the shipped player capsule, in both directions and off-center.
var world: Node3D
var body: AxolotlBody
var held: Dictionary = {}
var failures: PackedStringArray = []
var checks := 0
func _initialize() -> void: run.call_deferred()
func check(ok: bool, label: String) -> void:
	checks += 1
	if not ok: failures.append(label)
func key(code: Key, down: bool) -> void:
	if bool(held.get(code, false)) == down: return
	held[code] = down
	var event := InputEventKey.new()
	event.physical_keycode = code
	event.pressed = down
	Input.parse_input_event(event)
func release() -> void:
	for code: Key in [KEY_W, KEY_S, KEY_A, KEY_D, KEY_SPACE, KEY_SHIFT]: key(code, false)
func reset(p: Vector3) -> void:
	release()
	body.get_input_system().clear()
	body.clear_water_contacts()
	body.position = p
	body.velocity = Vector3.ZERO
	body.get_controller().set_velocity(Vector3.ZERO)
	body.get_controller().sync_body_position(p)
	body.resample_water_contacts()
	for i in range(3): await physics_frame
func travel(target: Vector3, swim: bool) -> bool:
	for i in range(420):
		var delta := target - body.position
		if Vector2(delta.x, delta.z).length() < 0.42 and (not swim or absf(delta.y) < 0.4):
			release()
			return true
		key(KEY_A, delta.x < -0.14); key(KEY_D, delta.x > 0.14)
		key(KEY_W, delta.z < -0.14); key(KEY_S, delta.z > 0.14)
		key(KEY_SPACE, swim and delta.y > 0.14); key(KEY_SHIFT, swim and delta.y < -0.14)
		await physics_frame
	release()
	for j in body.get_slide_collision_count():
		print("BLOCKED ", body.get_slide_collision(j).get_collider().get_path(), " target ", target)
	return false
func run() -> void:
	var stage := Node3D.new(); root.add_child(stage)
	world = load("res://worlds/coral_cove/world.tscn").instantiate() as Node3D
	stage.add_child(world)
	body = load("res://core/controller/axolotl_body.tscn").instantiate() as AxolotlBody
	stage.add_child(body)
	await physics_frame
	# Enemy AI isn't wired in this fixture; the separate combat regression covers it.
	for row: Array in [["S03_EntryTunnel", -1.6, 3.5, 0.65], ["S03_MiddleTunnel", -1.6, 3.5, 0.65], ["S03_ExitTunnel", -1.6, 3.5, 0.65], ["S03_GrottoArch", -1.6, 3.5, 0.65], ["S04_DiveArch", 2.1, 2.3, 0.3], ["S06_DiveTunnel", 1.7, 3.0, 0.65]]:
		var arch := world.get_node("SuppliedAssets/" + String(row[0])) as Node3D
		for offset: float in [-float(row[3]), 0.0, float(row[3])]:
			var a := arch.to_global(Vector3(offset, 0, float(row[2])))
			var b := arch.to_global(Vector3(offset, 0, -float(row[2])))
			# This is a pocket grotto, not a through tunnel: stop before its solid
			# back wall, which must continue containing the player.
			if row[0] == "S03_GrottoArch": b = arch.to_global(Vector3(offset, 0, -2.7))
			a.y = float(row[1]); b.y = float(row[1])
			for reverse: bool in [false, true]:
				await reset(b if reverse else a)
				var ok := await travel(a if reverse else b, true)
				check(ok, "%s lane %.2f reverse=%s stopped=%s" % [row[0], offset, reverse, body.position])
	for rock: Node3D in world.get_node("SuppliedAssets").get_children():
		if not rock.has_meta("landing_support_y"): continue
		var center := Vector3(rock.position.x, float(rock.get_meta("landing_support_y")) + 0.85, rock.position.z)
		for direction: Vector3 in [Vector3.RIGHT, Vector3.FORWARD, Vector3(1, 0, 1).normalized()]:
			await reset(center - direction * 0.85)
			var ok := await travel(center + direction * 0.85, false)
			check(ok and body.is_on_floor(), "rock crossing " + String(rock.name) + " " + str(direction))
	print("CASCADE COLLISION MOVEMENT: ", checks - failures.size(), "/", checks, " passed")
	for failure: String in failures: print("FAIL ", failure)
	release()
	stage.queue_free(); await process_frame
	quit(0 if failures.is_empty() else 1)

shader_type spatial;
render_mode cull_disabled;

uniform vec3 shallow_color : source_color = vec3(0.045, 0.68, 0.65);
uniform vec3 deep_color : source_color = vec3(0.008, 0.27, 0.39);
uniform bool cascade = false;
varying vec3 world_pos;

float hash(vec2 p) { vec3 q=fract(vec3(p.xyx)*0.1031); q+=dot(q,q.yzx+33.33); return fract((q.x+q.y)*q.z); }
float noise(vec2 p) {
    vec2 i = floor(p); vec2 f = fract(p); f = f * f * (3.0 - 2.0 * f);
    return mix(mix(hash(i), hash(i + vec2(1,0)), f.x), mix(hash(i + vec2(0,1)), hash(i + vec2(1,1)), f.x), f.y);
}
void vertex() {
    world_pos = (MODEL_MATRIX * vec4(VERTEX, 1.0)).xyz;
    if (!cascade) VERTEX.y += 0.017 * sin(world_pos.x * 3.5 + TIME * 1.2) * cos(world_pos.z * 3.0 - TIME);
}
void fragment() {
    vec2 p = world_pos.xz;
    float t = TIME;
    float depth = smoothstep(8.0, 0.0, length((p - vec2(0.0,-2.0)) * vec2(0.65,0.85)));
    vec2 cell_p=p*2.2+vec2(sin(p.y*2.7+t*0.45),cos(p.x*2.5-t*0.4))*0.6;
    vec2 cell=floor(cell_p), local=fract(cell_p);
    float nearest=8.0, second=8.0;
    for(int y=-1;y<=1;y++) for(int x=-1;x<=1;x++) {
        vec2 offset=vec2(float(x),float(y));
        vec2 point=vec2(hash(cell+offset),hash(cell+offset+19.0));
        point=0.5+0.4*sin(point*6.283+t*0.45);
        float d=length(offset+point-local);
        if(d<nearest) { second=nearest; nearest=d; } else { second=min(second,d); }
    }
    float caustic=1.0-smoothstep(0.015,0.065,second-nearest);
    vec3 col = mix(shallow_color, deep_color, depth * 0.8);
    col += vec3(0.08,0.16,0.13) * caustic * (1.0-depth*0.94) * smoothstep(0.22,0.6,noise(p*1.3));
    float foam = 0.0;
    if (cascade) {
        vec2 q = UV * vec2(48.0, 4.0) + vec2(0.0, -t * 3.8);
        float streak = noise(vec2(q.x, q.y * 0.24)) * noise(q * 1.5);
        foam = smoothstep(0.16, 0.48, streak) + pow(UV.y, 4.0) * 0.6;
        col = mix(vec3(0.01,0.27,0.4), vec3(0.85,0.97,1.0), clamp(foam,0.0,1.0));
    }
    ALBEDO = col;
    ROUGHNESS = cascade ? 0.26 : 0.19;
    METALLIC = 0.05;
    SPECULAR = 0.85;
    if (!cascade) {
        vec3 normal=normalize(vec3(0.1*sin(p.x*5.0+p.y*9.0+t*1.2),1.0,0.18*cos(p.y*14.0+sin(p.x*5.0)-t*1.4)));
        NORMAL=normalize((VIEW_MATRIX*vec4(normal,0.0)).xyz);
    }
    EMISSION = col * (cascade ? 0.14 : 0.035);
}

{
  "contractVersion": "1.0",
  "title": "OpenAxolotl Level Contract v1",
  "description": "What any world module must provide to be a valid OpenAxolotl world. This file is the MACHINE-READABLE half of the contract; docs/level-contract.md is the prose half and explains the reasoning. Where the two disagree, this file wins.",
  "sourceOfTruth": "The compliance checker loads this file and hardcodes no conformance rule. Adding a rule of an EXISTING ruleKind changes checker behaviour with no code change to the checker. Adding a NEW ruleKind is the one case that needs checker work, which is why the kinds below are few and deliberately general rather than one kind per element.",
  "authoringPath": "Code and Godot scenes only. There is no editor GUI authoring path, in any phase \u2014 which is what keeps this surface narrow enough to check, and what lets a human and an AI coding agent build a world the same way.",
  "ruleKinds": {
    "manifest_field_present": {
      "arguments": [
        "field"
      ],
      "description": "The dotted field path exists in world.json and is not null."
    },
    "manifest_field_type": {
      "arguments": [
        "field",
        "type"
      ],
      "description": "The field is of the named JSON type (string, number, integer, boolean, array, object)."
    },
    "manifest_field_matches": {
      "arguments": [
        "field",
        "pattern"
      ],
      "description": "The string field matches the given regular expression, anchored."
    },
    "manifest_field_in_set": {
      "arguments": [
        "field",
        "values"
      ],
      "description": "The field's value is one of a closed set. A value outside it is a violation, never a warning."
    },
    "manifest_array_min_length": {
      "arguments": [
        "field",
        "min"
      ],
      "description": "The array field has at least min entries."
    },
    "manifest_keys_subset_of": {
      "arguments": [
        "field",
        "allowedFrom"
      ],
      "description": "Every key of the object field appears in the list named by allowedFrom, which is a path into another contract file. Used so an allowlist is referenced rather than duplicated."
    },
    "scene_group_count": {
      "arguments": [
        "group",
        "min",
        "max"
      ],
      "description": "The world scene contains between min and max nodes belonging to the named Godot group. Omit max for unbounded. Group membership IS the tag: no name matching, no type sniffing, because a contributor renaming a node must not silently break conformance."
    },
    "file_present": {
      "arguments": [
        "path"
      ],
      "description": "The path exists inside the module root."
    },
    "file_absent": {
      "arguments": [
        "path"
      ],
      "description": "The path does NOT exist inside the module root."
    },
    "manifest_field_equals_directory_name": {
      "arguments": [
        "field"
      ],
      "description": "The string field equals the module's own directory name. Used so an identity that is also a directory name and a save namespace cannot disagree with the folder it lives in."
    },
    "manifest_array_items_prefixed_by": {
      "arguments": [
        "field",
        "prefixFrom"
      ],
      "description": "Every entry of the array field begins with the value of the field named by prefixFrom, followed by a dot. Used to namespace save keys per world."
    }
  },
  "moduleLayout": {
    "root": "worlds/<world_id>/",
    "worldIdPattern": "^[a-z][a-z0-9_]{2,31}$",
    "worldIdRationale": "Lowercase snake_case, 3-32 characters. It is a directory name, a save-key namespace and a portal id at once, so it must be filesystem-safe on every PC target and stable enough to key persisted data.",
    "files": {
      "manifest": {
        "name": "world.json",
        "required": true,
        "description": "The declaration this contract validates."
      },
      "scene": {
        "name": "world.tscn",
        "required": true,
        "description": "The world's root scene. Instanced by the hub; never auto-loaded."
      },
      "scripts": {
        "pattern": "^[a-z][a-z0-9_]*\\.gd$",
        "required": false,
        "description": "Statically typed GDScript only. Checked against the Sanctioned World API Surface by the static-analysis gate."
      },
      "assets": {
        "name": "assets/",
        "required": false,
        "description": "Per-world art and audio, each with the provenance record the Asset Contract requires."
      }
    },
    "rules": [
      {
        "kind": "file_present",
        "path": "world.json"
      },
      {
        "kind": "file_present",
        "path": "world.tscn"
      },
      {
        "kind": "file_absent",
        "path": "project.godot"
      },
      {
        "kind": "file_absent",
        "path": "export_presets.cfg"
      }
    ],
    "forbiddenFileRationale": "A world module carrying its own project.godot or export preset is trying to be a game rather than a module, and would override project-wide policy \u2014 the typed-GDScript settings and the no-networking declarations REQ-030 depends on."
  },
  "required": {
    "contractVersion": {
      "manifestField": "contractVersion",
      "description": "The contract version this world targets. Declared by every world so a core update can tell which worlds it may break, rather than discovering it at load.",
      "rules": [
        {
          "kind": "manifest_field_present",
          "field": "contractVersion"
        },
        {
          "kind": "manifest_field_in_set",
          "field": "contractVersion",
          "values": [
            "1.0"
          ]
        }
      ]
    },
    "worldId": {
      "manifestField": "worldId",
      "description": "Stable identity. Must equal the module directory name, so a world cannot be renamed on disk without renaming its save namespace.",
      "rules": [
        {
          "kind": "manifest_field_present",
          "field": "worldId"
        },
        {
          "kind": "manifest_field_matches",
          "field": "worldId",
          "pattern": "^[a-z][a-z0-9_]{2,31}$"
