      ]
    },
    "spawnPoint": {
      "manifestField": null,
      "description": "Where the player begins. Declared in the SCENE rather than the manifest: it is a transform, and a transform in JSON would drift from the geometry it is meant to sit on.",
      "rules": [
        {
          "kind": "scene_group_count",
          "group": "spawn_point",
          "min": 1,
          "max": 1
        }
      ],
      "rationale": "Exactly one. Two spawn points is not a richer world, it is an ambiguous one, and the hub would have to pick arbitrarily."
    },
    "checkpoints": {
      "manifestField": null,
      "description": "Checkpoint volumes. REQUIRED rather than optional because they anchor TWO systems at once: life refill and capability-state restore. A world without one has no defined answer to 'what happens when the player runs out of lives'.",
      "rules": [
        {
          "kind": "scene_group_count",
          "group": "checkpoint",
          "min": 1
        }
      ],
      "rationale": "At least one. The spacing rule \u2014 replay time from any checkpoint to the next within progression.max_retry_seconds \u2014 is a separate check that needs a traversal model, and belongs to the world's own test rather than to structural conformance."
    },
    "finishCondition": {
      "manifestField": "finishCondition",
      "description": "How the world is completed and the player returned to the Open Lagoon hub. Declarative: a world states WHAT completes it, never scripts the return itself.",
      "rules": [
        {
          "kind": "manifest_field_present",
          "field": "finishCondition"
        },
        {
          "kind": "manifest_field_present",
          "field": "finishCondition.kind"
        },
        {
          "kind": "manifest_field_in_set",
          "field": "finishCondition.kind",
          "values": [
            "reach_volume",
            "defeat_boss",
            "restore_all_regions",
            "collect_all"
          ]
        }
      ],
      "kinds": {
        "reach_volume": "The player enters a node in group finish_volume.",
        "defeat_boss": "The world's declared boss is defeated. Requires the optional boss element.",
        "restore_all_regions": "Every declared restorable region reaches restored. Requires restorableRegions.",
        "collect_all": "Every declared collectible is collected. Requires collectibles."
      },
      "rationale": "A closed set. An open-ended 'custom' kind would put completion logic back into world script, which is exactly what makes a world unverifiable \u2014 and it is the one thing the hub must be able to trust."
    },
    "controllerCompatibility": {
      "manifestField": "controllerCompatibility",
      "description": "The Axolotl Controller Interface version the world was built against. A DECLARATION, not a call \u2014 worlds never invoke the controller (see the Sanctioned World API Surface).",
      "rules": [
        {
          "kind": "manifest_field_present",
          "field": "controllerCompatibility"
        },
        {
          "kind": "manifest_field_in_set",
          "field": "controllerCompatibility",
          "values": [
            "1.0"
          ]
        }
      ]
    },
    "saveIntegration": {
      "manifestField": "saveIntegration",
      "description": "The save keys this world reads and writes. Declared up front so the save system can namespace them and so a fork's divergent keys are visible rather than discovered on a corrupt load.",
      "rules": [
        {
          "kind": "manifest_field_present",
          "field": "saveIntegration"
        },
        {
          "kind": "manifest_field_present",
          "field": "saveIntegration.keys"
        },
        {
          "kind": "manifest_field_type",
          "field": "saveIntegration.keys",
          "type": "array"
        },
        {
          "kind": "manifest_array_items_prefixed_by",
          "field": "saveIntegration.keys",
          "prefixFrom": "worldId"
        }
      ],
      "keyNamespaceRule": "Every key must begin with the world's own worldId followed by a dot. Two worlds cannot collide, and a removed world's data is identifiable.",
      "rationale": "An empty array is valid and means the world persists nothing. Declaring nothing is different from omitting the declaration: the first is a decision, the second is an oversight."
    }
  },
  "optional": {
    "collectibles": {
      "absentDefault": "none \u2014 the world declares no collectibles and the collectibles system is not engaged for it",
      "manifestField": "collectibles",
      "description": "An array of collectible declarations. The manifest says WHAT exists; the scene says WHERE, by placing an Area3D in group `collectible` with metadata `collectible_id` naming a declared id \u2014 a transform in JSON would drift from the geometry it sits on, the same reasoning spawnPoint gives. Two kinds with two lifetimes, kept distinct because only one is spent.",
      "entryShape": {
        "collectibleId": "string, unique within the world (the save namespace is already per world)",
        "kind": "one of the kinds below",
        "regionId": "required for kind resource: the restorableRegions entry it restores",
        "displayName": "optional string for the HUD and credits; defaults to the id",
        "kinds": {
          "resource": "A restoration resource. SPENT: delivered to regionId through the Restoration Region Interface and consumed to advance its state (collectibles.resource_pickup_value per pickup). A TYPE the scene may place any number of times; never persisted by id, because the region's banked count is what persists.",
          "discovery": "A rescued creature or a secret. KEPT: counted per world, persisted to the profile by id the moment it is collected, and absent from the scene on re-entry. One instance per declaration; the scene places it exactly once."
        }
      },
      "rules": [
        {
          "kind": "manifest_field_type",
          "field": "collectibles",
          "type": "array"
        }
      ],
      "completion": "The `collect_all` finish condition completes when every declared DISCOVERY collectible is collected. Resources are consumables and never part of completion. It can never complete vacuously: a collect_all world declaring no discovery collectibles is uncompletable, and the runtime says so at load.",
      "rationale": "Optional because the reward layer is exactly that \u2014 a world with no optional branches has nothing to reward. Nothing in any other finish condition may depend on a collectible existing, which is what keeps the absent default real: the reference template declares none and completes."
    },
    "enemies": {
      "absentDefault": "none \u2014 no Drift Fleet units spawn",
      "manifestField": "enemies"
    },
    "boss": {
      "absentDefault": "none \u2014 the world has no Flagship encounter and remains fully completable",
      "manifestField": "boss"
    },
    "customAbility": {
      "absentDefault": "none \u2014 only the installed Gill Mods are available",
      "manifestField": "customAbility",
      "description": "A Gill Mod declaration the world ships itself, registered through the Gill Mod Registration Interface. Travels the same validation a shipped mod does."
    },
    "secretAreas": {
      "absentDefault": "none",
      "manifestField": "secretAreas"
    },
    "npcs": {
      "absentDefault": "none",
      "manifestField": "npcs"
    },
    "music": {
      "absentDefault": "the engine's default bed plays \u2014 never silence, because silence reads as a bug rather than as a choice",
      "manifestField": "music"
    },
    "cameraHints": {
      "absentDefault": "none \u2014 the camera uses its default framing for the active grammar",
      "manifestField": null,
      "description": "Camera hint volumes placed in the scene, overriding framing declaratively. No custom camera code is permitted in a world, in any circumstance."
    },
    "restorableRegions": {
      "absentDefault": "none \u2014 the world has no restoration progression",
      "manifestField": "restorableRegions",
      "description": "Each region declares the barren/resourced/restored progression plus a SEPARATE boolean unlocked flag. The flag is not a fourth state. Each region may also declare `unlockedBy`: \"entry\" (unlocked the moment the player arrives) or \"boss\" (unlocked by the Flagship encounter). Omitting it keeps the pre-F-2 inference \u2014 unlocked at entry when the world declares no boss, locked until the encounter when it declares one \u2014 so a world written before this field means what it always meant. Declare it when a level wants both restoration on its critical path and a boss at its end; inferring the policy from an unrelated element deadlocks that level.",
      "regionFields": {
        "regionId": "required \u2014 the region's id",
        "traversalGates": "required, non-empty \u2014 restoration must open a real path",
        "unlockedBy": "optional \u2014 \"entry\" | \"boss\"; absent keeps the inference"
      }
    },
    "tuningOverrides": {
      "absentDefault": "none \u2014 every tuning value stays at its global setting",
      "manifestField": "tuningOverrides",
      "rules": [
        {
          "kind": "manifest_keys_subset_of",
          "field": "tuningOverrides",
          "allowedFrom": "core/tuning/tuning.json#worldOverridable"
        }
      ],
      "description": "Only keys enumerated in the tuning surface's own worldOverridable list may be overridden. That list is REFERENCED rather than copied here, so the two cannot drift apart."
    },
    "livesPerAttemptOverride": {
      "absentDefault": "the global progression.default_lives_per_attempt applies",
      "manifestField": "tuningOverrides.progression.default_lives_per_attempt",
      "description": "Expressed through tuningOverrides rather than as a field of its own, so there is one mechanism for overriding a tuned value rather than two."
    }
  },
  "sanctionedWorldApiSurface": {
    "$ref": "contracts/sanctioned_api.v1.json",
    "description": "The interfaces a world module may call, enforced by the World Static Analysis Gate. Kept in its own file because it is DERIVED from the architecture graph's world-outbound edges rather than authored from intent, and because the gate and the checker are different tools with different jobs."
  },
  "versioning": {
    "current": "1.0",
    "frozen": false,
    "freezeCondition": "v1 freezes only after both official MVP worlds are built against it and their friction has been fed back in. Freezing earlier would mean the contract encodes what was imagined rather than what was needed.",
    "compatibility": "A world declaring a contractVersion the running game does not support is refused by the hub and surfaced as an unavailable portal, never loaded partially.",
    "migration": {
      "policy": "A version increment ships with a written migration note naming every changed element and, for each, the mechanical edit a v1 world needs.",
      "additiveChanges": "New OPTIONAL elements may be added within a version, because an absent optional element already has a defined default and existing worlds stay conforming by definition.",
      "breakingChanges": "Adding a required element, removing an element, or narrowing a closed set increments the version.",
      "support": "The previous major version stays loadable for at least one release after the increment, so a fork has a window to migrate rather than breaking on the day of."
    }
  }
}

extends SceneTree
var passed:=0
var failed:=0
func check(ok: bool,message: String) -> void:
	if ok:passed+=1;print("PASS ",message)
	else:failed+=1;push_error(message)
func _initialize() -> void:run.call_deferred()
func frames(n: int) -> void:
	for i: int in n:await physics_frame
func key(body: AxolotlBody,pressed: bool) -> void:
	var event:=InputEventKey.new();event.physical_keycode=KEY_F;event.pressed=pressed;body.get_input_system().handle_event(event)
func run() -> void:
