class_name WorldContractShape
extends RefCounted

## The contract-visible shape of a world module: the element ids a save can
## legitimately refer to (REQ-014 AC-4).
##
## Stored alongside a world's progress so a later load can tell what changed.
## Comparing the stored shape to the world's current declarations is what
## classifies a change as additive or destructive, which is what the
## save-compatibility policy acts on.

var regions: PackedStringArray = []
var collectibles: PackedStringArray = []
var checkpoints: PackedStringArray = []


static func from_dictionary(source: Dictionary) -> WorldContractShape:
	var shape := WorldContractShape.new()
	shape.regions = _sorted_ids(source.get("regions", source.get("restorableRegions", [])))
	shape.collectibles = _sorted_ids(source.get("collectibles", []))
	shape.checkpoints = _sorted_ids(source.get("checkpoints", []))
	return shape


## The id field of a declaration object, by element. A manifest declares
## objects, the save records ids; the shape must read the same id from both.
const _ID_FIELDS: PackedStringArray = ["collectibleId", "regionId", "checkpointId"]


## Accepts both Array and PackedStringArray. PackedStringArray is NOT an Array
## in GDScript, so testing only `is Array` silently yields an empty shape — and
## an empty stored shape makes every later comparison look additive, including
## the renames that must quarantine.
##
## Entries may be bare ids or declaration objects straight from a manifest. A
## resource-kind collectible is a consumable TYPE the profile never refers to,
## so dropping one is not a destructive change and it contributes no id.
static func _sorted_ids(raw: Variant) -> PackedStringArray:
	var out := PackedStringArray()
	if raw is PackedStringArray:
		out = (raw as PackedStringArray).duplicate()
	elif raw is Array:
		for entry: Variant in (raw as Array):
			if entry is Dictionary:
				var id := _declared_id(entry as Dictionary)
				if not id.is_empty():
					out.append(id)
			else:
				out.append(String(entry))
	out.sort()
	return out


static func _declared_id(row: Dictionary) -> String:
	if String(row.get("kind", "")) == "resource":
		return ""
	for field: String in _ID_FIELDS:
		if row.has(field):
			return String(row[field])
	return ""


## Emits plain Arrays rather than packed ones so the in-memory shape and the
## JSON round trip are byte-identical — a shape must not classify differently
## depending on whether it came from memory or from disk.
func to_dictionary() -> Dictionary:
	return {
		"regions": _as_plain_array(regions),
		"collectibles": _as_plain_array(collectibles),
		"checkpoints": _as_plain_array(checkpoints),
	}


static func _as_plain_array(ids: PackedStringArray) -> Array:
	var out: Array = []
	for id: String in ids:
		out.append(id)
	return out


## How a stored shape differs from the world's current one.
enum Change {
	NONE,        ## identical
	ADDITIVE,    ## the world only gained elements; every stored id still exists
	DESTRUCTIVE, ## an id the save may reference was removed or renamed
}


## Classifies [param current] against this stored shape.
##
## A rename is indistinguishable from a removal plus an addition at the id level,
## and deliberately so: both mean an id the save references is gone, and both
## must be treated the same way. Guessing that "reef_a" became "reef_alpha"
## would be exactly the silent wrongness the policy exists to prevent.
func classify(current: WorldContractShape) -> Change:
	var change := Change.NONE

	for field: String in ["regions", "collectibles", "checkpoints"]:
		var stored_ids: PackedStringArray = get(field)
		var current_ids: PackedStringArray = current.get(field)

		for id: String in stored_ids:
			if not current_ids.has(id):
				return Change.DESTRUCTIVE  # something the save may point at is gone

		if current_ids.size() > stored_ids.size():
			change = Change.ADDITIVE

	return change


func equals(other: WorldContractShape) -> bool:
	return classify(other) == Change.NONE and other.classify(self) == Change.NONE

"""Original, deterministic synthesized score and foley. No sampled recordings."""
from pathlib import Path
import math, wave, json
import numpy as np
OUT=Path(__file__).resolve().parents[1]/'assets/audio/cascade'
OUT.mkdir(exist_ok=True)
SR=44100
rng=np.random.default_rng(19427)
report={}
def hz(m):return 440*2**((m-69)/12)
def write(name,x,loop=False):
    if x.ndim==1:x=np.stack([x,x],axis=1)
    peak=float(np.max(np.abs(x)))
    if peak>.83:x=x*(.83/peak)
    if not loop:
        n=min(len(x)//2,441);x[:n]*=np.linspace(0,1,n)[:,None];x[-n:]*=np.linspace(1,0,n)[:,None]
    with wave.open(str(OUT/(name+'.wav')),'wb') as f:
        f.setnchannels(2);f.setsampwidth(2);f.setframerate(SR);f.writeframes((x*32767).astype('<i2').tobytes())
    report[name]={'seconds':round(len(x)/SR,4),'peak':round(float(abs(x).max()),4),'rms':round(float(np.sqrt(np.mean(x*x))),4),'loop':loop}
def tone(m,d,kind='keys'):
    t=np.arange(round(d*SR))/SR;f=hz(m)
    if kind=='bass':
        x=(np.sin(2*np.pi*f*t)+.24*np.sin(4*np.pi*f*t)+.09*np.sin(6*np.pi*f*t))*np.exp(-t*3)
        x*=np.minimum(t/.006,1)*np.minimum((d-t)/.035,1)
    elif kind=='pad':
        x=(np.sin(2*np.pi*f*t)+.22*np.sin(2*np.pi*f*1.002*t)+.16*np.sin(4*np.pi*f*t))
        x*=np.minimum(t/.18,1)*np.minimum((d-t)/.28,1)*.55
    elif kind=='pluck':
        x=(np.sin(2*np.pi*f*t+.85*np.sin(2*np.pi*f*2*t)*np.exp(-t*18))+.15*np.sin(2*np.pi*f*3*t))*np.exp(-t*7)
        x*=np.minimum(t/.004,1)
    else:
        x=(np.sin(2*np.pi*f*t+1.5*np.sin(2*np.pi*f*2*t)*np.exp(-t*10))+.08*np.sin(2*np.pi*f*4*t))*np.exp(-t*3.3)
        x*=np.minimum(t/.004,1)*np.minimum((d-t)/.03,1)
    return x
def drum(kind):
    d={'kick':.3,'snare':.20,'hat':.055,'clap':.15,'rim':.075}[kind]
    t=np.arange(round(d*SR))/SR;n=rng.normal(0,1,len(t))
    hi=n-np.convolve(n,np.ones(9)/9,mode='same')
    if kind=='kick':return np.sin(2*np.pi*(46*t+50*.027*(1-np.exp(-t/.027))))*np.exp(-t*17)+hi*.02*np.exp(-t*120)
    if kind=='snare':return (hi*.4+np.sin(2*np.pi*185*t)*.22)*np.exp(-t*26)*np.minimum(t/.002,1)
    if kind=='hat':return hi*.15*np.exp(-t*85)*np.minimum(t/.001,1)
    if kind=='clap':return hi*.24*(np.exp(-t*40)+np.where(t>.012,np.exp(-np.maximum(t-.012,0)*55),0)+np.where(t>.023,np.exp(-np.maximum(t-.023,0)*45),0))
    return (np.sin(2*np.pi*820*t)+.6*np.sin(2*np.pi*1430*t))*np.exp(-t*95)*.4
def mix_score(name,bpm,bars,groove=False):
    beat=60/bpm;duration=bars*4*beat;count=round(duration*SR);x=np.zeros((count,2))
    def put(signal,b,level=.1,pan=0):
        start=round(b*beat*SR);idx=(np.arange(len(signal))+start)%count
        gains=np.sqrt([(1-pan)/2,(1+pan)/2]);np.add.at(x,idx,signal[:,None]*gains*level)
    roots=[50,55,48,53] # Dm9 - G13 - Cmaj9 - Fmaj9
    chords=[[62,65,69,72,76],[59,65,69,74],[60,64,67,71,74],[57,64,67,72]]
    melody=[74,76,77,81,79,77,76,72,74,77,76,69,72,74,69,67]
    for bar in range(bars):
        c=(bar//2)%4;root=roots[c];b=bar*4
        if groove:
            for off in [0,1.5,2.75]:put(drum('kick'),b+off,.45)
            for off in [1,3]:put(drum('snare'),b+off,.28);put(drum('clap'),b+off+.008,.12, .12)
            for j in range(8):put(drum('hat'),b+j*.5+(.035 if j%2 else 0),.45 if j%2==0 else .28,(-1)**j*.35)
            for off,interval in [(0,0),(.75,12),(1.5,7),(2,0),(2.75,10),(3.5,12)]:put(tone(root-12+interval,.26,'bass'),b+off,.29,-.06)
            for off in [.5,1.75,2.5,3.5]:
                for note in chords[c]:put(tone(note,.35,'keys'),b+off,.062,-.25)
            for j in range(4):
                note=melody[(bar*2+j)%len(melody)]
                put(tone(note,.28,'pluck'),b+j+.25,.075,.4)
        else:
            for note in chords[c]:put(tone(note,beat*4.1,'pad'),b,.055, (note%3-1)*.45)
            for off in [0,2.5]:put(tone(root-12,.65,'bass'),b+off,.18)
            for off in [1,3]:put(drum('rim'),b+off,.13,.3)
            for off in [0,2]:put(drum('kick'),b+off,.14)
            for j in range(8):put(drum('hat'),b+j*.5,.13 if j%2 else .18,(-1)**j*.4)
            for j,off in enumerate([.5,1.25,2.5,3.25]):
                note=melody[(bar*2+j+(8 if bar>=8 else 0))%len(melody)]
                if bar%4==3 and j>1:continue
                put(tone(note,.8,'keys'),b+off,.15,math.sin(bar+j)*.3)
    # Subtle stereo room echoes wrap into loop head, preserving exact bar length.
    wet=x.copy()
    for delay,gain in [(.137,.11),(.239,.065),(.383,.04)]:x+=np.roll(wet,round(delay*SR),axis=0)[:,::-1]*gain
    x=np.tanh(x*1.1)*.85
    write(name,x,not groove)
mix_score('cascade_exploration',96,16)
mix_score('crayfish_groove',112,8,True)
def chime(notes,spacing=.09):
    n=round((len(notes)*spacing+.8)*SR);x=np.zeros(n)
    for i,m in enumerate(notes):
        v=tone(m,.8,'keys')*.22;a=round(i*spacing*SR);x[a:a+len(v)]+=v[:len(x)-a]
    return x
for name,notes in {'crayfish_pickup':[81,86,90],'dance_unlocked':[74,77,81,86,89],'checkpoint':[67,74,79],'net_escape':[74,81,86],'net_caught':[62,57,50]}.items():write(name,chime(notes))
for name,kind in [('tail_whack','whack'),('spin_charge','spin'),('slide','slide'),('movement_swim_stroke','swim'),('movement_dive','dive'),('movement_waddle_step','step'),('movement_hop','hop'),('landing','land')]:
    d={'whack':.25,'spin':.55,'slide':.42,'swim':.22,'dive':.4,'step':.085,'hop':.17,'land':.14}[kind]
    t=np.arange(round(d*SR))/SR;n=rng.normal(0,1,len(t));smooth=np.convolve(n,np.ones(35)/35,mode='same')
    if kind in ['swim','dive','spin']:
        v=smooth*.38*np.sin(np.pi*t/d)**2+np.sin(2*np.pi*(240*t+150*t*t))*np.exp(-t*17)*.04
    elif kind=='hop':v=np.sin(2*np.pi*(240*t+800*t*t))*np.sin(np.pi*t/d)**2*.11
    elif kind=='whack':v=smooth*.6*np.sin(np.pi*t/d)**1.3+np.sin(2*np.pi*(110*t-60*t*t))*np.exp(-t*22)*.07
    else:v=smooth*.40*np.exp(-t*(16 if kind=='slide' else 45))
    write(name,v)
# Distinct required bank events, all original synthesized motifs.
for i,part in enumerate(['tail','gill','leg']):
    write('capability_lost_'+part,chime([65+i*3,60+i*3,55+i*3]))
    write('capability_regrown_'+part,chime([62+i*3,69+i*3,74+i*3]))
for name,notes in [('bubble',[79,84,88]),('jet',[62,74,86]),('glow',[81,85,88,93])]:write('gill_mod_'+name+'_activated',chime(notes,.07))
# Low ambience beds use periodic synthesis to avoid loop clicks.
for k,name in enumerate(['grammar_land','grammar_water','region_barren','region_resourced','region_restored']):
    d=8.;t=np.arange(round(d*SR))/SR
    if k<2:
        noise=rng.normal(0,1,len(t));spec=np.fft.rfft(noise);f=np.fft.rfftfreq(len(t),1/SR)
        spec*=np.exp(-(f/(900 if k==0 else 260))**2);v=np.fft.irfft(spec,n=len(t));v=v/max(abs(v))*.055
        v*=.8+.2*np.sin(2*np.pi*t/d)
    else:
        v=np.zeros(len(t))
        for m in [50,57,62+(k-2)*2]:
            f=round(hz(m)*d)/d;v+=np.sin(2*np.pi*f*t)*.012*(.8+.2*np.sin(2*np.pi*t/d))
    write(name,v,True)
(Path(__file__).resolve().parent/'source_art'/'cascade_audio_analysis.json').write_text(json.dumps(report,indent=2),encoding='utf-8')
(Path(__file__).resolve().parent/'source_art'/'cascade_audio_build_details.json').write_text(json.dumps({'author':'OpenAxolotl project; original procedural synthesis authored in Codex','generationMethod':'ai-generated','tool':'Python and NumPy, deterministic oscillator and noise synthesis','licenseTerms':'Original generated composition and waveforms; no third-party recordings or sampled music. Project Apache-2.0 licence.','description':'96 BPM D-minor exploration loop; 112 BPM funk dance cue; synthesized movement, pickup and restoration sounds.','source':'tools/make_cascade_audio.py'},indent=2),encoding='utf-8')
print('Generated',len(report),'original stereo WAVs',json.dumps({k:v for k,v in report.items() if k in ['cascade_exploration','crayfish_groove']}))

@tool
class_name WaterVolume
extends Area3D

## A region of water, placed by a world (REQ-001 AC-1, REQ-034, REQ-039).
##
## Which grammar the axolotl is in is a property of WHERE IT IS, so a world
## declares water by placing a volume rather than by scripting a state change.
## That is the same shape CameraHintVolume uses for framing, and it is what lets
## a contributor build a lagoon without touching controller code.
##
## The body tracks overlapping volumes and samples immersion with hysteresis;
## the controller remains the authority on movement grammar. Surface height
## comes from the original BoxMesh, or an explicit plane for shaped waterways.
## Currents are opt-in, spatially bounded, and independent of visual ripples.
##
## WHAT IT ANNOUNCES. Crossing the surface is the most physical thing that
## happens in this game and for a long time it happened in silence: the grammar
## changed, the animation changed, and the water itself did not react at all.
## Entering and leaving now raise a splash at the crossing point through
## WaterSplash, and ask for an audio cue by NAME — never a file path, because
## the Audio System alone decides what water sounds like (REQ-023).
##
## `@tool` so the shape is visible while editing. It does nothing in the editor
## beyond existing.

signal body_entered_water(body: AxolotlBody)
signal body_exited_water(body: AxolotlBody)

## Semantic audio ids, resolved by the Audio System. A dive and a surfacing are
## different sounds — one is a body arriving, the other is water closing behind
## it — so they are different ids rather than one "splash".
const CUE_ENTER := "water_enter"
const CUE_EXIT := "water_exit"

signal audio_cue_requested(cue_id: String)

## Below this vertical speed a crossing is a wade rather than a plunge, and it
## gets the smaller splash. A number rather than a boolean because the two ends
## of it are genuinely different events: stepping off a shore into shallows
## should not throw the same sheet of water as falling in from a ledge.
const PLUNGE_SPEED := 6.0

@export var explicit_surface: bool = false
@export var surface_height: float = 0.0
@export var surface_gradient: Vector2 = Vector2.ZERO
@export var water_priority: int = 0
@export var depth_lighting_enabled: bool = true
@export var shallow_wading_enabled: bool = false
@export var swim_enter_depth: float = -0.10
@export var swim_exit_depth: float = -0.26
@export var current_velocity: Vector3 = Vector3.ZERO
@export var current_ramp_m: float = 2.0

var _bodies: Array[AxolotlBody] = []


func _ready() -> void:
	if Engine.is_editor_hint():
		return
	add_to_group("water_volumes")
	body_entered.connect(_on_body_entered)
	body_exited.connect(_on_body_exited)


func _on_body_entered(body: Node3D) -> void:
	var axolotl := body as AxolotlBody
	if axolotl == null:
		return
	if _bodies.has(axolotl):
		return
	track_body(axolotl)
	_splash(axolotl, true)
	body_entered_water.emit(axolotl)


func _on_body_exited(body: Node3D) -> void:
	var axolotl := body as AxolotlBody
	if axolotl == null:
		return
	if not _bodies.has(axolotl):
		return
	_bodies.erase(axolotl)
	axolotl.unregister_water(self)
	_splash(axolotl, false)
	body_exited_water.emit(axolotl)


## Raises a splash where the body met the surface.
##
## AT THE SURFACE, NOT AT THE BODY. A player who dives in fast is already half
## a metre under by the frame the area reports it, and a splash centred on them
## appears underwater where nobody sees it. The crossing point is the body's
## own x and z at the height of this volume's top face, which is where the
## water was actually disturbed.
func _splash(body: AxolotlBody, entering: bool) -> void:
	var top := surface_at(body.global_position if body.is_inside_tree() else body.position)
	if is_inf(top):
		return
	var position_3d: Vector3 = body.global_position if body.is_inside_tree() else body.position
	var at := Vector3(position_3d.x, top, position_3d.z)
	var speed := absf(body.velocity.y)

	# DEFERRED, because this is inside the physics flush. body_entered fires
	# while the physics server is iterating its own state, and adding a node
	# to the tree during that is refused outright — "parent node is busy
	# setting up children" — so the splash simply never appeared. Every other
	# reaction to a volume in this game is deferred for the same reason; the
	# splash is the newest one to learn it.
	#
	# The crossing is measured NOW and the effect raised next frame: a
	# deferred call that read the body's velocity when it finally ran would
	# read it a frame late, by which point a dive has already changed speed.
	#
	# Through a method on this node rather than a bound Callable on
	# WaterSplash's static: binding one failed at runtime, and because it
	# failed INSIDE the crossing handler it took the rest of the handler with
	# it — the water grammar still switched, and every signal after this line
	# silently stopped being emitted.
	_raise_splash.call_deferred(at, speed, speed >= PLUNGE_SPEED)
	audio_cue_requested.emit(CUE_ENTER if entering else CUE_EXIT)


func _raise_splash(at: Vector3, speed: float, plunging: bool) -> void:
	WaterSplash.erupt(self, at, speed, plunging)


## The world height of this volume's top face, or INF when it has no box to
## take one from.
func _surface_height() -> float:
	for node: Node in find_children("*", "MeshInstance3D", true, false):
		var box := (node as MeshInstance3D).mesh as BoxMesh
		if box != null:
			var visual := node as Node3D
			return (visual.global_position.y if visual.is_inside_tree() else position.y + visual.position.y) + box.size.y * 0.5
	return INF


func surface_at(point: Vector3) -> float:
	if not explicit_surface:
		return _surface_height()
	var local: Vector3 = to_local(point) if is_inside_tree() else point - position
	var height: float = surface_height + surface_gradient.dot(Vector2(local.x, local.z))
	return (to_global(Vector3(local.x,height,local.z)).y if is_inside_tree() else height + position.y)


func should_swim(point: Vector3, was_swimming: bool) -> bool:
	# Existing deep-water routes were authored around capsule overlap, including
	# launching out of the surface. Shallow banks opt into immersion thresholds.
	if not shallow_wading_enabled:
		return true
	var top: float = surface_at(point)
	return not is_inf(top) and top-point.y >= (swim_exit_depth if was_swimming else swim_enter_depth)


func surface_slope_at(_point: Vector3) -> Vector2:
	return surface_gradient


func enclosure_at(_point: Vector3) -> float:
	return 0.0


func contains_point(point: Vector3, margin: float = 0.0) -> bool:
	for child: Node in get_children():
		var collision := child as CollisionShape3D
		if collision == null or collision.disabled or not collision.shape is BoxShape3D:
			continue
		var box := collision.shape as BoxShape3D
		var local: Vector3 = collision.to_local(point) if collision.is_inside_tree() else point-position-collision.position
		# Include the capsule's bottom while the body wades above the surface.
		if absf(local.x) <= box.size.x*0.5+margin and absf(local.z) <= box.size.z*0.5+margin and local.y >= -box.size.y*0.5-0.8 and local.y <= box.size.y*0.5+0.8:
			return true
	return false


func flow_at(point: Vector3) -> Vector3:
	if current_velocity.is_zero_approx() or not contains_point(point):
		return Vector3.ZERO
	for child: Node in get_children():
		var collision := child as CollisionShape3D
		if collision == null or not collision.shape is BoxShape3D:
			continue
		var box := collision.shape as BoxShape3D
		var local: Vector3 = collision.to_local(point) if collision.is_inside_tree() else point-position-collision.position
		var direction := Vector2(current_velocity.x,current_velocity.z).normalized()
		var half_length: float = absf(direction.x)*box.size.x*0.5+absf(direction.y)*box.size.z*0.5
		var along: float = Vector2(local.x,local.z).dot(direction)+half_length
		var lateral: float = absf(Vector2(local.x,local.z).dot(Vector2(-direction.y,direction.x)))
		var half_width: float = absf(direction.y)*box.size.x*0.5+absf(direction.x)*box.size.z*0.5
		var weight: float = smoothstep(0.0,maxf(0.01,current_ramp_m),along)*smoothstep(0.0,0.45,half_width-lateral)
		return (global_basis * current_velocity if is_inside_tree() else current_velocity)*weight
	return Vector3.ZERO


func forget_body(body: AxolotlBody) -> void:
	_bodies.erase(body)


func track_body(body: AxolotlBody) -> void:
	if not _bodies.has(body):
		_bodies.append(body)
	body.register_water(self)


func _exit_tree() -> void:
	for body: AxolotlBody in _bodies.duplicate():
		if is_instance_valid(body):
			body.unregister_water(self)
	_bodies.clear()

shader_type spatial;
render_mode diffuse_burley;
uniform sampler2D rock_color : source_color, filter_linear_mipmap_anisotropic, repeat_enable;
uniform sampler2D rock_normal : hint_normal, filter_linear_mipmap_anisotropic, repeat_enable;
uniform sampler2D rock_arm : filter_linear_mipmap_anisotropic, repeat_enable;
uniform sampler2D sand_color : source_color, filter_linear_mipmap_anisotropic, repeat_enable;
uniform sampler2D sand_normal : hint_normal, filter_linear_mipmap_anisotropic, repeat_enable;
uniform sampler2D sand_arm : filter_linear_mipmap_anisotropic, repeat_enable;
uniform sampler2D turf_color : source_color, filter_linear_mipmap_anisotropic, repeat_enable;
uniform sampler2D turf_normal : hint_normal, filter_linear_mipmap_anisotropic, repeat_enable;
uniform sampler2D turf_arm : filter_linear_mipmap_anisotropic, repeat_enable;
uniform sampler2D gravel_color : source_color, filter_linear_mipmap_anisotropic, repeat_enable;
uniform sampler2D gravel_normal : hint_normal, filter_linear_mipmap_anisotropic, repeat_enable;
uniform sampler2D gravel_arm : filter_linear_mipmap_anisotropic, repeat_enable;
uniform vec4 rock_tint : source_color = vec4(1.0);
uniform vec4 grass_tint : source_color = vec4(0.65,0.90,0.48,1.0);
uniform vec4 sand_tint : source_color = vec4(1.0,0.97,0.85,1.0);
uniform float surface_kind = 1.0;
uniform float water_level = 0.0;
uniform float gravel_share = 0.32;
uniform float rock_scale = 0.20;
uniform bool depth_blend_enabled = false;
varying vec3 p;
varying vec3 n;
varying vec4 mask;
varying vec3 view_x;
varying vec3 view_y;
varying vec3 view_z;
float hash(vec3 q){q=fract(q*0.1031);q+=dot(q,q.yzx+33.33);return fract((q.x+q.y)*q.z);}
float noise(vec3 q){vec3 i=floor(q),f=fract(q);f=f*f*(3.0-2.0*f);return mix(mix(mix(hash(i),hash(i+vec3(1,0,0)),f.x),mix(hash(i+vec3(0,1,0)),hash(i+vec3(1,1,0)),f.x),f.y),mix(mix(hash(i+vec3(0,0,1)),hash(i+vec3(1,0,1)),f.x),mix(hash(i+vec3(0,1,1)),hash(i+vec3(1,1,1)),f.x),f.y),f.z);}
vec3 tri(sampler2D tex,vec3 q,vec3 w,vec3 s){return texture(tex,q.zy*vec2(-s.x,1)).rgb*w.x+texture(tex,q.xz*vec2(1,-s.y)).rgb*w.y+texture(tex,q.xy*vec2(s.z,1)).rgb*w.z;}
vec3 rock_bump(vec3 q,vec3 w,vec3 s,vec3 base){
 vec3 x=texture(rock_normal,q.zy*vec2(-s.x,1)).xyz*2.0-1.0;
 vec3 y=texture(rock_normal,q.xz*vec2(1,-s.y)).xyz*2.0-1.0;
 vec3 z=texture(rock_normal,q.xy*vec2(s.z,1)).xyz*2.0-1.0;
 return normalize(base+(vec3(0,x.y,-x.x*s.x)*w.x+vec3(y.x,0,-y.y*s.y)*w.y+vec3(z.x*s.z,z.y,0)*w.z)*0.80);
}
vec3 top_bump(sampler2D tex,vec2 uv,vec3 base,float strength){vec3 t=texture(tex,uv).xyz*2.0-1.0;return normalize(base+vec3(t.x,0,-t.y)*strength);}
void vertex(){
 p=VERTEX; n=NORMAL; mask=COLOR;
 view_x=(MODELVIEW_MATRIX*vec4(1,0,0,0)).xyz;
 view_y=(MODELVIEW_MATRIX*vec4(0,1,0,0)).xyz;
 view_z=(MODELVIEW_MATRIX*vec4(0,0,1,0)).xyz;
}
void fragment(){
 vec3 base=normalize(n),s=sign(base+vec3(0.00001));
 vec3 w=pow(abs(base),vec3(5));w/=max(dot(w,vec3(1)),0.00001);
 float macro=noise(p*0.16),patch=noise(p*0.54);
 float up=smoothstep(0.48,0.93,base.y);
 float wet=1.0-smoothstep(water_level-0.10,water_level+0.30,p.y);
 // Green stores signed local water depth (-4..4 m); blue stores coverage.
 // They are baked from actual pool planes and the shared sloping chute profile.
 float bed_depth=depth_blend_enabled?max(mask.g*8.0-4.0,0.0):0.0;
 float immersed=depth_blend_enabled?clamp(mask.b,0.0,1.0)*smoothstep(0.025,0.22,bed_depth):0.0;
 float depth_mix=smoothstep(0.20,3.20,bed_depth);
 vec3 color,normal=base;float rough=0.88,ao=1.0;
 if(surface_kind>0.5){
   vec3 q=p*rock_scale;
   vec3 raw=tri(rock_color,q,w,s);
   vec3 arm=tri(rock_arm,q,w,s);
   float luma=dot(raw,vec3(0.2126,0.7152,0.0722));
   color=mix(raw,vec3(luma)*vec3(1.03,1.02,0.96),0.28)*rock_tint.rgb*1.30;
   color*=0.92+macro*0.16;
   normal=rock_bump(q,w,s,base);
   rough=clamp(arm.g,0.65,0.96);ao=mix(1.0,arm.r,0.36);
 }else{color=vec3(0);}
 if(surface_kind<1.5 || up>0.02){
   vec2 uv=p.xz*0.58;
   vec3 sand=texture(sand_color,uv).rgb*sand_tint.rgb*1.18;
   vec3 sand_data=texture(sand_arm,uv).rgb;
   vec3 sand_n=top_bump(sand_normal,uv,base,0.34);
   float gravel=max(wet,immersed)*mix(gravel_share,0.88,depth_mix*immersed)*smoothstep(0.29,0.72,patch);
   vec2 guv=p.xz*0.72;
   sand=mix(sand,texture(gravel_color,guv).rgb*1.30,gravel);
   sand_n=normalize(mix(sand_n,top_bump(gravel_normal,guv,base,0.62),gravel));
   sand_data=mix(sand_data,texture(gravel_arm,guv).rgb,gravel);
   float value=dot(sand,vec3(0.2126,0.7152,0.0722));
   vec3 shallow=sand*vec3(1.05,1.07,1.09);
   vec3 middle=sand*vec3(0.65,0.85,0.96);
   vec3 deep=value*vec3(0.23,0.40,0.53);
   vec3 sediment=mix(shallow,middle,smoothstep(0.15,1.75,bed_depth));
   sediment=mix(sediment,deep,smoothstep(1.10,3.20,bed_depth));
   sand=mix(sand,sediment,immersed);
   if(surface_kind<0.5){color=sand;normal=sand_n;rough=sand_data.g;ao=mix(1.0,sand_data.r,0.26);}
   else{
     float grass=mask.r*(1.0-max(wet,immersed))*smoothstep(0.25,0.52,patch+macro*0.25);
     if(surface_kind>1.5)grass=mask.r*0.72;
     vec2 tuv=p.xz*0.48;
     vec3 turf=texture(turf_color,tuv).rgb;
     float lum=dot(turf,vec3(0.2126,0.7152,0.0722));
     turf=mix(turf,vec3(lum),0.20)*grass_tint.rgb*vec3(1.20,1.65,0.92)*1.10;
     vec3 ground=mix(sand,turf,grass);
     vec3 tn=normalize(mix(sand_n,top_bump(turf_normal,tuv,base,0.40),grass));
     float blend=surface_kind<1.5?up:up*0.70;
     color=mix(color,ground,blend);
     normal=normalize(mix(normal,tn,blend));
     rough=mix(rough,mix(sand_data.g,texture(turf_arm,tuv).g,grass),blend);
   }
 }
 ALBEDO=color*(1.0-wet*0.24);
 NORMAL=normalize(view_x*normal.x+view_y*normal.y+view_z*normal.z);
 ROUGHNESS=clamp(rough-wet*0.20,0.42,0.96);
 AO=ao;AO_LIGHT_AFFECT=0.10;SPECULAR=0.20;
}

class_name HeroMotion
extends SkeletonModifier3D

var body: AxolotlBody
var model: Node3D
var visual_rotation := Vector3.ZERO
var visual_offset: float = 0.0
var wetness: float = 0.0
var swim_weight: float = 0.0
var bank: float = 0.0
var turn_rate: float = 0.0
var _initialized: bool = false
var _speed: float = 0.0
var swim_drive: float = 0.0
var swim_phase: float = 0.0
var _time: float = 0.0
var _bend: Array[float] = [0.0,0.0,0.0]
var _head_lead: float = 0.0
var _feet: Dictionary = {}
var _foot_heights: Array[float] = [INF,INF,INF,INF]
var _materials: Array[Dictionary] = []
var _foot_planted: Array[bool] = [false,false,false,false]
var _foot_anchors: Array[Vector3] = [Vector3.ZERO,Vector3.ZERO,Vector3.ZERO,Vector3.ZERO]
var _last_velocity := Vector3.ZERO
var _acceleration_lean := 0.0
var _swim_yaw_velocity := 0.0
const FEET: Array[String] = ["leg_fl","leg_fr","leg_bl","leg_br"]
const FOOT_PHASE: Array[float] = [0.0,0.5,0.62,0.12]

func bind(owner_body: AxolotlBody, visual: Node3D) -> void:
	body = owner_body
	model = visual
	_fit_feet()
	for node: Node in model.find_children("*","MeshInstance3D",true,false):
		var mesh := node as MeshInstance3D
		if mesh.mesh == null:
			continue
		for surface: int in mesh.mesh.get_surface_count():
			var original := mesh.get_active_material(surface) as BaseMaterial3D
			if original == null:
				continue
			var material := original.duplicate() as BaseMaterial3D
			mesh.set_surface_override_material(surface,material)
			_materials.append({"material":material,"roughness":original.roughness,"coat":original.clearcoat,"coat_enabled":original.clearcoat_enabled,"coat_roughness":original.clearcoat_roughness})

func reset_pose(yaw: float) -> void:
	visual_rotation = Vector3(0,yaw,0)
	_initialized = true
	turn_rate = 0.0
	bank = 0.0
	_bend = [0.0,0.0,0.0]
	_head_lead = 0.0
	_foot_heights = [INF,INF,INF,INF]
	_foot_planted = [false,false,false,false]
	_last_velocity = Vector3.ZERO
	_acceleration_lean = 0.0
	_swim_yaw_velocity = 0.0

func prepare(delta: float, in_water: bool, grounded: bool, velocity: Vector3, yaw: float, pitch: float, floor_normal: Vector3) -> void:
	if delta <= 0:
		return
	if not _initialized:
		reset_pose(yaw)
	_time += delta
	var old_yaw: float = visual_rotation.y
	var action: String = body.get_animator().get_current_action() if body != null else ""
	var response: float = 22.0 if action in ["spin","roll"] else 13.0
	if in_water and action.is_empty():
		# Ease angular speed as well as orientation: the torso begins, carries
		# through, and settles into a turn rather than swivelling in one tick.
		var difference := wrapf(yaw-old_yaw,-PI,PI)
		var wanted_rate := clampf(difference*6.0,-deg_to_rad(240.0),deg_to_rad(240.0))
		_swim_yaw_velocity = move_toward(_swim_yaw_velocity,wanted_rate,deg_to_rad(850.0)*delta)
		var step := _swim_yaw_velocity*delta
		if step*difference > 0.0 and absf(step) > absf(difference):
			step = difference
			_swim_yaw_velocity = 0.0
		visual_rotation.y = wrapf(old_yaw+step,-PI,PI)
	else:
		_swim_yaw_velocity = 0.0
		visual_rotation.y = wrapf(lerp_angle(old_yaw,yaw,1.0-exp(-delta*response)),-PI,PI)
	turn_rate = lerpf(turn_rate,clampf(wrapf(visual_rotation.y-old_yaw,-PI,PI)/delta,-6,6),1.0-exp(-delta*9))
	swim_weight = lerpf(swim_weight,1.0 if in_water else 0.0,1.0-exp(-delta*9))
	var contact_water: WaterVolume = body.get_water_volume() if body != null else null
	var relative_velocity: Vector3 = velocity-contact_water.flow_at(body.global_position) if contact_water != null and body.is_inside_tree() else velocity
	var acceleration := ((relative_velocity - _last_velocity) / delta).rotated(Vector3.UP, -visual_rotation.y)
	_last_velocity = relative_velocity
	var lean_target := clampf(acceleration.z * 0.006, -0.10, 0.08) if grounded and not in_water and action.is_empty() else 0.0
	_acceleration_lean = lerpf(_acceleration_lean, lean_target, 1.0-exp(-delta*12))
	_speed = lerpf(_speed,relative_velocity.length(),1.0-exp(-delta*10))
	swim_drive = smoothstep(0.25,3.5,_speed)
	swim_phase = fposmod(swim_phase+delta*lerpf(0.48,1.55,swim_drive),1.0)
	var action_damping: float = 0.0 if not action.is_empty() else 1.0
	bank = lerpf(bank,clampf(turn_rate*(0.085 if in_water else 0.014),-0.28,0.28)*action_damping,1.0-exp(-delta*9))
	var lead := wrapf(yaw-visual_rotation.y,-PI,PI)
	if in_water: lead = clampf(lead,-0.55,0.55)
	_head_lead = lerpf(_head_lead,lead*action_damping,1.0-exp(-delta*(8.0 if in_water else 12.0)))
	for i: int in 3:
		var wanted: float = -turn_rate*(0.055 if in_water else 0.035)*action_damping if i == 0 else _bend[i-1]
		_bend[i] = lerpf(_bend[i],clampf(wanted,-0.24,0.24),1.0-exp(-delta*((6.5-i*1.4) if in_water else (8.0-i*1.7))))
	var normal: Vector3 = floor_normal.rotated(Vector3.UP,-visual_rotation.y) if grounded else Vector3.UP
	var slope_pitch: float = clampf(atan2(normal.z,maxf(0.1,normal.y)),-0.25,0.25)*(1.0-swim_weight)
	var slope_roll: float = -clampf(atan2(normal.x,maxf(0.1,normal.y)),-0.20,0.20)*(1.0-swim_weight)
	visual_rotation.x = lerp_angle(visual_rotation.x,pitch*swim_weight+slope_pitch+_acceleration_lean,1.0-exp(-delta*11))
	visual_rotation.z = bank+slope_roll
	# Bring the torso toward the capsule centre while swimming; feet anchor land poses.
	visual_offset = swim_weight*(0.55+sin(_time*2.4)*0.015)
	if action == HeroAnimator.ROLL and grounded and not in_water:
		var phase: float = body.get_animator().get_action_phase()
		visual_offset -= 0.055*smoothstep(0.0,0.12,phase)*(1.0-smoothstep(0.75,1.0,phase))
	for foot: int in 4:
		_foot_heights[foot] = INF
		if not grounded or in_water or not action.is_empty(): _foot_planted[foot] = false
		if body != null and body.is_inside_tree() and grounded and not in_water and action not in ["roll","dance"]:
			var point: Vector3 = foot_position(foot)
			var query := PhysicsRayQueryParameters3D.create(point+Vector3.UP*0.4,point+Vector3.DOWN*0.5,body.collision_mask,[body.get_rid()])
			var hit: Dictionary = body.get_world_3d().direct_space_state.intersect_ray(query)
			if not hit.is_empty() and (hit["normal"] as Vector3).y > 0.55:
				_foot_heights[foot] = (hit["position"] as Vector3).y+0.008
	var water: WaterVolume = body.get_water_volume() if body != null else null
	var wet_target: float = 1.0 if in_water else 0.0
	if water != null and body.global_position.y-0.8 < water.surface_at(body.global_position):
		wet_target = maxf(wet_target,0.45)
	wetness = move_toward(wetness,wet_target,delta*(3.0 if wet_target > wetness else 0.075))
	for row: Dictionary in _materials:
		var material := row["material"] as BaseMaterial3D
		material.roughness = float(row["roughness"])*lerpf(1.0,0.38,wetness)
		material.clearcoat_enabled = bool(row["coat_enabled"]) or wetness > 0.01
		material.clearcoat = lerpf(float(row["coat"]),0.5,wetness)
		material.clearcoat_roughness = lerpf(float(row["coat_roughness"]),0.18,wetness)

func _process_modification_with_delta(_delta: float) -> void:
	var skeleton := get_skeleton()
	if skeleton == null or body == null:
		return
	var action: String = body.get_animator().get_current_action()
	if action == HeroAnimator.DANCE:return
	if action == HeroAnimator.WHACK:
		var root: int = skeleton.find_bone("root")
		if root >= 0:
			# Modifier poses are transient, so this pivot cannot leave an offset in
			# the next locomotion clip or move the CharacterBody collision capsule.
			skeleton.set_bone_pose_position(root,HeroActionClips.whack_root_position(skeleton.get_bone_rest(root).origin,body.get_animator().get_action_phase()))
	if action == HeroAnimator.WHACK and body.get_animator().has_walking_feet():
		for foot: String in FEET:
			var bone: int = skeleton.find_bone(foot)
			if bone >= 0:
				skeleton.set_bone_pose_rotation(bone,body.get_animator().walking_leg_pose(foot))
	var free_motion: float = 1.0 if action.is_empty() else 0.12
	if action.is_empty() and swim_weight > 0.001:
		_swimming_feet()
		# Replace the moving clip's oscillation with one coherent wave. Keep its
		# gentle idle tail motion and the original idle paddling unchanged.
		for bone_name: String in ["spine","head","tail_1","tail_2","tail_3"]:
			var bone: int = skeleton.find_bone(bone_name)
			if bone < 0:
				continue
			var rest: Quaternion = skeleton.get_bone_rest(bone).basis.get_rotation_quaternion()
			var idle_weight: float = 0.22 if bone_name.begins_with("tail_") else 1.0
			var clip_weight: float = lerpf(1.0,idle_weight*(1.0-swim_drive),swim_weight)
			skeleton.set_bone_pose_rotation(bone,rest.slerp(skeleton.get_bone_pose_rotation(bone),clip_weight))
			_rotate(bone_name,Vector3.UP,swim_bend(bone_name,swim_phase,swim_drive)*swim_weight)
	if action in [HeroAnimator.ROLL,HeroAnimator.SPIN]:
		var phase: float = body.get_animator().get_action_phase()
		_aim_feet(1.0,smoothstep(0.0,0.12,phase)*(1.0-smoothstep(0.75,1.0,phase)))
	_rotate("head",Vector3.UP,_head_lead*0.50)
	_rotate("spine",Vector3.UP,_head_lead*0.22)
	for i: int in 3:
		_rotate("tail_%d" % (i+1),Vector3.UP,_bend[i])
		_rotate("tail_%d" % (i+1),Vector3.RIGHT,sin(_time*2.0-i*0.65)*0.015*swim_weight*free_motion)
	for i: int in 2:
		var side: float = 1.0 if i == 0 else -1.0
		_rotate("gill_l" if i == 0 else "gill_r",Vector3.FORWARD,side*sin(_time*3.0-i*0.8)*(0.025+swim_weight*0.025)*free_motion)
	for foot: int in 4:
		_place_foot(foot)

static func swim_foot_direction(foot: int, phase: float, drive: float) -> Vector3:
	var side: float = 1.0 if foot%2 == 0 else -1.0
	var cycle: float = TAU*(phase+[0.0,0.5,0.55,0.05][foot])
	var tread := Vector3(side*(0.34+0.06*sin(cycle)),-0.15+0.07*cos(cycle),0.10+0.10*sin(cycle))
	var kick := Vector3(side*(0.040+0.012*cos(cycle)),-0.035+0.008*sin(cycle),0.46+0.018*sin(cycle))
	return tread.lerp(kick,clampf(drive,0,1)).normalized()

static func swim_bend(bone: String, phase: float, drive: float) -> float:
	# Phase travels from torso to tail tip, with greater amplitude toward the fin.
	var wave: float = TAU*phase
	match bone:
		"spine": return sin(wave)*0.12*drive
		"head": return -sin(wave)*0.085*drive
		"tail_1": return sin(wave-0.80)*0.24*drive
		"tail_2": return sin(wave-1.60)*0.34*drive
		"tail_3": return sin(wave-2.40)*0.44*drive
	return 0.0

func _swimming_feet() -> void:
	_aim_feet(swim_drive,swim_weight)

func _aim_feet(drive: float, weight: float) -> void:
	var skeleton := get_skeleton()
	for foot: int in 4:
		var bone: int = skeleton.find_bone(FEET[foot])
		if bone < 0 or not _feet.has(FEET[foot]):
			continue
		var rest: Quaternion = skeleton.get_bone_rest(bone).basis.get_rotation_quaternion()
		var direction: Vector3 = skeleton.get_bone_global_rest(bone).basis.inverse()*swim_foot_direction(foot,swim_phase,drive)
		var aim := Quaternion((_feet[FEET[foot]] as Vector3).normalized(),direction.normalized())
		var pose: Quaternion = (rest*aim).normalized()
		skeleton.set_bone_pose_rotation(bone,skeleton.get_bone_pose_rotation(bone).slerp(pose,weight))

static func contact_weight(phase: float) -> float:
	return smoothstep(0.0,0.05,phase)*(1.0-smoothstep(0.55,0.62,phase))

func _place_foot(foot: int) -> void:
	if is_inf(_foot_heights[foot]) or not _feet.has(FEET[foot]):
		_foot_planted[foot] = false
		return
	var animator := body.get_animator()
	var weight: float = contact_weight(fposmod(animator.get_gait_phase()-FOOT_PHASE[foot],1)) if animator.has_walking_feet() else 1.0
	var skeleton := get_skeleton()
	var bone: int = skeleton.find_bone(FEET[foot])
	var parent: int = skeleton.get_bone_parent(bone)
	var parent_transform: Transform3D = skeleton.global_transform*(skeleton.get_bone_global_pose(parent) if parent >= 0 else Transform3D.IDENTITY)
	var pose: Transform3D = skeleton.get_bone_pose(bone)
	var current: Vector3 = foot_position(foot)
	var target: Vector3 = current
	var locomotion := animator.get_current_action().is_empty() and swim_weight < 0.1
	if weight < 0.1 or not locomotion:
		_foot_planted[foot] = false
	elif not _foot_planted[foot]:
		_foot_anchors[foot] = Vector3(current.x, _foot_heights[foot], current.z)
		_foot_planted[foot] = true
	if _foot_planted[foot]:
		var offset := _foot_anchors[foot] - current
		# This rig has one bone per leg: release unreachable anchors instead of
		# stretching the skin or leaving a foot behind through a sharp turn.
		if Vector2(offset.x, offset.z).length() > 0.28 or absf(turn_rate) > 2.5:
			_foot_planted[foot] = false
		else:
			target.x = _foot_anchors[foot].x
			target.z = _foot_anchors[foot].z
	target.y += clampf(_foot_heights[foot]-current.y,-0.08,0.08)
	var from: Vector3 = parent_transform.affine_inverse()*current-pose.origin
	var to: Vector3 = parent_transform.affine_inverse()*target-pose.origin
	if from.length_squared() < 0.0001 or to.length_squared() < 0.0001:
		return
	# One joint per limb: cap correction instead of stretching the imported skin.
	var correction := Quaternion(from.normalized(),to.normalized())
	var angle: float = correction.angle_to(Quaternion.IDENTITY)
	var limited: float = minf(1.0,0.38/maxf(angle,0.0001))*weight*(1.0-swim_weight)
	skeleton.set_bone_pose_rotation(bone,(Quaternion.IDENTITY.slerp(correction,limited)*skeleton.get_bone_pose_rotation(bone)).normalized())

func _rotate(bone_name: String, axis: Vector3, amount: float) -> void:
	var skeleton := get_skeleton()
	var bone: int = skeleton.find_bone(bone_name)
	if bone < 0:
		return
	var local_axis: Vector3 = (skeleton.get_bone_global_rest(bone).basis.inverse()*axis).normalized()
	skeleton.set_bone_pose_rotation(bone,(skeleton.get_bone_pose_rotation(bone)*Quaternion(local_axis,amount)).normalized())

func foot_position(index: int) -> Vector3:
	var skeleton := get_skeleton()
	var bone: int = skeleton.find_bone(FEET[index])
	if bone < 0 or not _feet.has(FEET[index]):
		return body.global_position+Vector3.DOWN*0.8
	return skeleton.global_transform*(skeleton.get_bone_global_pose(bone)*(_feet[FEET[index]] as Vector3))

func tail_position() -> Vector3:
	var skeleton := get_skeleton()
	var bone: int = skeleton.find_bone("tail_3")
	return skeleton.global_transform*(skeleton.get_bone_global_pose(bone)*Vector3(0,0.50,0)) if bone >= 0 else body.global_position

func _fit_feet() -> void:
	var skeleton := get_skeleton()
	if skeleton == null:
		return
	for foot: String in FEET:
		var bone: int = skeleton.find_bone(foot)
		if bone < 0:
			continue
		var sum := Vector3.ZERO
		var weight_sum: float = 0.0
		for node: Node in model.find_children("*","MeshInstance3D",true,false):
			var instance := node as MeshInstance3D
			# Harness weights follow the legs, but equipment is not a foot contact.
			if instance.name == "ExplorerBackpack" or instance.skin == null or instance.mesh == null:
				continue
			var bind_index: int = -1
			for bind_id: int in instance.skin.get_bind_count():
				if String(instance.skin.get_bind_name(bind_id)) == foot or instance.skin.get_bind_bone(bind_id) == bone:
					bind_index = bind_id
			if bind_index < 0:
				continue
			for surface: int in instance.mesh.get_surface_count():
				var arrays: Array = instance.mesh.surface_get_arrays(surface)
				var vertices: PackedVector3Array = arrays[Mesh.ARRAY_VERTEX]
				var bones: PackedInt32Array = arrays[Mesh.ARRAY_BONES]
				var weights: PackedFloat32Array = arrays[Mesh.ARRAY_WEIGHTS]
				if vertices.is_empty() or bones.is_empty():
					continue
				var influences: int = bones.size()/vertices.size()
				for vertex: int in vertices.size():
					if vertices[vertex].y > instance.get_aabb().position.y+0.22:
						continue
					for slot: int in influences:
						var offset: int = vertex*influences+slot
						if bones[offset] == bind_index and weights[offset] > 0.35:
							sum += vertices[vertex]*weights[offset]
							weight_sum += weights[offset]
		var point: Vector3 = sum/weight_sum if weight_sum > 0 else Vector3(0.55 if foot.ends_with("l") else -0.55,0,-0.55 if foot.begins_with("leg_f") else 0.55)
		_feet[foot] = skeleton.get_bone_global_rest(bone).affine_inverse()*point

