  "contractVersion": "1.0",
  "title": "Sanctioned World API Surface v1",
  "description": "The complete set of interfaces a world module may call, and the classes of call it may never make. Enforced by the World Static Analysis Gate as a merge-blocking CI check against every world — official worlds, the reference template, and community submissions alike. This surface is the security boundary for community-contributed code: worlds ship GDScript like any other module, so safety comes from this allowlist plus MANDATORY HUMAN REVIEW, never from an automated-only merge path.",

  "sourceOfTruth": "The static-analysis gate loads this file and hardcodes no rule.",

  "derivation": {
    "rule": "allowedInterfaces is DERIVED from the architecture graph: it is exactly the set of contract names on edges whose SOURCE is a world node. It is never authored from intent.",
    "why": "An allowlist written from memory drifts from the interfaces that really exist, in both directions. Too narrow and the gate rejects legitimate world code; too broad and a world is granted reach the architecture never gave it. A drafted version of this file listed eleven interfaces where the graph gives seven — it had added the controller, input, checkpoint and tuning interfaces, none of which a world has an edge to.",
    "source": ".nodespec/model.json",
    "query": "{ contracts[e.contractId].name for e in edges if nodes[e.source].label starts with 'World:' }",
    "enforcement": "test/contracts/test_level_contract.gd recomputes this set from the model on every run and fails when this file and the graph disagree. Widening the allowlist by hand is therefore not possible: add the architecture edge and this file follows."
  },

  "allowedInterfaces": [
    {
      "contract": "Save Integration Interface",
      "provider": "Save System",
      "description": "The only permitted persistence path. A world never opens, reads, or writes a save file directly, and only under the save keys it declared in its manifest."
    },
    {
      "contract": "Audio Event Interface",
      "provider": "Audio System",
      "description": "Semantic audio event ids. Never a file path, and never a direct AudioStreamPlayer of the world's own."
    },
    {
      "contract": "Camera Hint Interface",
      "provider": "Camera System",
      "description": "Declarative hint volumes overriding framing. No custom camera code in a world, in any circumstance."
    },
    {
      "contract": "Gill Mod Registration Interface",
      "provider": "Gill Mod Ability Framework",
      "description": "Register a custom Gill Mod through the Level Contract's optional customAbility element. Travels the same validation a shipped mod does."
    },
    {
      "contract": "Enemy Registration Interface",
      "provider": "Drift Fleet Enemy Framework",
      "description": "Place and configure Drift Fleet units, including the Flagship encounter."
    },
    {
      "contract": "Collectible Registration Interface",
      "provider": "Collectibles System",
      "description": "Declare collectibles and their placement."
    },
    {
      "contract": "Restoration Region Interface",
      "provider": "World Restoration State System",
      "description": "Declare restorable regions and query or advance their state."
    }
  ],

  "deliberatelyExcluded": [
    {
      "contract": "Player Input Interface",
      "why": "Worlds read player intent through the controller interface and never read raw input (REQ-024 AC-6). There is no world-facing input surface at all, by design.",
      "instead": "Gate a path on the controller's published movement state, or on a Gill Mod affordance."
    },
    {
      "contract": "Axolotl Controller Interface",
      "why": "The graph gives no world an edge to the controller. Controller compatibility is DECLARED in world.json, not called.",
      "instead": "Declare controllerCompatibility in the manifest; the Game Client owns the wiring."
    },
    {
      "contract": "Checkpoint and Life Interface",
      "why": "Checkpoints are declarative. A world places nodes in the checkpoint group and the Game Client wires them to the life and capability systems.",
      "instead": "Place checkpoint volumes in the scene."
    },
    {
      "contract": "Tuning Data Interface",
      "why": "A world does not read the tuning surface; it declares tuningOverrides in its manifest, limited to the enumerated worldOverridable set.",
      "instead": "Declare tuningOverrides in the manifest."
    },
    {
      "contract": "HUD State Interface",
      "why": "The HUD reads game state; a world does not write to it. A world that needs to say something to the player says it through a declared element, not by drawing.",
      "instead": "Use the declarative elements the Level Contract provides."
    }
  ],

  "exclusionPolicy": "If a world genuinely needs an excluded interface, the fix is to add the architecture edge and let this file follow — never to widen the allowlist by hand. A world that can only achieve something by reaching outside this surface is evidence the interface is wrong, not evidence the world is special.",

  "enforcement": {
    "tool": "world-static-analysis",
    "severity": "error",
    "mergeGate": "blocking",
    "appliesTo": [
      "worlds/<world_id>/**/*.gd",
      "worlds/<world_id>/**/*.tscn",
      "worlds/<world_id>/world.json"
    ],
    "defaultPosture": "deny — a symbol absent from allowedInterfaces is a violation, not an omission"
  },

  "forbiddenCallClasses": {
    "filesystem": {
      "rationale": "A world module has no legitimate reason to touch the filesystem; persistence goes through the Save Integration Interface.",
      "symbols": ["FileAccess", "DirAccess", "ResourceSaver", "ProjectSettings.globalize_path", "ConfigFile"]
    },
    "network": {
      "rationale": "Single-player, offline game. There is no network layer of any kind.",
      "symbols": ["HTTPRequest", "HTTPClient", "StreamPeerTCP", "StreamPeerTLS", "PacketPeerUDP", "TCPServer", "UDPServer", "WebSocketPeer", "IP"]
    },
    "osExecution": {
      "rationale": "Executing processes or shelling out from world code is arbitrary code execution on a contributor's machine.",
      "symbols": ["OS.execute", "OS.create_process", "OS.shell_open", "OS.set_environment", "OS.get_environment"]
    },
    "dynamicEvaluation": {
      "rationale": "Dynamic evaluation defeats static analysis entirely — it is how an allowlist gets bypassed.",
      "symbols": ["Expression", "GDScript.new", "Object.call", "Object.callv", "Object.set_script", "ResourceLoader.load with a non-literal path", "load with a non-literal path", "str2var", "bytes_to_var"]
    },
    "rawInput": {
      "rationale": "Worlds read intent, never input (REQ-024 AC-6). A world gating a path on a physical key could never be rebound, which would break the accessibility guarantee for every player of that world.",
      "symbols": ["Input", "InputEvent", "InputMap", "Input.is_action_pressed", "Input.get_vector"]
    },
    "multiplayer": {
      "rationale": "No multiplayer, in any phase — a firm non-goal, not a deferral. This mirrors the Engine Feature Policy applied to core systems, so world modules are covered by exactly the same ban as core (REQ-030 AC-7).",
      "symbols": {
        "apis": ["multiplayer", "MultiplayerAPI", "SceneMultiplayer"],
        "calls": ["rpc", "rpc_id", "rpc_config"],
        "nodes": ["MultiplayerSynchronizer", "MultiplayerSpawner"],
        "peers": ["MultiplayerPeer", "ENetMultiplayerPeer", "WebRTCMultiplayerPeer", "WebSocketMultiplayerPeer", "OfflineMultiplayerPeer"],
        "authority": ["is_multiplayer_authority", "set_multiplayer_authority", "get_multiplayer_authority"],
        "annotations": ["@rpc"],
        "projectSettings": ["network/*"]
      }
    },
    "coreInternals": {
      "rationale": "Reaching past a published interface into a core system's private members is the hole that makes a world unforkable. If a world can only achieve something this way, the interface is wrong — fix the interface, not the world.",
      "symbols": [
        "any member prefixed _ on a core system",
        "get_node paths into core/ scene trees",
        "direct instantiation of core system classes not exposed via a sanctioned interface"
      ]
    }
  },

  "guidanceOverride": "Where general Godot documentation, engine samples, or catalog technology guidance demonstrate RPC-based movement, server-authority patterns, direct file access for saves, or raw Input reads, that guidance DOES NOT APPLY to world modules in this project. Implement world logic as local single-player code against the sanctioned interfaces above.",

  "violationOutput": {
    "requirement": "Failure output names the offending file, line, the specific forbidden symbol, and the call class it violates, as structured machine-readable output an AI coding agent can parse and self-correct against.",
    "exitCode": "non-zero on any violation"
  }
}

class_name ContractValidator
extends RefCounted

## The hub's runtime Level Contract validation (REQ-009 AC-4, REQ-006 AC-1).
##
## The Python compliance checker guards the MERGE; this guards the LOAD. They
## are two engines over ONE data file — `contracts/level_contract.v1.json` —
## because "fork it" is the project's premise: a forked repo with a world
## dropped straight into `worlds/` never went through anyone's CI, and the hub
## still must refuse to load what does not conform rather than crash on it.
##
## Same design law as the Python engine: this class knows rule KINDS, never
## contract elements. There is no `_check_spawn_point()` here and never will
## be — adding a conformance rule is an edit to the contract file only, and an
## element this engine has never heard of validates fine the day it appears.
## A rule KIND this engine does not implement is reported as its own named
## error instead of being skipped, because a skipped rule is a rule that
## silently stopped protecting anyone.
##
## Violations carry the same stable dotted ids the Python checker emits
## (`<element>.<kind>`), so an agent self-correcting against either gate is
## reading one vocabulary.

const DEFAULT_SCHEMA_PATH := "res://contracts/level_contract.v1.json"

var _schema: Dictionary = {}
var _schema_ok := false


func _init(schema_path: String = DEFAULT_SCHEMA_PATH) -> void:
	var text := _read_file(schema_path)
	if text.is_empty():
		return
	var parsed: Variant = JSON.parse_string(text)
	if parsed is Dictionary:
		_schema = parsed as Dictionary
		_schema_ok = true


func is_ready() -> bool:
	return _schema_ok


func contract_version() -> String:
	return String(_schema.get("contractVersion", "unknown"))


## Validates one module directory. Returns true when it conforms; every
## violation is appended to [param out_errors]. A missing or unreadable schema
## refuses ALL modules with a named error — a hub that loads worlds unchecked
## because its contract went missing would be strictly worse than one that
## loads nothing.
func validate_module(module_dir: String,
		out_errors: Array[HubError]) -> bool:
	if not _schema_ok:
		out_errors.append(HubError.new(
			HubError.SCHEMA_UNAVAILABLE, DEFAULT_SCHEMA_PATH,
			"the Level Contract schema could not be loaded; refusing to "
			+ "validate rather than loading worlds unchecked"))
		return false

	var before := out_errors.size()
	var manifest: Variant = _load_manifest(module_dir, out_errors)
	if manifest == null:
		return false

	for pair: Array in _collect_rules():
		_apply_rule(String(pair[0]), pair[1] as Dictionary,
			module_dir, manifest as Dictionary, out_errors)

	return out_errors.size() == before


## (element, rule) pairs in the same stable order the Python checker walks:
## moduleLayout first, then required and optional elements sorted by name.
func _collect_rules() -> Array[Array]:
	var pairs: Array[Array] = []
	var layout := _schema.get("moduleLayout", {}) as Dictionary
	for rule: Variant in layout.get("rules", []) as Array:
		pairs.append(["moduleLayout", rule])

	for section: String in ["required", "optional"]:
		var elements := _schema.get(section, {}) as Dictionary
		var names := elements.keys()
		names.sort()
		for name: Variant in names:
			var body: Variant = elements[name]
			if not (body is Dictionary):
				continue
			for rule: Variant in (body as Dictionary).get("rules", []) as Array:
				pairs.append([String(name), rule])
	return pairs


func _apply_rule(element: String, rule: Dictionary, module_dir: String,
		manifest: Dictionary, out_errors: Array[HubError]) -> void:
	var kind := String(rule.get("kind", ""))
	var subject := "%s.%s" % [element, kind]

	match kind:
		"file_present":
			var path := module_dir.path_join(String(rule["path"]))
			if not FileAccess.file_exists(path):
				_violation(out_errors, subject,
					"required file '%s' is missing" % String(rule["path"]))
		"file_absent":
			var path := module_dir.path_join(String(rule["path"]))
			if FileAccess.file_exists(path):
				_violation(out_errors, subject,
					"forbidden file '%s' is present" % String(rule["path"]))
		"manifest_field_present":
			if _read_path(manifest, String(rule["field"])) == null:
				_violation(out_errors, subject,
					"manifest field '%s' is missing" % String(rule["field"]))
		"manifest_field_type":
			var value: Variant = _read_path(manifest, String(rule["field"]))
			if value != null and not _type_matches(value, String(rule["type"])):
				_violation(out_errors, subject,
					"manifest field '%s' must be of type %s"
					% [String(rule["field"]), String(rule["type"])])
		"manifest_field_matches":
			var value: Variant = _read_path(manifest, String(rule["field"]))
			if value is String:
				var regex := RegEx.create_from_string(String(rule["pattern"]))
				if regex.search(String(value)) == null:
					_violation(out_errors, subject,
						"'%s' does not match %s"
						% [String(value), String(rule["pattern"])])
		"manifest_field_in_set":
			var value: Variant = _read_path(manifest, String(rule["field"]))
			if value != null:
				var allowed := rule.get("values", []) as Array
				if not allowed.has(value):
					_violation(out_errors, subject,
						"'%s' is not one of %s" % [str(value), str(allowed)])
		"manifest_field_equals_directory_name":
			var value: Variant = _read_path(manifest, String(rule["field"]))
			var dir_name := module_dir.rstrip("/").get_file()
			if value is String and String(value) != dir_name:
				_violation(out_errors, subject,
					"'%s' must equal the module directory name '%s'"
					% [String(value), dir_name])
		"manifest_array_min_length":
			var value: Variant = _read_path(manifest, String(rule["field"]))
			if value is Array and (value as Array).size() < int(rule["min"]):
				_violation(out_errors, subject,
					"'%s' needs at least %d entr(ies)"
					% [String(rule["field"]), int(rule["min"])])
		"manifest_array_items_prefixed_by":
			_rule_items_prefixed(rule, manifest, subject, out_errors)
		"manifest_keys_subset_of":
			_rule_keys_subset(rule, manifest, subject, out_errors)
		"scene_group_count":
			_rule_scene_group_count(rule, module_dir, subject, out_errors)
		_:
			# A kind this engine cannot enforce means the CONTRACT is newer
			# than the hub. Refusing the module with the gap named beats
			# loading a world a rule was supposed to have screened.
			out_errors.append(HubError.new(
				HubError.UNKNOWN_RULE_KIND, subject,
				"this hub does not implement rule kind '%s'" % kind))


func _rule_items_prefixed(rule: Dictionary, manifest: Dictionary,
		subject: String, out_errors: Array[HubError]) -> void:
	var value: Variant = _read_path(manifest, String(rule["field"]))
	if not (value is Array):
		return
	var prefix_value: Variant = _read_path(manifest, String(rule["prefixFrom"]))
	if not (prefix_value is String):
		return
	var prefix := String(prefix_value) + "."
	for item: Variant in (value as Array):
		if not (item is String) or not String(item).begins_with(prefix):
			_violation(out_errors, subject,
				"'%s' must begin with '%s'" % [str(item), prefix])


func _rule_keys_subset(rule: Dictionary, manifest: Dictionary,
		subject: String, out_errors: Array[HubError]) -> void:
	var value: Variant = _read_path(manifest, String(rule["field"]))
	if not (value is Dictionary):
		return
	var source := String(rule.get("allowedFrom", ""))
	var parts := source.split("#")
	var text := _read_file("res://" + parts[0])
	var allowed: Array = []
	if not text.is_empty():
		var parsed: Variant = JSON.parse_string(text)
		if parsed is Dictionary and parts.size() > 1:
			allowed = (parsed as Dictionary).get(parts[1], []) as Array
	for key: Variant in (value as Dictionary):
		if not allowed.has(String(key)):
			_violation(out_errors, subject,
				"'%s' is not a world-overridable key" % String(key))


func _rule_scene_group_count(rule: Dictionary, module_dir: String,
		subject: String, out_errors: Array[HubError]) -> void:
	var group := String(rule["group"])
	var count := _count_scene_group(module_dir.path_join("world.tscn"), group)
	if rule.has("min") and count < int(rule["min"]):
		_violation(out_errors, subject,
			"group '%s' needs at least %d node(s), found %d"
			% [group, int(rule["min"]), count])
	if rule.has("max") and count > int(rule["max"]):
		_violation(out_errors, subject,
			"group '%s' allows at most %d node(s), found %d"
			% [group, int(rule["max"]), count])


## Counts group memberships the same way the Python checker does: from the
## scene FILE, not an instantiated tree — validation must never execute a
## module's content before it has passed.
func _count_scene_group(scene_path: String, group: String) -> int:
	var text := _read_file(scene_path)
	if text.is_empty():
		return 0
	var count := 0
	var node_line := RegEx.create_from_string("^\\[node\\s+.*\\]\\s*$")
	var groups_attr := RegEx.create_from_string("groups\\s*=\\s*\\[([^\\]]*)\\]")
	var quoted := RegEx.create_from_string("\"([^\"]*)\"")
	for line: String in text.split("\n"):
		if node_line.search(line) == null:
			continue
		var attr := groups_attr.search(line)
		if attr == null:
			continue
		for match_: RegExMatch in quoted.search_all(attr.get_string(1)):
			if match_.get_string(1) == group:
				count += 1
	return count


func _load_manifest(module_dir: String,
		out_errors: Array[HubError]) -> Variant:
	var path := module_dir.path_join("world.json")
	if not FileAccess.file_exists(path):
		out_errors.append(HubError.new(
			HubError.MISSING_MANIFEST, module_dir,
			"no world.json in this module"))
		return null
	var text := _read_file(path)
	var parsed: Variant = JSON.parse_string(text)
	if not (parsed is Dictionary):
		out_errors.append(HubError.new(
			HubError.MALFORMED_MANIFEST, path,
			"world.json is not a JSON object"))
		return null
	return parsed


func _violation(out_errors: Array[HubError], subject: String,
		message: String) -> void:
	out_errors.append(HubError.new(
		HubError.CONTRACT_VIOLATION, subject, message))


static func _read_path(data: Dictionary, dotted: String) -> Variant:
	var current: Variant = data
	for part: String in dotted.split("."):
		if not (current is Dictionary) or not (current as Dictionary).has(part):
			return null
		current = (current as Dictionary)[part]
	return current


static func _type_matches(value: Variant, type_name: String) -> bool:
	match type_name:
		"array":
			return value is Array
		"object":
			return value is Dictionary
		"string":
			return value is String
		"number":
			return value is float or value is int
		"boolean":
			return value is bool
		_:
			return false


static func _read_file(path: String) -> String:
	if not FileAccess.file_exists(path):
		return ""
	var handle := FileAccess.open(path, FileAccess.READ)
	if handle == null:
		return ""
	var text := handle.get_as_text()
	handle.close()
	return text

class_name TongueGrapple
extends RefCounted

## Tongue grapple: discovery, range, attachment and the pull (REQ-001 AC-4).
##
## Range comes from the tuning surface and is tested INCLUSIVELY: an anchor
## exactly at max range attaches, one beyond it is rejected. The criterion says
## "at or within", and an off-by-a-hair exclusive test would make the documented
## number a lie at exactly the distance a player aims for.
##
## Discovery is a group query plus a line-of-sight ray, in that order and with the
## range filter between them (see AnchorSource). The criterion's third clause —
## "pulls the axolotl to the attached anchor" — is the pull below: attaching
## without moving would satisfy the first two clauses and still leave the verb
## doing nothing, which is precisely the gap this file has to not have.

const MAX_RANGE_KEY := "controller.grapple.max_range_m"
const PULL_SPEED_KEY := "controller.grapple.pull_speed_m_per_s"
const ARRIVAL_RADIUS_KEY := "controller.grapple.arrival_radius_m"

## The group a world tags anchor nodes with. Membership IS the tag.
const ANCHOR_GROUP := "grapple_anchor"

var _tuning: TuningData
var _anchor: GrappleAnchor = null


func _init(tuning: TuningData) -> void:
	_tuning = tuning


func max_range() -> float:
	return _tuning.get_number(MAX_RANGE_KEY)


func pull_speed() -> float:
	return _tuning.get_number(PULL_SPEED_KEY)


func arrival_radius() -> float:
	return _tuning.get_number(ARRIVAL_RADIUS_KEY)


## True when an anchor at [param distance] is attachable. Inclusive at the bound.
func is_in_range(distance: float) -> bool:
	return distance <= max_range()


## The nearest anchor that is in the group, within range, and in line of sight.
## Returns null when nothing qualifies — the caller plays a miss rather than the
## grapple silently doing nothing.
##
## Range is filtered BEFORE the ray so an out-of-reach anchor across the level
## never costs a physics query, and the nearest-first ordering means the ray
## budget is spent on the anchors most likely to win.
func find_anchor(origin: Vector3, source: AnchorSource) -> GrappleAnchor:
	if source == null:
		return null

	var reachable: Array[GrappleAnchor] = []
	for anchor: GrappleAnchor in source.query_anchors_in_group(ANCHOR_GROUP):
		if is_in_range(origin.distance_to(anchor.position)):
			reachable.append(anchor)

	reachable.sort_custom(func(a: GrappleAnchor, b: GrappleAnchor) -> bool:
		return origin.distance_to(a.position) < origin.distance_to(b.position))

	for anchor: GrappleAnchor in reachable:
		if source.has_line_of_sight(origin, anchor.position):
			return anchor

	return null


## Attaches to a resolved anchor. Attaching to null is a no-op so a missed grapple
## cannot leave the controller believing it is attached.
func attach(anchor: GrappleAnchor) -> bool:
	if anchor == null or anchor.id.is_empty():
		return false
	_anchor = anchor
	return true


func detach() -> void:
	_anchor = null


func is_attached() -> bool:
	return _anchor != null


func get_attached_anchor() -> String:
	return "" if _anchor == null else _anchor.id


func get_anchor_position() -> Vector3:
	return Vector3.ZERO if _anchor == null else _anchor.position


## True once the body is inside the tuned arrival radius. Without a radius the
## pull would overshoot and oscillate around the anchor forever, since the
## velocity is constant rather than damped.
func has_arrived(from: Vector3) -> bool:
	if _anchor == null:
		return false
	return from.distance_to(_anchor.position) <= arrival_radius()


## Velocity that carries the body toward the anchor. Constant speed straight down
## the tongue: the tongue is taut, so the pull does not steer, and a player who
## fires it commits to the arc. Vector3.ZERO when detached or already arrived.
func pull_velocity(from: Vector3) -> Vector3:
	if _anchor == null or has_arrived(from):
		return Vector3.ZERO
	return (_anchor.position - from).normalized() * pull_speed()

extends GdUnitTestSuite

func test_channel_descends_without_a_backwards_segment() -> void:
	var previous: Vector3 = LagoonStreamPath.point(0)
	var length: float = LagoonStreamPath.curve().get_baked_length()
	for i: int in range(1,101):
		var next: Vector3 = LagoonStreamPath.point(length*float(i)/100)
		assert_bool(next.z < previous.z).is_true()
		assert_bool(next.y <= previous.y).is_true()
		assert_bool(absf(next.x) < 5.0).is_true()
		previous = next
	assert_bool(previous.is_equal_approx(Vector3(3,-6.8,-52))).is_true()

func test_stream_meets_existing_lagoon_channel_at_the_same_height() -> void:
	var entrance: Vector3 = LagoonStreamPath.point(0)
	assert_float(entrance.y).is_equal_approx(LagoonHydrology.channel_surface(entrance.z),0.001)
	assert_bool(LagoonStreamPath.curve().get_baked_length() > 43).is_true()

func test_cave_darkness_has_gradual_entrance_and_exit() -> void:
	assert_float(LagoonStreamPath.enclosure(-9)).is_equal_approx(0.0,0.001)
	assert_bool(LagoonStreamPath.enclosure(-12) < LagoonStreamPath.enclosure(-16)).is_true()
	assert_bool(LagoonStreamPath.enclosure(-30) > 0.99).is_true()
	assert_bool(LagoonStreamPath.enclosure(-48) < LagoonStreamPath.enclosure(-44)).is_true()
	assert_float(LagoonStreamPath.enclosure(-54)).is_equal_approx(0.0,0.001)

func test_lagoon_floor_is_excavated_below_the_passage() -> void:
	var ground := LagoonHydrology.new()
	ground.continuous_stream = true
	for z: float in [-12.0,-16.0,-20.0,-23.0]:
		var center: Vector3 = LagoonStreamPath.at_z(z)
		assert_bool(ground.floor_height(Vector2(center.x,z)) < center.y-2.2).is_true()
	ground.free()

func test_flat_water_retains_its_original_slope_and_no_cave_darkening() -> void:
	var water := WaterVolume.new()
	water.surface_gradient = Vector2(0,0.19)
	assert_bool(water.surface_slope_at(Vector3.ZERO).is_equal_approx(Vector2(0,0.19))).is_true()
