extends RefCounted
## Bake local water depth into unused terrain vertex colour channels.
## Geometry, collision, planting masks and runtime water authority stay intact.
var world: Node3D
var zones: Array[Dictionary] = []
var materials: Dictionary = {}
var stats := {"meshes":0,"vertices":0,"submerged_vertices":0,"sections":{}}

func pose(node: Node3D) -> Transform3D:
	var t := node.transform
	var parent := node.get_parent()
	while parent!=world and parent is Node3D:
		t=(parent as Node3D).transform*t
		parent=parent.get_parent()
	return t

func collect(target: Node3D) -> void:
	world=target
	zones.clear()
	var channels: Dictionary = {}
	for volume: WaterVolume in world.find_children("*","WaterVolume",true,false):
		var vt := pose(volume)
		var zone := {"pose":vt,"inverse":vt.affine_inverse(),"height":volume.surface_height,"gradient":volume.surface_gradient,"priority":volume.water_priority,"boxes":[],"profile":null}
		var script := volume.get_script() as Script
		var is_channel := script!=null and script.resource_path.ends_with("channel_water_volume.gd")
		if is_channel:
			var path := String(volume.get("profile_path"))
			if channels.has(path):
				zone=channels[path]
			else:
				var profile := preload("res://core/controller/channel_profile.gd").new()
				profile.source_path=path; profile.initialize()
				zone["profile"]=profile
				zone["pose"]=pose(volume.get_parent() as Node3D)
				zone["inverse"]=(zone["pose"] as Transform3D).affine_inverse()
				channels[path]=zone
				zones.append(zone)
		elif not volume.explicit_surface:
			var found := false
			for visual: MeshInstance3D in volume.find_children("*","MeshInstance3D",true,false):
				if visual.mesh is BoxMesh:
					var mt := pose(visual)
					zone["height"]=(mt*Vector3(0,(visual.mesh as BoxMesh).size.y*0.5,0)).y-vt.origin.y
					found=true; break
			if not found: continue
		if not is_channel: zones.append(zone)
		for shape: CollisionShape3D in volume.find_children("*","CollisionShape3D",true,false):
			if shape.disabled or not shape.shape is BoxShape3D: continue
			var t := pose(shape)
			zone["boxes"].append({"inverse":t.affine_inverse(),"half":(shape.shape as BoxShape3D).size*0.5})
	# Scenic source pools have visible water but intentionally no gameplay Area.
	for visual: MeshInstance3D in world.get_node("CustomLandscape").find_children("*","MeshInstance3D",true,false):
		if not visual.mesh is PlaneMesh: continue
		if not String(visual.name) in ["S04_HeadwaterFlow","S04_ImpactPool","S05_HeadwaterFlow","S05_ShallowRunoff"]: continue
		var t := pose(visual)
		var size := (visual.mesh as PlaneMesh).size
		zones.append({"pose":t,"inverse":t.affine_inverse(),"height":0.0,"gradient":Vector2.ZERO,"priority":100,"profile":null,"boxes":[{"inverse":t.affine_inverse(),"half":Vector3(size.x*0.5,0.5,size.y*0.5)}]})

func sample(point: Vector3) -> Dictionary:
	var selected := false
	var best_priority := -100000
	var height := -INF
	var nearest_distance := INF
	var nearest_height := -INF
	for zone: Dictionary in zones:
		var inside := false
		var zone_distance := INF
		for box: Dictionary in zone["boxes"]:
			var p: Vector3=(box["inverse"] as Transform3D)*point
			var half: Vector3=box["half"]
			# A narrow tolerance includes the bed skin. The lower bound keeps a
			# raised source pool from tinting unrelated ground beneath it.
			if p.y< -half.y-0.40:continue
			zone_distance=minf(zone_distance,Vector2(maxf(absf(p.x)-half.x,0),maxf(absf(p.z)-half.z,0)).length_squared())
			if absf(p.x)<=half.x+0.08 and absf(p.z)<=half.z+0.08:
				inside=true;break
		if not inside and zone_distance>=nearest_distance: continue
		var local: Vector3=(zone["inverse"] as Transform3D)*point
		var surface: float=zone["height"]
		if zone["profile"]!=null:
			surface=float(zone["profile"].sample(local)["surface"])
		else:
			surface+=(zone["gradient"] as Vector2).dot(Vector2(local.x,local.z))
		surface=((zone["pose"] as Transform3D)*Vector3(local.x,surface,local.z)).y
		if zone_distance<nearest_distance:
			nearest_distance=zone_distance;nearest_height=surface
		if not inside:continue
		var priority := int(zone["priority"])
		if not selected or priority>best_priority or (priority==best_priority and surface>height):
			selected=true;best_priority=priority;height=surface
	# Keep the depth field continuous across shoreline triangles. Coverage still
	# prevents the neighbouring dry ground from receiving underwater shading.
	var reference := height if selected else nearest_height
	return {"covered":selected,"depth":reference-point.y if not is_inf(reference) else -4.0,"surface":reference}

func apply(target: Node3D) -> void:
	collect(target)
	for visual: MeshInstance3D in world.find_children("*","MeshInstance3D",true,false):
		var mat := visual.material_override as ShaderMaterial
		if mat==null or not mat.shader.resource_path.ends_with("cascade_pbr_ground.gdshader"): continue
		# Only authored floor, ramp and bank meshes; leave wall and prop materials.
		if not String(visual.name) in ["SculptedTerrain","ChannelBed","CarvedChannel"]: continue
		if float(mat.get_shader_parameter("surface_kind"))>=1.5: continue
		var source := visual.mesh as ArrayMesh
		if source==null: continue
		var mesh := ArrayMesh.new()
		var transform := pose(visual)
		var section := String((visual.get_parent() as Node).get_meta("terrain_section","S06"))
		for i in range(source.get_surface_count()):
			var arrays := source.surface_get_arrays(i)
			var vertices: PackedVector3Array=arrays[Mesh.ARRAY_VERTEX]
			var colors: PackedColorArray=arrays[Mesh.ARRAY_COLOR]
			if colors.size()!=vertices.size():colors.resize(vertices.size());colors.fill(Color(0,0,0,1))
			for v in range(vertices.size()):
				var row := sample(transform*vertices[v])
				var color := colors[v]
				color.g=clampf((float(row["depth"])+4.0)/8.0,0.0,1.0)
				color.b=1.0 if row["covered"] else 0.0
				colors[v]=color
				stats["vertices"]+=1
				if row["covered"] and float(row["depth"])>0:stats["submerged_vertices"]+=1
			arrays[Mesh.ARRAY_COLOR]=colors
			mesh.add_surface_from_arrays(source.surface_get_primitive_type(i),arrays)
			mesh.surface_set_material(i,source.surface_get_material(i))
		visual.mesh=mesh
		if not materials.has(mat):
			var detailed := mat.duplicate() as ShaderMaterial
			detailed.set_shader_parameter("depth_blend_enabled",true)
			materials[mat]=detailed
		visual.material_override=materials[mat]
		stats["meshes"]+=1
		stats["sections"][section]=int(stats["sections"].get(section,0))+1
	world.get_node("CustomLandscape").set_meta("ground_depth_statistics",stats)
	print("GROUND DEPTH: ",JSON.stringify(stats))

// Shared transparent water: lit ripples, depth absorption, shoreline foam and wakes.
shader_type spatial;
render_mode blend_mix, cull_disabled, depth_draw_never, specular_schlick_ggx;
global uniform vec4 water_actor;
global uniform vec4 water_motion;
uniform sampler2D depth_buffer : hint_depth_texture, filter_nearest;
uniform sampler2D scene_color : hint_screen_texture, repeat_disable, filter_linear;
uniform vec3 deep_tint : source_color = vec3(0.04,0.31,0.40);
uniform vec3 shallow_tint : source_color = vec3(0.26,0.64,0.64);
uniform vec3 foam_tint : source_color = vec3(0.87,0.96,0.97);
uniform float alpha_facing = 0.16;
uniform float alpha_grazing = 0.52;
uniform float ripple_scale = 0.8;
uniform float ripple_speed = 0.65;
uniform float wave_height = 0.075;
uniform float normal_strength = 0.19;
uniform float shore_band_share = 0.12;
uniform float shore_foam = 0.12;
uniform float shallows_depth_m = 0.35;
uniform float shallows_foam = 0.23;
uniform bool mesh_is_surface = false;
uniform vec2 flow_velocity = vec2(0.0);
uniform bool flow_uses_uv = false;
uniform float flow_exit_z = -100000.0;
uniform float turbulence = 0.0;
varying vec3 world_position;
varying vec3 world_normal;
varying float shore;
varying float top_face;

float caustic(vec2 p, float t) {
    vec2 cell=floor(p), local=fract(p);
    float first=8.0, second=8.0;
    for(int y=-1;y<=1;y++) {
        for(int x=-1;x<=1;x++) {
            vec2 neighbor=vec2(float(x),float(y));
            vec2 seed=cell+neighbor;
            vec2 phase=fract(sin(vec2(dot(seed,vec2(127.1,311.7)),dot(seed,vec2(269.5,183.3))))*43758.5453);
            vec2 center=neighbor+0.5+0.27*sin(phase*6.28318+t)-local;
            float d=dot(center,center);
            if(d<first) { second=first; first=d; }
            else { second=min(second,d); }
        }
    }
    return 1.0-smoothstep(0.025,0.14,second-first);
}

float wave(vec2 p, float t) {
    return (sin(dot(p,vec2(1.7,0.6))+t*1.1)
          +0.55*sin(dot(p,vec2(-0.9,2.3))-t*0.83)
          +0.23*sin(dot(p,vec2(3.8,2.1))+t*1.45))/1.78;
}
vec2 wave_slope(vec2 p, float t) {
    vec2 slope=vec2(
        wave(p+vec2(0.03,0.0),t)-wave(p-vec2(0.03,0.0),t),
        wave(p+vec2(0.0,0.03),t)-wave(p-vec2(0.0,0.03),t))/0.06;
    return slope+vec2(cos(dot(p,vec2(8.2,3.7))-t*2.4),cos(dot(p,vec2(-4.9,9.1))+t*1.8))*0.18;
}
void vertex() {
    vec2 face=mesh_is_surface ? UV : (UV-vec2(1.0/3.0,0.5))*vec2(3.0,2.0);
    vec2 inset=0.5-abs(face-0.5);
    shore=mesh_is_surface ? 1.0 : clamp(min(inset.x,inset.y)*2.0/shore_band_share,0.0,1.0);
    top_face=smoothstep(0.65,0.95,NORMAL.y);
    vec3 placed=(MODEL_MATRIX*vec4(VERTEX,1.0)).xyz;
    float outlet=flow_uses_uv ? smoothstep(flow_exit_z,flow_exit_z+4.0,placed.z) : 1.0;
    VERTEX.y+=top_face*shore*wave_height*outlet*wave((placed.xz-flow_velocity*TIME)*ripple_scale,TIME*ripple_speed);
    world_position=(MODEL_MATRIX*vec4(VERTEX,1.0)).xyz;
    world_normal=normalize(MODEL_NORMAL_MATRIX*NORMAL);
}
void fragment() {
    vec2 p=((flow_uses_uv ? UV : world_position.xz)-flow_velocity*TIME)*ripple_scale;
    float t=TIME*ripple_speed;
    float outlet=flow_uses_uv ? smoothstep(flow_exit_z,flow_exit_z+4.0,world_position.z) : 1.0;
    vec2 slope=wave_slope(p,t);
    if(flow_uses_uv) {
        // Match the receiving water's world-space normal phase at the join.
        slope=mix(wave_slope(world_position.xz*ripple_scale,t),slope,outlet);
        p=mix(world_position.xz*ripple_scale,p,outlet);
    }

    vec2 offset=world_position.xz-water_actor.xz;
    vec2 direction=normalize(water_motion.xz+vec2(0.0001));
    float aft=-dot(offset,direction);
    float lateral=abs(dot(offset,vec2(-direction.y,direction.x)));
    float active=water_actor.w*(1.0-smoothstep(0.15,0.7,abs(world_position.y-water_actor.y)));
    float wake=exp(-pow((lateral-aft*0.32)*7.0,2.0))*smoothstep(0.0,0.4,aft)*(1.0-smoothstep(0.5,4.0,aft))*active;
    slope+=vec2(sin(aft*14.0-t*5.0),cos(lateral*12.0-t*3.0))*wake*0.5;

    vec3 n=normalize(world_normal+vec3(-slope.x*normal_strength,0.0,-slope.y*normal_strength)*top_face);
    NORMAL=normalize((VIEW_MATRIX*vec4(n,0.0)).xyz);
    if(!FRONT_FACING) NORMAL=-NORMAL;
    float facing=clamp(abs(dot(NORMAL,normalize(VIEW))),0.0,1.0);
    float fresnel=pow(1.0-facing,5.0);

    float raw_depth=texture(depth_buffer,SCREEN_UV).r;
    vec4 behind=INV_PROJECTION_MATRIX*vec4(SCREEN_UV*2.0-1.0,raw_depth,1.0);
    float thickness=max(0.0,VERTEX.z-behind.z/behind.w);
    float absorption=1.0-exp(-thickness*0.12);
    float shallows=1.0-smoothstep(0.015,shallows_depth_m,thickness);
    float pulse=0.55+0.45*sin(dot(p,vec2(6.2,4.3))-t*2.2);
    float surf=shallows*shallows_foam*pulse*top_face;
    surf=max(surf,(1.0-shore)*shore_foam*pulse*top_face);
    if(flow_uses_uv) surf=max(surf,(1.0-outlet)*shore_foam*pulse*top_face);
    float streak=pow(0.5+0.5*sin(p.x*24.0+sin(p.y*5.0-t*4.0)),12.0);
    float foam=clamp(surf+wake*0.20+streak*turbulence*outlet*0.23,0.0,0.55);
    vec3 tint=mix(shallow_tint,deep_tint,absorption);
    ALBEDO=mix(tint,foam_tint,foam);
    ROUGHNESS=clamp(0.085+foam*0.3+turbulence*outlet*0.04,0.08,0.4);
    METALLIC=0.0;
    SPECULAR=0.5;
    ALPHA=clamp(mix(alpha_facing,0.30,absorption)+fresnel*alpha_grazing+foam*0.45,0.03,0.72);
    if(top_face>0.5 && FRONT_FACING) {
        vec2 refracted_uv=clamp(SCREEN_UV+slope*0.004*min(thickness,2.0),vec2(0.001),vec2(0.999));
        float refracted_depth=texture(depth_buffer,refracted_uv).r;
        vec4 refracted_point=INV_PROJECTION_MATRIX*vec4(refracted_uv*2.0-1.0,refracted_depth,1.0);
        if(refracted_point.z/refracted_point.w>VERTEX.z) refracted_uv=SCREEN_UV;
        vec3 transmitted=textureLod(scene_color,refracted_uv,0.0).rgb;
        // Project the light pattern onto the submerged geometry, not the surface.
        vec3 bed=(INV_VIEW_MATRIX*vec4(behind.xyz/behind.w,1.0)).xyz;
        float water_depth=max(0.0,world_position.y-bed.y);
        float focus=caustic(bed.xz*2.2+sin(bed.zx*0.7+t*0.3)*0.15,t*0.7);
        float light_pattern=(focus-0.25)*0.13*(0.55+0.45*sin(bed.x*1.4+sin(bed.z*1.2-t)))*smoothstep(0.02,0.18,water_depth)*exp(-water_depth*0.22);
        transmitted*=1.0+light_pattern;
        vec3 attenuation=exp(-vec3(0.58,0.17,0.10)*min(thickness,18.0));
        transmitted=transmitted*attenuation+deep_tint*(1.0-attenuation)*0.45;
        EMISSION=transmitted*(1.0-foam)*(1.0-fresnel);
        ALBEDO=mix(tint*0.035,foam_tint,foam);
        ALPHA=0.96;
    }
    // A submerged view should not see an opaque, brightly lit box side.
    if(top_face<0.1) ALPHA*=0.35;
}

extends GdUnitTestSuite

## The world dressing (REQ-034): the shared environment kit and the rule
## that keeps it safe — decoration is VISUAL ONLY. A prop that collided
## would invalidate every tuned probe and walk; a prop that grouped would
## become a contract element by accident. So the structure held here is:
## every dressed scene carries kit instances under a Dressing container,
## and that container's whole subtree has no physics and no groups.

const KIT_PROPS: Array[String] = [
	"rock_cluster", "coral_branch", "kelp_strand", "seagrass_tuft",
]
const DRESSED_SCENES: Array[String] = [
	"res://hub/open_lagoon.tscn",
	"res://worlds/coral_cove/world.tscn",
	"res://worlds/bubble_bay/world.tscn",
]
const WATERED_SCENES: Array[String] = [
	"res://worlds/coral_cove/world.tscn",
	"res://worlds/bubble_bay/world.tscn",
]


func test_every_kit_prop_loads_with_meshes_and_vertex_colour_albedo() -> void:
	for prop: String in KIT_PROPS:
		var path := "res://assets/environment/%s/%s.glb" % [prop, prop]
		var packed: PackedScene = load(path)
		assert_object(packed).override_failure_message(
			"%s failed to load" % path).is_not_null()
		var root := packed.instantiate()
		var meshes := root.find_children("*", "MeshInstance3D", true, false)
		assert_int(meshes.size()).is_greater_equal(1)
		for node: Node in meshes:
			var material := (node as MeshInstance3D).mesh.surface_get_material(0)
			assert_bool(material is BaseMaterial3D
				and (material as BaseMaterial3D).vertex_color_use_as_albedo
				).override_failure_message(
				"%s must read its palette from vertex colours; a kit prop "
				% prop + "without them renders white").is_true()
		root.free()


func test_dressed_scenes_carry_props_and_the_dressing_is_visual_only() -> void:
	for scene_path: String in DRESSED_SCENES:
		var scene := (load(scene_path) as PackedScene).instantiate()
		var containers := scene.find_children("Dressing", "", true, false)
		assert_int(containers.size()).override_failure_message(
			"%s must carry one Dressing container" % scene_path).is_equal(1)
		var dressing := containers[0] as Node

		# Props reach a world two ways now, and the count has to see both.
		# A prop can still be its own scene instance, but the bulk of a
		# dressed world is SCATTERED: one ScatterField per prop type, drawing
		# every instance of it in a single call. Counting only scene instances
		# would have read the converted valley as undressed while it carried
		# 183 plants — the assertion would have failed for a change that made
		# the dressing better, and someone would have deleted the assertion.
		var instanced := 0
		for node: Node in dressing.get_children():
			if node.scene_file_path.begins_with("res://assets/environment/"):
				instanced += 1
			var field := node as ScatterField
			if field != null:
				instanced += field.instance_count()
		assert_int(instanced).override_failure_message(
			"%s: a Dressing container with fewer than a dozen props is not "
			% scene_path + "dressed").is_greater_equal(12)

		# Visual only: no physics object and no group anywhere beneath it.
		for node: Node in dressing.find_children("*", "", true, false):
			assert_int((node.get_groups() as Array).size()
				).override_failure_message(
				"%s: dressing node %s carries a group; decoration must "
				% [scene_path, node.name]
				+ "never become a contract element").is_equal(0)
		assert_int(dressing.find_children("*", "CollisionObject3D", true,
			false).size()).override_failure_message(
			"%s: dressing must not collide" % scene_path).is_equal(0)
		scene.free()


func test_water_volumes_in_official_worlds_carry_bubbles() -> void:
	for scene_path: String in WATERED_SCENES:
		var scene := (load(scene_path) as PackedScene).instantiate()
		var volumes := scene.find_children("*", "WaterVolume", true, false)
		assert_int(volumes.size()).is_greater_equal(1)
		for volume: Node in volumes:
			var particles := volume.find_children("*", "GPUParticles3D",
				true, false)
			assert_int(particles.size()).override_failure_message(
				"%s: the water volume must carry its bubble particles"
				% scene_path).is_greater_equal(1)
			var bubbles := particles[0] as GPUParticles3D
			assert_object(bubbles.process_material).is_not_null()
			assert_object(bubbles.draw_pass_1).is_not_null()
		scene.free()

extends GdUnitTestSuite

## Balance and Tuning Data — REQ-025.
##
## Test names carry the requirement id they prove (test_req_025_...) so the
## harness can parse it back out and report it as the failing rule (REQ-026 AC-6).

const REAL_TUNING_PATH := "res://core/tuning/tuning.json"

## Every tuning key cited by ANOTHER requirement's acceptance criteria.
##
## REQ-025 AC-7 makes this node responsible for the whole project's tuning-key
## integrity. This list is the single place to update when a requirement gains a
## new cited key — keep it sorted and keep the citing requirement in the comment.
const CITED_KEYS: PackedStringArray = [
	"camera.smoothing.max_position_delta_m_per_frame",  # REQ-005 AC-1
	"camera.smoothing.max_rotation_delta_deg_per_frame",  # REQ-005 AC-1
	"capability.gill_loss.boost_duration_multiplier",  # REQ-004 AC-5
	"controller.grapple.max_range_m",  # REQ-001 AC-4
	"controller.transition.momentum_retention_ratio",  # REQ-001 AC-1
	"enemy.hookline.mod_strip_seconds",  # REQ-004 AC-6, REQ-012 AC-2
	"enemy.runoff.duration_s",  # REQ-012 AC-4
	"enemy.runoff.gill_recharge_multiplier",  # REQ-012 AC-4
	"enemy.runoff.vision_debuff_factor",  # REQ-012 AC-4
	"progression.max_retry_seconds",  # REQ-003 AC-6
	"regen.mutation.duration_s",  # REQ-002 AC-5
]

## The categories REQ-025 AC-2 requires the surface to cover, each with a key
## prefix that must be present.
const REQUIRED_COVERAGE: Dictionary = {
	"capability-loss modifiers": "capability.",
	"default lives per attempt": "progression.default_lives_per_attempt",
	"dash charge and recharge": "controller.dash.",
	"Gill Mod durations and cooldowns": "gillmod.",
	"enemy debuff magnitudes and windows": "enemy.",
	"restoration resource costs": "restoration.",
	"grapple range": "controller.grapple.",
	"camera smoothing thresholds": "camera.smoothing.",
	"mutation loadout duration": "regen.mutation.duration_s",
	"momentum retention": "controller.transition.momentum_retention_ratio",
	"maximum retry duration": "progression.max_retry_seconds",
}

var _temp_dir: String = ""


func before_test() -> void:
	_temp_dir = create_temp_dir("tuning")


func _write_tuning(body: Dictionary) -> String:
	var path := _temp_dir.path_join("tuning_%d.json" % Time.get_ticks_usec())
	var handle := FileAccess.open(path, FileAccess.WRITE)
	handle.store_string(JSON.stringify(body))
	handle.close()
	return path


func _minimal_entry(value: float, minimum: float, maximum: float) -> Dictionary:
	return {
		"value": value,
		"unit": "ratio",
		"min": minimum,
		"max": maximum,
		"description": "fixture value",
	}


func _load_real() -> TuningData:
	var errors: Array[TuningError] = []
	var data := TuningData.load_from_file(REAL_TUNING_PATH, errors)
	assert_array(errors).is_empty()
	assert_object(data).is_not_null()
	return data


# --- AC-1: values live in data, not constants -------------------------------

func test_req_025_values_are_defined_in_data_not_code() -> void:
	# The shipped tuning file is the source; the loader holds no hardcoded values.
	var data := _load_real()
	assert_int(data.get_keys().size()).is_greater(0)

	# Nothing in the tuning source declares a balance number as a GDScript const.
	var source := FileAccess.open("res://core/tuning/tuning_data.gd", FileAccess.READ)
	var text := source.get_as_text()
	source.close()
	assert_str(text).not_contains("const DEFAULT_MOMENTUM")
	assert_bool(text.contains("JSON.parse_string")).is_true()


# --- AC-2: the surface covers every enumerated category ---------------------

func test_req_025_tuning_surface_covers_every_required_category() -> void:
	var data := _load_real()
	var keys := data.get_keys()

	for category: String in REQUIRED_COVERAGE:
		var needle: String = REQUIRED_COVERAGE[category]
		var found := false
		for key: String in keys:
			if key.begins_with(needle):
				found = true
				break
		assert_bool(found).override_failure_message(
			"REQ-025 AC-2: no tuning key covers '%s' (expected a key matching '%s')"
			% [category, needle]
		).is_true()


# --- AC-3: name, unit and permitted range on every value --------------------

func test_req_025_every_value_carries_name_unit_and_range() -> void:
	var data := _load_real()
	for key: String in data.get_keys():
		assert_str(data.get_unit(key)).override_failure_message(
			"REQ-025 AC-3: '%s' has no unit" % key).is_not_empty()
		assert_str(data.get_description(key)).override_failure_message(
			"REQ-025 AC-3: '%s' has no description" % key).is_not_empty()

		var bounds := data.get_permitted_range(key)
		assert_int(bounds.size()).override_failure_message(
			"REQ-025 AC-3: '%s' has no permitted range" % key).is_equal(2)
		assert_bool(bounds[0] <= bounds[1]).override_failure_message(
			"REQ-025 AC-3: '%s' has an inverted range" % key).is_true()

		var value := data.get_number(key)
		assert_bool(value >= bounds[0] and value <= bounds[1]).override_failure_message(
			"REQ-025 AC-3: '%s' value %s is outside its own declared range [%s, %s]"
			% [key, value, bounds[0], bounds[1]]
		).is_true()


# --- AC-4: changing a value changes behavior, no code change, no recompile ---

func test_req_025_changing_a_value_alters_behavior_without_code_change() -> void:
	var key := "controller.grapple.max_range_m"
	var body := {
		"schemaVersion": "1.0",
		"worldOverridable": [],
		"values": {key: _minimal_entry(12.0, 1.0, 60.0)},
	}

	var first_path := _write_tuning(body)
	var errors: Array[TuningError] = []
	var before := TuningData.load_from_file(first_path, errors)
	assert_array(errors).is_empty()
	assert_float(before.get_number(key)).is_equal_approx(12.0, 0.0001)

	# Same code path, same binary — only the data file differs.
	body["values"][key]["value"] = 30.0
	var second_path := _write_tuning(body)
	errors.clear()
	var after := TuningData.load_from_file(second_path, errors)
	assert_array(errors).is_empty()
	assert_float(after.get_number(key)).is_equal_approx(30.0, 0.0001)


# --- AC-5: world overrides are a closed, enumerated set ---------------------

func test_req_025_world_override_inside_sanctioned_set_is_applied() -> void:
	var data := _load_real()
	var key := data.get_world_overridable_keys()[0]
	var bounds := data.get_permitted_range(key)

	var errors: Array[TuningError] = []
	var applied := data.apply_world_overrides({key: bounds[1]}, errors)

	assert_bool(applied).is_true()
	assert_array(errors).is_empty()
	assert_float(data.get_number(key)).is_equal_approx(bounds[1], 0.0001)


func test_req_025_world_override_outside_sanctioned_set_is_rejected() -> void:
	var data := _load_real()
	# A real key, deliberately global: movement stays coherent across forks.
	var key := "controller.transition.momentum_retention_ratio"
	assert_bool(data.is_world_overridable(key)).is_false()

	var before := data.get_number(key)
	var errors: Array[TuningError] = []
	var applied := data.apply_world_overrides({key: 0.1}, errors)

	assert_bool(applied).is_false()
	assert_int(errors.size()).is_equal(1)
	assert_str(errors[0].code).is_equal(TuningError.OVERRIDE_NOT_PERMITTED)
	assert_str(errors[0].key).is_equal(key)
	# Rejected means nothing applied, not partially applied.
	assert_float(data.get_number(key)).is_equal_approx(before, 0.0001)


func test_req_025_world_override_set_is_rejected_wholesale_on_any_violation() -> void:
	var data := _load_real()
	var permitted := data.get_world_overridable_keys()[0]
	var forbidden := "controller.grapple.max_range_m"
	var before := data.get_number(permitted)

	var errors: Array[TuningError] = []
	var applied := data.apply_world_overrides(
		{permitted: data.get_permitted_range(permitted)[1], forbidden: 2.0}, errors)

	assert_bool(applied).is_false()
	# The legal half must NOT have landed — a world never runs half-overridden.
	assert_float(data.get_number(permitted)).is_equal_approx(before, 0.0001)


