{
  "contractVersion": "1.0",
  "description": "The Asset Contract (REQ-015): what any art or audio asset must satisfy to enter the repository. The art-side sibling of the Level Contract, and data for BOTH sides of the pipeline: the validator (oax-asset-check) enforces every machine-checkable rule here, and the Game Client and Audio System resolve assets at runtime from the same layout and naming facts. Style and art direction are documented in docs/asset-contract.md and reviewed by a human maintainer - deliberately absent from this file, because a machine-checkable style rule would reject legitimate work.",
  "assetsRoot": "assets",
  "layout": {
    "pattern": "assets/<category>/<name>/",
    "description": "One directory per asset, holding its source files and its provenance.json. Nothing lives loose in assets/ or in a category directory.",
    "namePattern": "^[a-z][a-z0-9_]*$",
    "nameDescription": "Asset directory names and file stems: lower_snake_case, starting with a letter. The same convention the tuning keys and save namespaces use, so one grep finds an asset everywhere it is referenced."
  },
  "provenance": {
    "file": "provenance.json",
    "schema": "contracts/provenance.schema.json",
    "description": "Required in EVERY asset directory. Records author, generation method and license terms; AI-generated assets additionally record the tool and prompt. This is a licensing instrument, not bookkeeping."
  },
  "requiredPerAsset": [
    "at least one conforming source file",
    "provenance.json"
  ],
  "models": {
    "fileType": ".glb",
    "description": "3D assets are binary glTF 2.0, one .glb per asset directory beside any textures it uses. Godot imports glTF natively - meshes, skeletons, materials, animation clips - so no conversion step exists to drift. Each category that carries meshes declares a triangle budget: the validator reads the file's JSON chunk (its header) and sums primitive index counts, never decoding geometry. Godot's <file>.import sidecars are engine bookkeeping, not sources, and are ignored wherever they appear.",
    "deviationDescription": "Each mesh category also declares maxDeviation: how far a decimated surface may stray from the dense source it came from, as a fraction of the bounding-box diagonal, measured in BOTH directions by oax-decimate. The numbers rise with distance from the camera and with how little the strayed geometry means. Half a percent on a character is about two screen pixels: a two-metre hero fills roughly a third of a 1080p frame at gameplay camera distance, so one pixel is a fifth of a percent of its diagonal - and every one of those pixels is silhouette the player reads all game. A Drift Fleet machine is engaged further out and strays at its hardware rather than its outline; set dressing recedes into the teal depth fog. Holding those to the hero's number would not buy sharper silhouettes, it would buy triangles nobody can see, which is exactly what this tool exists to remove. The looser ceilings are not licence to skip looking: a shipped asset is checked by render at its shipped count, and the gate's job is to catch the collapse to a coarse hull that a glance at a triangle count would call a success."
  },
  "categories": {
    "character": {
      "fileTypes": [".png", ".glb"],
      "minSize": [64, 64],
      "maxSize": [2048, 2048],
      "alpha": "required",
      "maxTriangles": 60000,
      "maxDeviation": 0.005,
      "why": "Characters composite over every background the game has; a character sprite or texture without an alpha channel ships a rectangle. The hero and named characters get the largest mesh budget: they are on screen every frame and closest to the camera - which is also why they carry the tightest deviation ceiling, since their silhouette is the one the player reads all game."
    },
    "creature": {
      "fileTypes": [".png", ".glb"],
      "minSize": [64, 64],
      "maxSize": [2048, 2048],
      "alpha": "required",
      "maxTriangles": 30000,
      "maxDeviation": 0.005,
      "why": "Same compositing rule as characters. Creatures appear in numbers, so each carries half a hero's mesh budget - but they share the hero's camera distance, so they keep the hero's deviation ceiling."
    },
    "prop": {
      "fileTypes": [".png", ".glb"],
      "minSize": [32, 32],
      "maxSize": [2048, 2048],
      "alpha": "required",
      "maxTriangles": 10000,
      "maxDeviation": 0.02,
      "why": "Props sit in scenes over arbitrary geometry, and a world places dozens of them. Ten thousand triangles is the CEILING for a file entering the repository, not a target to fill: a world that instances ten of them at the ceiling has spent two thirds of its whole-scene budget on machinery alone, so shipped props are decimated to what the scene they live in can afford. Four times the hero's deviation allowance because the deviation is made of something different: a machine's worst-strayed point is its hardware - a railing, a hose, an intake lip - while a hero's is the outline the player reads all game. Losing pipework off a Dredger costs nothing that can be seen at gameplay distance, and each shipped machine is checked by render at its shipped count rather than trusted to the number alone."
    },
    "environment": {
      "fileTypes": [".png", ".glb"],
      "minSize": [128, 128],
      "maxSize": [4096, 4096],
      "alpha": "allowed",
      "maxTriangles": 200000,
      "maxDeviation": 0.03,
      "why": "Environment textures may be opaque (ground, walls) or cut-out (foliage); both are legitimate, so alpha is neither required nor forbidden. Environment meshes are a world's set dressing in one piece, hence the largest budget - and the same ceiling caveat as props: two hundred thousand is what may enter, while what ships is decimated to the scene budget. Set dressing recedes into the teal depth fog, so the same two pixels of silhouette error are worth six times the hero's fraction of a diagonal."
    },
    "audio": {
      "fileTypes": [".wav", ".ogg"],
      "maxChannels": 2,
      "sampleRates": [44100, 48000],
      "why": "Mono or stereo at one of the two standard rates; the Audio System's bus layout assumes nothing wider, and a 96kHz sample is repository weight with no audible payoff in this game."
    }
  }
}

class_name WorldRegistry
extends RefCounted

## Runtime world discovery for the Open Lagoon (REQ-009 AC-1, AC-3, AC-4).
##
## Scans a worlds directory at runtime, validates each module against the
## loaded Level Contract, and builds the portal list from what it finds. THERE
## IS NO WORLD LIST IN CODE, and no world's id appears anywhere in `hub/` —
## including no special case for the reference template, which must ride the
## identical path because that is what proves the path is generic. Adding,
## removing or replacing a module changes the portals on the next scan with no
## edit here (AC-3), which is the property that lets a world be forked or
## replaced without touching the hub.
##
## A module that fails to load or fails validation becomes an UNAVAILABLE
## portal carrying its failure reasons; it never propagates an error into the
## hub (AC-4). The scan itself cannot crash on a module's content: validation
## reads files as text and data, and a module's scene is only ever instantiated
## AFTER it has passed.
##
## The directory is a constructor argument (defaulting to res://worlds) so the
## discovery behaviour itself is testable against a scratch directory — the
## add/remove/replace criterion is proven by actually adding and removing
## modules, not by reading this comment.

const DEFAULT_WORLDS_DIR := "res://worlds"

var _worlds_dir: String
var _validator: ContractValidator
var _portals: Array[WorldPortal] = []


func _init(worlds_dir: String = DEFAULT_WORLDS_DIR,
		validator: ContractValidator = null) -> void:
	_worlds_dir = worlds_dir
	_validator = validator if validator != null else ContractValidator.new()


## Scans the directory and rebuilds the portal list. Safe to call again at any
## time — the hub refreshes rather than restarting. A missing worlds directory
## yields an empty hub, not an error: a fresh fork with no worlds yet is a
## legitimate state.
func discover() -> Array[WorldPortal]:
	_portals = []
	var dir := DirAccess.open(_worlds_dir)
	if dir == null:
		return _portals

	var names := dir.get_directories()
	names.sort()
	for name: String in names:
		_portals.append(_build_portal(name))
	return _portals


func _build_portal(name: String) -> WorldPortal:
	var module_dir := _worlds_dir.path_join(name)
	var portal := WorldPortal.new(name, module_dir)

	var errors: Array[HubError] = []
	var conforming := _validator.validate_module(module_dir, errors)

	# Read the manifest for presentation fields even when validation failed —
	# an unavailable portal with its declared name is easier to debug than a
	# bare directory id. Never for anything load-bearing.
	var manifest := _read_manifest(module_dir)
	portal.display_name = String(manifest.get("displayName", name))
	portal.tier = PortalTier.from_manifest(manifest, errors)

	portal.failures = errors
	portal.available = conforming and errors.is_empty()
	if portal.available:
		portal.world_id = String(manifest.get("worldId", name))
	return portal


func get_portals() -> Array[WorldPortal]:
	return _portals.duplicate()


func get_available() -> Array[WorldPortal]:
	var out: Array[WorldPortal] = []
	for portal: WorldPortal in _portals:
		if portal.available:
			out.append(portal)
	return out


func get_unavailable() -> Array[WorldPortal]:
	var out: Array[WorldPortal] = []
	for portal: WorldPortal in _portals:
		if not portal.available:
			out.append(portal)
	return out


func get_portal(world_id: String) -> WorldPortal:
	for portal: WorldPortal in _portals:
		if portal.world_id == world_id:
			return portal
	return null


## Fills each portal's completion and restoration progress from the Save
## Integration Interface (AC-6). The hub reads a world's namespaced data
## through the save system's API and NEVER opens the save file itself — the
## save format stays the Save System's private business.
func apply_progress(save: SaveSystem) -> void:
	for portal: WorldPortal in _portals:
		var data := save.get_world_data(portal.world_id)
		portal.completed = bool(data.get("completed", false))

		var regions := data.get("regions", {}) as Dictionary
		portal.regions_total = regions.size()
		portal.regions_restored = 0
		for key: Variant in regions:
			var region: Variant = regions[key]
			if region is Dictionary \
					and String((region as Dictionary).get("state", "")) == "restored":
				portal.regions_restored += 1


func _read_manifest(module_dir: String) -> Dictionary:
	var path := module_dir.path_join("world.json")
	if not FileAccess.file_exists(path):
		return {}
	var handle := FileAccess.open(path, FileAccess.READ)
	if handle == null:
		return {}
	var parsed: Variant = JSON.parse_string(handle.get_as_text())
	handle.close()
	return parsed as Dictionary if parsed is Dictionary else {}

class_name TuningData
extends RefCounted

## The single authoritative tuning surface (REQ-025).
##
## Every balance value the game uses is defined in data and read through this
## interface at use time. Consumers must NOT copy a value into a [code]const[/code] at
## load — caching defeats the criterion that changing a tuning value alters
## observable behavior with no code change and no recompile.
##
## Construct with [method load_from_file]; it returns [code]null[/code] and populates
## [method get_load_errors] rather than raising, so a caller decides how to
## surface the failure. A file with a missing or out-of-range value never loads
## partially — strictness is this node's entire value.

const DEFAULT_TUNING_PATH := "res://core/tuning/tuning.json"

## Required per-entry fields. An entry missing any of these is malformed:
## "every value carries a documented name, unit, and permitted range".
const _REQUIRED_ENTRY_FIELDS: PackedStringArray = [
	"value", "unit", "min", "max", "description"
]

var _values: Dictionary = {}
var _world_overridable: PackedStringArray = []
var _schema_version: String = ""
var _errors: Array[TuningError] = []


## Loads and fully validates a tuning file. Returns null on any failure; the
## reasons are available from [method get_load_errors] on the returned instance
## only when loading succeeded, so failures are reported via [param out_errors].
static func load_from_file(path: String, out_errors: Array[TuningError] = []) -> TuningData:
	if not FileAccess.file_exists(path):
		out_errors.append(TuningError.new(
			TuningError.FILE_UNREADABLE, "", "no tuning file at '%s'" % path))
		return null

	var handle: FileAccess = FileAccess.open(path, FileAccess.READ)
	if handle == null:
		out_errors.append(TuningError.new(
			TuningError.FILE_UNREADABLE,
			"",
			"could not open '%s' (error %d)" % [path, FileAccess.get_open_error()]))
		return null

	var text: String = handle.get_as_text()
	handle.close()

	var parsed: Variant = JSON.parse_string(text)
	if parsed == null or not (parsed is Dictionary):
		out_errors.append(TuningError.new(
			TuningError.MALFORMED_JSON, "", "'%s' is not a JSON object" % path))
		return null

	return _from_dictionary(parsed as Dictionary, out_errors)


static func _from_dictionary(root: Dictionary, out_errors: Array[TuningError]) -> TuningData:
	var data := TuningData.new()
	data._schema_version = String(root.get("schemaVersion", ""))

	var raw_overridable: Variant = root.get("worldOverridable", [])
	if raw_overridable is Array:
		for entry: Variant in (raw_overridable as Array):
			data._world_overridable.append(String(entry))

	var raw_values: Variant = root.get("values", null)
	if not (raw_values is Dictionary):
		out_errors.append(TuningError.new(
			TuningError.MALFORMED_ENTRY, "", "tuning file has no 'values' object"))
		return null

	for key: Variant in (raw_values as Dictionary):
		var name: String = String(key)
		var entry: Variant = (raw_values as Dictionary)[key]
		if not (entry is Dictionary):
			out_errors.append(TuningError.new(
				TuningError.MALFORMED_ENTRY, name, "entry is not an object"))
			continue
		data._validate_entry(name, entry as Dictionary, out_errors)

	# An entry naming an override target that does not exist is a drifted list —
	# exactly what declaring the set in the data is meant to prevent.
	for name: String in data._world_overridable:
		if not data._values.has(name):
			out_errors.append(TuningError.new(
				TuningError.UNKNOWN_KEY,
				name,
				"listed in worldOverridable but absent from values"))

	if not out_errors.is_empty():
		return null
	return data


func _validate_entry(name: String, entry: Dictionary, out_errors: Array[TuningError]) -> void:
	for field: String in _REQUIRED_ENTRY_FIELDS:
		if not entry.has(field):
			out_errors.append(TuningError.new(
				TuningError.MALFORMED_ENTRY, name, "missing required field '%s'" % field))
			return

	var raw_value: Variant = entry["value"]
	if not (raw_value is float or raw_value is int):
		out_errors.append(TuningError.new(
			TuningError.MALFORMED_ENTRY, name, "value is not numeric"))
		return

	var value: float = float(raw_value)
	var minimum: float = float(entry["min"])
	var maximum: float = float(entry["max"])

	if minimum > maximum:
		out_errors.append(TuningError.new(
			TuningError.MALFORMED_ENTRY,
			name,
			"declared range is inverted (min %s > max %s)" % [minimum, maximum]))
		return

	if value < minimum or value > maximum:
		out_errors.append(TuningError.new(
			TuningError.OUT_OF_RANGE,
			name,
			"value %s outside permitted range [%s, %s]" % [value, minimum, maximum]))
		return

	_values[name] = entry.duplicate(true)


## Returns the value for [param key]. Read at use time — never cache the result.
## Pushes an error and returns 0.0 for an unknown key rather than inventing a
## default, so a typo surfaces instead of silently tuning nothing.
func get_number(key: String) -> float:
	if not _values.has(key):
		push_error("[%s] %s: not present in the tuning data" % [TuningError.MISSING_KEY, key])
		return 0.0
	return float((_values[key] as Dictionary)["value"])


## Integer-valued convenience for counts (lives, charges, resource costs).
func get_count(key: String) -> int:
	return int(round(get_number(key)))


func has_key(key: String) -> bool:
	return _values.has(key)


func get_unit(key: String) -> String:
	if not _values.has(key):
		return ""
	return String((_values[key] as Dictionary)["unit"])


func get_description(key: String) -> String:
	if not _values.has(key):
		return ""
	return String((_values[key] as Dictionary)["description"])


## Returns the inclusive permitted range as [code][min, max][/code], or an empty
## array for an unknown key.
func get_permitted_range(key: String) -> PackedFloat64Array:
	if not _values.has(key):
		return PackedFloat64Array()
	var entry := _values[key] as Dictionary
	return PackedFloat64Array([float(entry["min"]), float(entry["max"])])


func get_keys() -> PackedStringArray:
	var keys := PackedStringArray()
	for key: Variant in _values:
		keys.append(String(key))
	keys.sort()
	return keys


## The closed set a world may override through the Level Contract. Declared in
## the tuning data so the contract references one list rather than keeping a
## second that drifts.
func get_world_overridable_keys() -> PackedStringArray:
	return _world_overridable.duplicate()


func is_world_overridable(key: String) -> bool:
	return _world_overridable.has(key)


func get_schema_version() -> String:
	return _schema_version


func get_load_errors() -> Array[TuningError]:
	return _errors.duplicate()


## Applies a world's declared tuning overrides. An override of a key outside the
## sanctioned set, of an unknown key, or of a value outside the declared range is
## REJECTED — the whole override set is refused and nothing is applied, so a world
## never runs half-overridden. Returns true only when every override was applied.
func apply_world_overrides(
	overrides: Dictionary, out_errors: Array[TuningError] = []
) -> bool:
	var staged: Dictionary = {}

	for key: Variant in overrides:
		var name: String = String(key)

		if not _values.has(name):
			out_errors.append(TuningError.new(
				TuningError.UNKNOWN_KEY, name, "world overrides a key that does not exist"))
			continue

		if not is_world_overridable(name):
			out_errors.append(TuningError.new(
				TuningError.OVERRIDE_NOT_PERMITTED,
				name,
				"key is not in the sanctioned world-overridable set"))
			continue

		var raw: Variant = overrides[key]
		if not (raw is float or raw is int):
			out_errors.append(TuningError.new(
				TuningError.MALFORMED_ENTRY, name, "override value is not numeric"))
			continue

		var value: float = float(raw)
		var bounds := get_permitted_range(name)
		if value < bounds[0] or value > bounds[1]:
			out_errors.append(TuningError.new(
				TuningError.OUT_OF_RANGE,
				name,
				"override %s outside permitted range [%s, %s]" % [value, bounds[0], bounds[1]]))
			continue

		staged[name] = value

	if not out_errors.is_empty():
		return false

	for name: Variant in staged:
		(_values[name] as Dictionary)["value"] = staged[name]
	return true

extends GdUnitTestSuite

## Axolotl Controller — REQ-001.
##
## Test names carry the requirement id they prove (test_req_001_...) so the
## runner reports it as the failing rule (REQ-026 AC-6).

const TUNING_PATH := "res://core/tuning/tuning.json"


func _tuning() -> TuningData:
	var errors: Array[TuningError] = []
	var data := TuningData.load_from_file(TUNING_PATH, errors)
	assert_array(errors).is_empty()
	return data


func _controller() -> AxolotlController:
	return AxolotlController.new(_tuning())


func _intent(direction: Vector3 = Vector3.ZERO,
		verbs: Array[MovementGrammar.Verb] = [],
		sustained: Array[MovementGrammar.Verb] = []) -> PlayerIntent:
	return PlayerIntent.new(direction, verbs, sustained)


## Stands in for the live scene so AC-4's discovery order — group query, range
## filter, then line of sight — can be asserted without a scene tree or a
## physics server. It also COUNTS rays, which is how the test proves discovery
## is not a proximity scan: an out-of-range anchor must never cost a ray.
class FakeAnchorSource extends AnchorSource:
	var anchors: Array[GrappleAnchor] = []
	var group_queried: String = ""
	var blocked_ids: PackedStringArray = []
	var rays_cast: int = 0

	func query_anchors_in_group(group: String) -> Array[GrappleAnchor]:
		group_queried = group
		var out: Array[GrappleAnchor] = []
		# Only anchors in the queried group are visible — membership is the tag.
		out.assign(anchors)
		return out

	func has_line_of_sight(_from: Vector3, to: Vector3) -> bool:
		rays_cast += 1
		for anchor: GrappleAnchor in anchors:
			if anchor.position.is_equal_approx(to) \
					and blocked_ids.find(anchor.id) != -1:
				return false
		return true


func _source(anchors: Array[GrappleAnchor]) -> FakeAnchorSource:
	var source := FakeAnchorSource.new()
	source.anchors = anchors
	return source


# --- AC-1: same-frame grammar switch and momentum retention ----------------

func test_req_001_crossing_into_water_switches_grammar_in_the_same_step() -> void:
	var controller := _controller()
	controller.physics_step(0.016, false, _intent())
	assert_int(int(controller.get_grammar())).is_equal(MovementGrammar.Grammar.LAND)

	# The very call that observes water must already report the water grammar —
	# no intervening frame is rendered in the previous grammar.
	controller.physics_step(0.016, true, _intent())
	assert_int(int(controller.get_grammar())).override_failure_message(
		"REQ-001 AC-1: the grammar must switch in the same physics step as the crossing"
	).is_equal(MovementGrammar.Grammar.WATER)


func test_req_001_grammar_change_signal_fires_on_the_crossing_step() -> void:
	var controller := _controller()
	var seen: Array[int] = []
	controller.grammar_changed.connect(func(g: MovementGrammar.Grammar) -> void:
		seen.append(int(g)))

	controller.physics_step(0.016, false, _intent())
	controller.physics_step(0.016, true, _intent())

	assert_int(seen.size()).is_equal(2)  # initial settle, then the crossing
	assert_int(seen[1]).is_equal(MovementGrammar.Grammar.WATER)


func test_req_001_crossing_retains_momentum_magnitude_per_tuning_key() -> void:
	var tuning := _tuning()
	var ratio := tuning.get_number("controller.transition.momentum_retention_ratio")
	var controller := AxolotlController.new(tuning)

	controller.physics_step(0.016, true, _intent())
	controller.set_velocity(Vector3(0.0, -10.0, 0.0))  # diving hard
	var before := controller.get_velocity().length()

	controller.physics_step(0.016, false, _intent())  # surfacing

	assert_float(controller.get_velocity().length()).override_failure_message(
		"REQ-001 AC-1: momentum magnitude must carry at the tuned retention ratio"
	).is_equal_approx(before * ratio, 0.001)


func test_req_001_momentum_carries_as_magnitude_not_as_the_vector() -> void:
	# A swimmer surfacing keeps speed without keeping a heading into the ground.
	var controller := _controller()
	controller.physics_step(0.016, true, _intent())
	controller.set_velocity(Vector3(0.0, -10.0, 0.0))
	controller.physics_step(0.016, false, _intent())

	# Direction is preserved only as a unit vector scaled down; the magnitude is
	# what the criterion constrains, and it is strictly less than before.
	assert_bool(controller.get_velocity().length() < 10.0).is_true()
	assert_bool(controller.get_velocity().length() > 0.0).is_true()


func test_req_001_staying_in_one_grammar_does_not_re_emit_or_decay_momentum() -> void:
	var controller := _controller()
	controller.physics_step(0.016, true, _intent())

	var changes: Array[int] = []
	controller.grammar_changed.connect(func(g: MovementGrammar.Grammar) -> void:
		changes.append(int(g)))

	controller.set_velocity(Vector3(5.0, 0.0, 0.0))
	controller.physics_step(0.016, true, _intent())
	controller.physics_step(0.016, true, _intent())

	assert_array(changes).override_failure_message(
		"staying in one grammar must not re-emit a change or re-apply retention"
	).is_empty()


# --- AC-2 / AC-3: the two grammars own distinct verbs ----------------------

func test_req_001_water_grammar_supports_swimming_dive_and_bubble_boost() -> void:
	var controller := _controller()
	controller.physics_step(0.016, true, _intent())

	assert_bool(controller.supports(MovementGrammar.Verb.SWIM)).is_true()
	assert_bool(controller.supports(MovementGrammar.Verb.DIVE)).is_true()
	assert_bool(controller.supports(MovementGrammar.Verb.BUBBLE_BOOST)).is_true()
	# Land verbs are not available in water.
	assert_bool(controller.supports(MovementGrammar.Verb.WADDLE)).is_false()
	assert_bool(controller.supports(MovementGrammar.Verb.HOP)).is_false()
	assert_bool(controller.supports(MovementGrammar.Verb.CLIMB)).is_false()


func test_req_001_land_grammar_supports_waddle_hop_and_climb() -> void:
	var controller := _controller()
	controller.physics_step(0.016, false, _intent())

	assert_bool(controller.supports(MovementGrammar.Verb.WADDLE)).is_true()
	assert_bool(controller.supports(MovementGrammar.Verb.HOP)).is_true()
	assert_bool(controller.supports(MovementGrammar.Verb.CLIMB)).is_true()
	assert_bool(controller.supports(MovementGrammar.Verb.SWIM)).is_false()
	assert_bool(controller.supports(MovementGrammar.Verb.DIVE)).is_false()


func test_req_001_the_two_grammars_are_mechanically_distinct() -> void:
	# Pillar 2: if the verb sets overlapped, "two grammars" would be decoration.
	for verb: MovementGrammar.Verb in MovementGrammar.WATER_VERBS:
		assert_bool(MovementGrammar.LAND_VERBS.has(verb)).override_failure_message(
			"REQ-001: '%s' appears in both grammars" % MovementGrammar.verb_id(verb)
		).is_false()


func test_req_001_land_grammar_ignores_vertical_steering() -> void:
	var controller := _controller()
	controller.physics_step(0.016, false, _intent(Vector3(0.0, 1.0, 0.0)))
	# Pure vertical intent on land is not steering, so it produces no motion.
	assert_float(controller.get_velocity().length()).is_equal_approx(0.0, 0.0001)


func test_req_001_water_grammar_supports_full_3d_directional_movement() -> void:
	var controller := _controller()
	controller.physics_step(0.016, true, _intent(Vector3(0.0, 1.0, 0.0)))
	assert_bool(controller.get_velocity().length() > 0.0).override_failure_message(
		"REQ-001 AC-2: water movement is full 3D; vertical intent must move the axolotl"
	).is_true()


## Full speed on every axis, HELD RATHER THAN INSTANT on the vertical one.
##
## This used to take a single step and demand the tuned speed on all four
## directions, and the vertical two now take about a third of a second to
## arrive: the water grammar eases into a climb or a descent instead of
## snapping to it, because a body that goes from level to five metres a second
## downward between two rendered frames has not dived, it has cut. Horizontal
## steering now accelerates as well; full speed is checked after settling.
##
## What the criterion actually says is that water movement is full 3D at the
## tuned speed. It still is, on every axis; the vertical two are simply
## asserted after the glide has had time to run rather than before.
func test_req_001_swimming_moves_at_the_tuned_speed_in_any_of_three_axes() -> void:
	var tuning := _tuning()
	var speed := tuning.get_number("controller.swim.base_speed_m_per_s")

	for direction: Vector3 in [Vector3.RIGHT, Vector3.UP, Vector3.FORWARD,
			Vector3(1.0, 1.0, 1.0)]:
		var controller := AxolotlController.new(tuning)
		# Two seconds of held steering: far longer than the glide needs, and
		# it must SETTLE at the tuned speed rather than pass through it.
		for _step: int in range(120):
			controller.physics_step(0.016, true, _intent(direction))
		assert_float(controller.get_velocity().length()).override_failure_message(
			"REQ-001 AC-2: full 3D steering must reach tuned swim speed on %s"
			% str(direction)
		).is_equal_approx(speed, 0.0001)


func test_req_001_horizontal_and_vertical_steering_begin_without_snapping() -> void:
	# The two halves of the same decision, held apart so neither can quietly
	# become the other: a glide applied to the whole vector would make the
	# swim mushy, and no glide at all is what made a dive read as a cut.
	var tuning := _tuning()
	var speed := tuning.get_number("controller.swim.base_speed_m_per_s")
	var controller := AxolotlController.new(tuning)

	controller.physics_step(0.016, true, _intent(Vector3.RIGHT))
	assert_bool(controller.get_velocity().x > 0.0 and controller.get_velocity().x < speed).override_failure_message(
		"horizontal steering begins immediately and accelerates toward full speed"
	).is_true()

	controller.set_velocity(Vector3.ZERO)
	controller.physics_step(0.016, true, _intent(Vector3.UP))
	assert_bool(controller.get_velocity().y > 0.0
		and controller.get_velocity().y < speed).override_failure_message(
		"a rise must BEGIN on the first frame and not be finished by it "
		+ "(y %.3f, tuned speed %.3f)" % [controller.get_velocity().y, speed]
	).is_true()


# --- AC-2: dive ------------------------------------------------------------

func test_req_001_dive_descends_at_the_tuned_speed_from_a_standstill() -> void:
	var tuning := _tuning()
	var dive_speed := tuning.get_number("controller.dive.speed_m_per_s")
	var controller := AxolotlController.new(tuning)

	# HELD, and settling. The dive used to SET velocity.y outright and arrive
	# in one frame; it now eases into the tuned speed, which is what gives the
	# descent a shape the player can see beginning. What the criterion asks —
	# that a dive descends at the tuned speed with no steering at all — is
	# unchanged, and is asserted where the glide has finished.
	for _step: int in range(60):
		controller.physics_step(0.016, true, _intent(Vector3.ZERO,
			[MovementGrammar.Verb.DIVE], [MovementGrammar.Verb.DIVE]))

	assert_float(controller.get_velocity().y).override_failure_message(
		"REQ-001 AC-2: a dive is a deliberate descent, so it must work with no steering"
	).is_equal_approx(-dive_speed, 0.0001)


func test_req_001_a_dive_eases_downward_instead_of_snapping_to_speed() -> void:
	# The glide itself, and the reason the case above had to change. A single
	# frame of dive must have STARTED the descent without completing it: the
	# frame that used to take the axolotl from level flight to full dive speed
	# was not a movement, it was a cut, and it is what a pitched body has to
	# have something to tip into.
	var tuning := _tuning()
	var dive_speed := tuning.get_number("controller.dive.speed_m_per_s")
	var controller := AxolotlController.new(tuning)

	controller.physics_step(0.016, true, _intent(Vector3.ZERO,
		[MovementGrammar.Verb.DIVE]))
	var first := controller.get_velocity().y

	assert_bool(first < 0.0 and first > -dive_speed).override_failure_message(
		"one frame of dive must begin the descent without finishing it "
		+ "(y %.3f, tuned speed %.3f)" % [first, dive_speed]).is_true()

	# And the descent DEEPENS while the key is held, rather than stalling at
	# whatever the first frame reached.
	controller.physics_step(0.016, true, _intent(Vector3.ZERO,
		[], [MovementGrammar.Verb.DIVE]))
	assert_bool(controller.get_velocity().y < first).override_failure_message(
		"a held dive must keep accelerating downward").is_true()


func test_req_001_the_model_pitches_into_a_dive_and_levels_off() -> void:
	# The visual half, and the reason the glide exists at all: an axolotl
	# sinking at five metres a second while held perfectly level is being
	# lowered, not diving. Negative is nose-down.
	var tuning := _tuning()
	var controller := AxolotlController.new(tuning)
	assert_float(controller.get_pitch()).is_equal_approx(0.0, 0.0001)

	for _step: int in range(60):
		controller.physics_step(0.016, true, _intent(Vector3.ZERO,
			[MovementGrammar.Verb.DIVE], [MovementGrammar.Verb.DIVE]))
	var diving := controller.get_pitch()
	assert_bool(diving < 0.0).override_failure_message(
		"a diving axolotl must nose DOWN (pitch %.3f rad)" % diving).is_true()
	assert_float(rad_to_deg(diving)).is_equal_approx(
		-tuning.get_number("controller.pitch.max_deg"), 0.5)

	# Rising noses up, which is the same rule with the sign flipped rather
	# than a second behaviour.
	for _step: int in range(60):
