class_name AudioSettings
extends RefCounted

## Master, music and effects volumes — independently adjustable and persisted
## across sessions (REQ-023 AC-6).
##
## Persistence goes through the Save Integration Interface's settings path,
## alongside input bindings, NOT a private file of this node's own. The Save
## System supplies the concrete store; this node declares only the port it needs,
## so Audio can be built and tested before Save exists.

const SETTINGS_SECTION := "audio"
const DEFAULT_VOLUME := 0.8

var _volumes: Dictionary = {}


func _init() -> void:
	for bus: String in AudioEvent.BUSES:
		_volumes[bus] = DEFAULT_VOLUME


## Volumes are linear 0.0–1.0; the sink converts to dB. Out-of-range input is
## clamped rather than rejected — a settings slider cannot produce a meaningful
## error, and refusing to load a profile over a bad volume would be worse than
## clamping it.
func set_volume(bus: String, linear: float) -> void:
	if not AudioEvent.BUSES.has(bus):
		push_error("[audio.unknown_bus] %s: not one of Master/Music/Effects" % bus)
		return
	_volumes[bus] = clampf(linear, 0.0, 1.0)


func get_volume(bus: String) -> float:
	return float(_volumes.get(bus, DEFAULT_VOLUME))


## The payload handed to the settings store. Flat and primitive so the save
## format stays readable and versionable.
func to_dictionary() -> Dictionary:
	return _volumes.duplicate()


func from_dictionary(stored: Dictionary) -> void:
	for bus: String in AudioEvent.BUSES:
		if stored.has(bus):
			set_volume(bus, float(stored[bus]))

extends SceneTree
var passed:=0
var failed:=0
func check(ok: bool, label: String) -> void:
	if ok:passed+=1
	else:failed+=1;push_error("FAIL: "+label)
func _initialize() -> void:run.call_deferred()
func run() -> void:
	var world:=load("res://worlds/coral_cove/world.tscn").instantiate() as Node3D;root.add_child(world)
	await physics_frame;await physics_frame
	var motions: Array[Node3D]=[]
	for node: Node in world.find_children("*","Node3D",true,false):
		if node.get_script()!=null and node.get_script().resource_path=="res://core/rendering/crayfish_motion.gd":motions.append(node as Node3D);node.set_physics_process(false)
	check(motions.size()==14,"all thirteen pickups plus the grotto creature use the new model")
	var records: Dictionary={}
	var shore:=0;var water:=0
	for motion: Node3D in motions:
		motion.call("_physics_process",.1)
		var actor:=motion.get_parent() as Node3D
		var skeleton:=motion.find_children("*","Skeleton3D",true,false)[0] as Skeleton3D
		check(skeleton.get_bone_count()==23,"complete rig: "+String(actor.name))
		var swimming: bool=motion.call("is_swimming")
		if swimming:water+=1
		else:shore+=1
		records[motion]={"last":actor.global_position,"distance":0.,"radius":0.,"valid":true,"sync":true,"turn":0.,"previous_heading":float(motion.get("_heading"))}
	# Simulate 45 seconds of local behaviour against the real production collision world.
	for step: int in 450:
		for motion: Node3D in motions:
			motion.call("_physics_process",.1)
			var actor:=motion.get_parent() as Node3D;var data: Dictionary=records[motion]
			data["distance"]=float(data["distance"])+actor.global_position.distance_to(data["last"])
			var offset: Vector3=actor.global_position-(motion.call("home_position") as Vector3)
			data["radius"]=maxf(float(data["radius"]),Vector2(offset.x,offset.z).length())
			data["sync"]=bool(data["sync"]) and motion.global_position.distance_to(actor.global_position)<.001
			if motion.call("is_swimming"):
				data["valid"]=bool(data["valid"]) and motion.call("_water_at",actor.global_position)!=null and absf(offset.y)<=.27
			else:
				var ground: Dictionary=motion.call("_ground_at",actor.global_position)
				data["valid"]=bool(data["valid"]) and not ground.is_empty() and absf((ground.get("position",actor.global_position) as Vector3).y-actor.global_position.y)<.04
			data["last"]=actor.global_position
		if step%30==0:await process_frame
	for motion: Node3D in motions:
		var data: Dictionary=records[motion];var name:=String(motion.get_parent().name)
		print("HABITAT ",name," water ",motion.call("is_swimming")," distance ",snappedf(float(data["distance"]),.01)," radius ",snappedf(float(data["radius"]),.01)," valid ",data["valid"])
		check(float(data["distance"])>.5,"natural roaming is active: "+name)
		check(float(data["radius"])<=1.151,"roaming stays near collectible route: "+name)
		check(bool(data["valid"]),"stays in its environment: "+name)
		check(bool(data["sync"]),"pickup trigger follows creature: "+name)
	check(shore==4,"four shore habitats");check(water==10,"ten underwater habitats including grotto")
	var mesh:=motions[0].find_children("*","MeshInstance3D",true,false)[0] as MeshInstance3D
	check(mesh.mesh.get_surface_count()==3,"three material surfaces in one skinned mesh")
	var triangles:=0
	for surface: int in mesh.mesh.get_surface_count():triangles+=mesh.mesh.surface_get_arrays(surface)[Mesh.ARRAY_INDEX].size()/3
	check(triangles>6000 and triangles<10000,"detail remains within an economical mesh budget")
	var shader_found:=false
	for i: int in mesh.mesh.get_surface_count():
		if mesh.mesh.surface_get_material(i) is ShaderMaterial:shader_found=true
	check(shader_found,"detailed shell shader imported")
	# Sweep against a deliberately thin barrier: endpoints alone would miss it.
	var wall:=StaticBody3D.new();var shape:=CollisionShape3D.new();var box:=BoxShape3D.new();box.size=Vector3(.08,2,2);shape.shape=box;wall.add_child(shape);wall.position=Vector3(100,0,0);root.add_child(wall)
	await physics_frame;await physics_frame
	check(not motions[0].call("_clear_path",Vector3(99,.2,0),Vector3(101,.2,0)),"thin walls cannot be crossed between targets")
	var hero:=CharacterBody3D.new();hero.add_to_group("player");root.add_child(hero);hero.position=(motions[0].get_parent() as Node3D).global_position
	motions[0].set("_moving",true);motions[0].call("_physics_process",.1)
	check(not bool(motions[0].get("_moving")),"nearby player can collect without endless fleeing")
	hero.queue_free();wall.queue_free();world.queue_free();await process_frame
	print("CRAYFISH HABITAT: %d passed, %d failed"%[passed,failed]);quit(1 if failed else 0)

extends GdUnitTestSuite

## Visual shells over greybox collision proxies (REQ-030, REQ-034).
##
## A shell is ART wrapped around a collision proxy that never moves. Two
## properties make that safe, and they are the whole reason this suite exists,
## because both fail SILENTLY — the render looks fine and the player falls
## through something, or lands on nothing:
##
##   1. THE CAP IS AT THE PROXY'S TOP PLANE. Not above it (the player would
##      sink into visible ground before stopping) and not below it (they would
##      stop in mid-air above visible ground).
##   2. THE RIM ONLY EVER GOES OUTWARD. Every point of collision has to be
##      under visible geometry. A rim pulled inside the footprint shows floor
##      the player falls through at the edge — the exact place a platformer
##      player spends their time.

const HUB := "res://hub/open_lagoon.tscn"


func _tree_root() -> Node:
	return (Engine.get_main_loop() as SceneTree).root


## A shell over a proxy of the given size, built and ready to interrogate.
func _shell(size: Vector3, offset := Vector3.ZERO) -> TerrainShell:
	var body := StaticBody3D.new()
	var collider := CollisionShape3D.new()
	var box := BoxShape3D.new()
	box.size = size
	collider.shape = box
	collider.position = offset
	body.add_child(collider)
	_tree_root().add_child(body)

	var shell := TerrainShell.new()
	body.add_child(shell)
	# Explicit: add_child from SceneTree._initialize defers _ready, so the
	# build has to be asked for rather than assumed.
	shell._rebuild()
	return shell


func _drop(shell: TerrainShell) -> void:
	var body := shell.get_parent()
	_tree_root().remove_child(body)
	body.free()


func _shell_vertices(shell: TerrainShell) -> PackedVector3Array:
	var visual := shell.get_visual() as MeshInstance3D
	if visual == null or visual.mesh == null:
		return PackedVector3Array()
	return visual.mesh.surface_get_arrays(0)[Mesh.ARRAY_VERTEX]


func test_req_030_the_walkable_cap_sits_exactly_on_the_proxys_top() -> void:
	# Displacing the surface a player lands on makes every landing a lie: the
	# foot stops somewhere the eye did not predict. The cap is flat, at the
	# proxy's own top plane, and that is not negotiable.
	for size: Vector3 in [Vector3(48, 2, 32), Vector3(4, 2, 4),
			Vector3(2.4, 6, 18)]:
		var shell := _shell(size)
		var bounds := shell.proxy_bounds()
		var top := bounds.position.y + bounds.size.y

		var cap_points := 0
		for vertex: Vector3 in _shell_vertices(shell):
			# Cap vertices are the ones at the top plane; the skirt hangs well
			# below it. Anything ABOVE the plane is the failure being hunted.
			assert_bool(vertex.y <= top + 0.001).override_failure_message(
				("a shell vertex sits %.3f ABOVE the proxy top on a %s proxy: "
				+ "the player would sink into visible ground before stopping")
				% [vertex.y - top, str(size)]).is_true()
			if absf(vertex.y - top) < 0.001:
				cap_points += 1
		assert_int(cap_points).override_failure_message(
			"a %s proxy produced no vertices at its top plane, so there is "
			% str(size) + "nothing to stand on visually").is_greater(3)
		_drop(shell)


func test_req_030_the_rim_never_pulls_inside_the_footprint() -> void:
	# The other half. Collision reaches the proxy's corner, so visible geometry
	# must too — a rim inside the footprint shows the player floor they fall
	# through, right at the edge where they spend their time.
	for size: Vector3 in [Vector3(48, 2, 32), Vector3(3, 2, 9)]:
		var shell := _shell(size)
		var bounds := shell.proxy_bounds()
		var top := bounds.position.y + bounds.size.y
		var half := Vector2(bounds.size.x * 0.5, bounds.size.z * 0.5)

		for vertex: Vector3 in _shell_vertices(shell):
			if absf(vertex.y - top) > 0.001:
				continue  # skirt: allowed to pull in, it is below the surface
			var out := Vector2(absf(vertex.x - bounds.get_center().x),
				absf(vertex.z - bounds.get_center().z))
			# The fan's hub sits at the centre of the cap by construction and
			# is the one top-plane vertex that is legitimately inside. It is
			# not a rim point, and it is what the surface fans out FROM.
			if out.x < 0.001 and out.y < 0.001:
				continue
			# On a rectangle, a rim point is outside the footprint when it
			# clears the half-extent on the axis it lies along. Being clear on
			# EITHER axis is enough; the corner cases clear both.
			assert_bool(out.x >= half.x - 0.001 or out.y >= half.y - 0.001
				).override_failure_message(
				("a %s proxy has a cap vertex at (%.2f, %.2f) inside its "
				+ "half-extents (%.2f, %.2f): collision reaches further than "
				+ "the art, so the player falls through a visible edge")
				% [str(size), out.x, out.y, half.x, half.y]).is_true()
		_drop(shell)


func test_req_030_a_shell_never_adds_collision() -> void:
	# A shell that could collide would be gameplay geometry wearing an art
	# costume, and the proxy would no longer be the authority on where the
	# player can stand.
	var shell := _shell(Vector3(6, 2, 6))
	assert_int(shell.find_children("*", "CollisionObject3D", true, false).size()
		).override_failure_message(
		"a visual shell must contain no collision of any kind").is_equal(0)
	assert_int(shell.find_children("*", "CollisionShape3D", true, false).size()
		).is_equal(0)
	_drop(shell)


func test_req_030_a_shell_follows_a_collider_that_is_not_centred() -> void:
	# Colliders are not always at their body's origin. A shell that assumed
	# they were would drift off its own platform, and the drift would be
	# invisible in any scene where the offset happened to be zero.
	var offset := Vector3(3.0, 0.0, -2.0)
	var shell := _shell(Vector3(4, 2, 4), offset)
	var bounds := shell.proxy_bounds()
	assert_bool(bounds.get_center().is_equal_approx(offset)
		).override_failure_message(
		"the shell read a centre of %s for a collider offset to %s"
		% [str(bounds.get_center()), str(offset)]).is_true()
	_drop(shell)


func test_req_030_the_kit_slot_replaces_the_generated_shell() -> void:
	# THE MESHY INTERFACE. Dropping a replacement kit in must not require
	# touching level logic — so the slot has to actually take over, and the
	# generated geometry has to step aside.
	var shell := _shell(Vector3(6, 2, 6))
	var generated := _shell_vertices(shell).size()
	assert_int(generated).is_greater(0)

	shell.visual_kit = load(
		"res://assets/environment/river_boulder/river_boulder.glb")
	shell._rebuild()

	var visual := shell.get_visual()
	assert_object(visual).override_failure_message(
		"setting visual_kit must produce a visual").is_not_null()
	assert_bool(visual.find_children("*", "MeshInstance3D", true, false).size() > 0
		).override_failure_message(
		"the kit's own meshes must be what renders").is_true()
	# The kit is fitted to the proxy rather than dropped in at its own scale.
	assert_bool(visual.scale != Vector3.ONE).override_failure_message(
		"a kit must be scaled onto the proxy's bounds, not used raw"
	).is_true()
	_drop(shell)


func test_req_030_shells_are_deterministic() -> void:
	# Two shells with the same seed and bounds must be the same rock. A level
	# whose silhouettes reshuffle between launches is not a place.
	var first := _shell(Vector3(8, 2, 5))
	first.shell_seed = 4242
	first._rebuild()
	var second := _shell(Vector3(8, 2, 5))
	second.shell_seed = 4242
	second._rebuild()
	assert_bool(_shell_vertices(first) == _shell_vertices(second)
		).override_failure_message(
		"the same seed and bounds must generate the same shell").is_true()

	second.shell_seed = 99
	second._rebuild()
	assert_bool(_shell_vertices(first) != _shell_vertices(second)
		).override_failure_message(
		"a different seed must give a different silhouette, or every platform "
		+ "in a level is the same rock").is_true()
	_drop(first)
	_drop(second)


func test_req_030_the_hub_ground_is_shelled_and_its_proxy_is_hidden() -> void:
	# The vertical slice: no raw BoxMesh may be visible in the hub.
	var scene := (load(HUB) as PackedScene).instantiate()
	var shells := 0
	for node: Node in scene.find_children("*", "Node3D", true, false):
		if node is TerrainShell:
			shells += 1
	assert_int(shells).override_failure_message(
		"Open Lagoon must dress its collision proxies with shells"
	).is_greater_equal(1)

	for node: Node in scene.find_children("*", "MeshInstance3D", true, false):
		var mesh := (node as MeshInstance3D).mesh
		if mesh is BoxMesh and (node as MeshInstance3D).visible:
			assert_bool(false).override_failure_message(
				("%s is a VISIBLE raw BoxMesh: a collision proxy is greybox, "
				+ "not final art") % node.name).is_true()
	scene.free()

class_name AudioBank
extends RefCounted

## Resolves an [AudioEvent] to the audio resource that should play (REQ-023).
##
## A world may declare its own music and ambience through the Level Contract; a
## world declaring none falls back to defaults rather than to silence (AC-5).
## Resolution happens ONCE at world load — [method resolve] holds the resolved
## set — so the fallback path is taken at load rather than re-tested on every
## playback.
##
## The bank is total by construction: [method resolve] refuses a default set that
## does not cover every declared cue and bed, because a gap would surface at
## runtime as silence instead of as a failure.

var _cues: Dictionary = {}
var _beds: Dictionary = {}
var _world_overridden: PackedStringArray = []
var _errors: Array[TuningError] = []


## Builds the resolved bank. [param defaults] must cover every cue and bed;
## [param world_declared] may override any subset and may be empty.
##
## Returns null and populates [param out_errors] when the defaults are
## incomplete — a world is allowed to declare nothing, but the project is never
## allowed to ship an incomplete default set.
static func resolve(
	defaults: Dictionary,
	world_declared: Dictionary,
	out_errors: Array[TuningError] = []
) -> AudioBank:
	var bank := AudioBank.new()

	for cue: AudioEvent.Cue in AudioEvent.all_cues():
		var id := AudioEvent.cue_id(cue)
		if not defaults.has(id) or String(defaults[id]).is_empty():
			out_errors.append(TuningError.new(
				"audio.default_missing", id,
				"default audio bank has no entry for cue '%s'" % id))
			continue
		bank._cues[cue] = String(defaults[id])

	for bed: AudioEvent.Bed in AudioEvent.all_beds():
		var id := AudioEvent.bed_id(bed)
		if not defaults.has(id) or String(defaults[id]).is_empty():
			out_errors.append(TuningError.new(
				"audio.default_missing", id,
				"default audio bank has no entry for bed '%s'" % id))
			continue
		bank._beds[bed] = String(defaults[id])

	if not out_errors.is_empty():
		return null

	# A world declaring nothing is legal and common — the reference template
	# declares no optional elements at all, and it must still be audible.
	for key: Variant in world_declared:
		var id := String(key)
		var path := String(world_declared[key])
		if path.is_empty():
			out_errors.append(TuningError.new(
				"audio.world_entry_empty", id,
				"world declared an empty audio path; omit the key to take the default"))
			continue

		var matched := false
		for cue: AudioEvent.Cue in AudioEvent.all_cues():
			if AudioEvent.cue_id(cue) == id:
				bank._cues[cue] = path
				matched = true
				break
		if not matched:
			for bed: AudioEvent.Bed in AudioEvent.all_beds():
				if AudioEvent.bed_id(bed) == id:
					bank._beds[bed] = path
					matched = true
					break

		if not matched:
			out_errors.append(TuningError.new(
				"audio.unknown_event", id,
				"world declared audio for an event that does not exist"))
			continue

		bank._world_overridden.append(id)

	if not out_errors.is_empty():
		return null
	return bank


func cue_path(cue: AudioEvent.Cue) -> String:
	return String(_cues.get(cue, ""))


func bed_path(bed: AudioEvent.Bed) -> String:
	return String(_beds.get(bed, ""))


## True when this entry came from the world rather than the defaults. Used by
## tests to prove the fallback actually fell back.
func is_world_supplied(id: String) -> bool:
	return _world_overridden.has(id)


func get_world_supplied_ids() -> PackedStringArray:
	return _world_overridden.duplicate()


## Every cue resolves to a non-empty path — the property that makes "falls back
## to defaults rather than silence" checkable.
func is_total() -> bool:
	for cue: AudioEvent.Cue in AudioEvent.all_cues():
		if cue_path(cue).is_empty():
			return false
	for bed: AudioEvent.Bed in AudioEvent.all_beds():
		if bed_path(bed).is_empty():
			return false
	return true

extends GdUnitTestSuite

## The hero's animation set (REQ-035): the rig's clips, chosen from the state
## the controller already knows.
##
## The state table is a pure function, so most of this needs no scene at all.
## The binding half is proven against the SHIPPED model, because a rig that
## exports clips the client never finds is the failure worth catching.

const SCENE_PATH := "res://core/controller/axolotl_body.tscn"


func test_the_state_table_maps_every_movement_state_to_its_clip() -> void:
	# Water wins over everything: the swim cycle is the water grammar.
	assert_str(HeroAnimator.choose_clip(true, false, 0.0, 0.0)
		).is_equal(HeroAnimator.SWIM)
	assert_str(HeroAnimator.choose_clip(true, true, 5.0, 4.0)
		).override_failure_message(
		"a swimmer brushing the seabed is still swimming"
		).is_equal(HeroAnimator.SWIM)

	# Airborne splits on which way the axolotl is going.
	assert_str(HeroAnimator.choose_clip(false, false, 4.0, 0.0)
		).is_equal(HeroAnimator.HOP)
	assert_str(HeroAnimator.choose_clip(false, false, -4.0, 0.0)
		).is_equal(HeroAnimator.FALL)
	assert_str(HeroAnimator.choose_clip(false, false, 0.0, 0.0)
		).override_failure_message(
		"at the apex the arc is falling, not hovering"
		).is_equal(HeroAnimator.FALL)

	# Grounded splits on whether it is going anywhere.
	assert_str(HeroAnimator.choose_clip(false, true, 0.0, 2.5)
		).is_equal(HeroAnimator.WADDLE)
	assert_str(HeroAnimator.choose_clip(false, true, 0.0, 0.0)
		).is_equal(HeroAnimator.IDLE)
	assert_str(HeroAnimator.choose_clip(false, true, 0.0, 0.05)
		).override_failure_message(
		"a hair of residual drift is standing still, not walking"
		).is_equal(HeroAnimator.IDLE)


func test_an_unbound_animator_is_inert_rather_than_broken() -> void:
	# The walk probes build bare bodies with no model at all; that must be
	# quiet, not a crash.
	var animator := HeroAnimator.new()
	assert_bool(animator.bind(null)).is_false()
	assert_bool(animator.is_bound()).is_false()
	animator.step(1.0 / 60.0, false, true, Vector3.ZERO)
	animator.play_hurt()
	assert_str(animator.get_current_clip()).is_empty()


func test_the_shipped_hero_binds_every_clip_the_animator_plays() -> void:
	var body := (load(SCENE_PATH) as PackedScene).instantiate()
	var model := body.get_node("Model") as Node3D

	var animator := HeroAnimator.new()
	assert_bool(animator.bind(model)).override_failure_message(
		"the shipped hero must carry an AnimationPlayer").is_true()

	var players := model.find_children("*", "AnimationPlayer", true, false)
	var player := players[0] as AnimationPlayer
	for clip: String in [HeroAnimator.IDLE, HeroAnimator.WADDLE,
			HeroAnimator.SWIM, HeroAnimator.HOP, HeroAnimator.FALL,
			HeroAnimator.HURT]:
		assert_bool(player.has_animation(clip)).override_failure_message(
			"the rig is missing the %s clip the animator plays" % clip
			).is_true()

	# The ongoing states must loop: glTF import leaves every clip one-shot,
	# so an idle that does not loop freezes the axolotl after four seconds.
	for clip: String in HeroAnimator.LOOPING:
		assert_int(player.get_animation(clip).loop_mode
			).override_failure_message("%s must loop" % clip
			).is_equal(Animation.LOOP_LINEAR)

	body.free()


func test_the_shipped_hero_is_skinned_to_a_skeleton() -> void:
	# Clips that drive a skeleton nothing is bound to move nothing at all.
	var body := (load(SCENE_PATH) as PackedScene).instantiate()
	var model := body.get_node("Model") as Node3D

	var skeletons := model.find_children("*", "Skeleton3D", true, false)
	assert_int(skeletons.size()).override_failure_message(
		"the hero must import a Skeleton3D").is_equal(1)
	var skeleton := skeletons[0] as Skeleton3D
	assert_int(skeleton.get_bone_count()).override_failure_message(
		"the documented rig is twelve bones: root, spine, head, two gills, "
		+ "four legs, three tail segments").is_equal(12)
	for bone: String in ["root", "spine", "head", "tail_1"]:
		assert_int(skeleton.find_bone(bone)).override_failure_message(
			"the rig must carry the %s bone the clips key" % bone
			).is_greater_equal(0)

	var meshes := model.find_children("*", "MeshInstance3D", true, false)
	assert_int(meshes.size()).is_greater_equal(1)
	for node: Node in meshes:
		assert_object((node as MeshInstance3D).skin).override_failure_message(
			"%s is not skinned; the rig would pose nothing" % node.name
			).is_not_null()

	body.free()


func test_every_vertex_of_the_hero_is_driven_by_the_rig() -> void:
	"""What replaced the eye-and-gleam rigid-binding test.

	That test defended a real bug: the eye sits centimetres from where the
	gill bones start, so the old rigger's nearest-two rule handed it 77% to
	the fronds and the highlight a different 70%, and the glint slid off the
	pupil whenever the gills swung. It defended it by name — it looked for
	meshes called `axolotl_eye` and `axolotl_gleam` — and the shipped hero is
	one surface with a painted face, so there is nothing left to look up.

	What replaced it guards the failure mode the CURRENT pipeline actually
	has. Bone-heat weighting leaves gaps: on this hero the gill filament tips
	came back with no weight at all, and an unweighted vertex stays in rest
	pose while the surface around it moves, which spikes the mesh. It is not
	hypothetical — it also killed the glTF exporter outright, which is how it
	was found. tools/blender/rig_model.py adopts orphans by nearest bone; this
	is what proves it kept doing so.
	"""
	var body := (load(SCENE_PATH) as PackedScene).instantiate()
	var model := body.get_node("Model") as Node3D

	var checked := 0
	var orphans := 0
	for node: Node in model.find_children("*", "MeshInstance3D", true, false):
		var mesh_instance := node as MeshInstance3D
		if mesh_instance.skin == null or mesh_instance.mesh == null:
			continue
		for surface: int in mesh_instance.mesh.get_surface_count():
			var arrays: Array = mesh_instance.mesh.surface_get_arrays(surface)
			var weights: PackedFloat32Array = arrays[Mesh.ARRAY_WEIGHTS]
			if weights.is_empty():
				continue
			# Four weights per vertex is glTF's fixed stride.
			var per_vertex := 4
			for vertex: int in weights.size() / per_vertex:
				checked += 1
				var total := 0.0
				for slot: int in per_vertex:
					total += weights[vertex * per_vertex + slot]
				if total <= 0.0001:
					orphans += 1

	assert_int(checked).override_failure_message(
		"no skinned vertices were found in the hero, so this proves nothing"
		).is_greater(0)
	assert_int(orphans).override_failure_message(
		("%d of %d hero vertices carry no bone weight at all. They will hang "
		+ "in rest pose while the surface around them moves, and Blender's "
		+ "glTF exporter refuses to write them.") % [orphans, checked]
		).is_equal(0)

	body.free()


func test_the_hurt_flinch_overrides_locomotion_until_it_finishes() -> void:
	var body := (load(SCENE_PATH) as PackedScene).instantiate()
	var model := body.get_node("Model") as Node3D
	var animator := HeroAnimator.new()
	animator.bind(model)

	animator.step(1.0 / 60.0, false, true, Vector3.ZERO)
	assert_str(animator.get_current_clip()).is_equal(HeroAnimator.IDLE)

	animator.play_hurt()
	assert_str(animator.get_current_clip()).is_equal(HeroAnimator.HURT)

	# Even a state change mid-flinch must not cut the flinch short.
	animator.step(1.0 / 60.0, false, true, Vector3(3.0, 0.0, 0.0))
	assert_str(animator.get_current_clip()).override_failure_message(
		"a flinch the player cannot see is not feedback"
		).is_equal(HeroAnimator.HURT)

	# Once its length has elapsed, locomotion resumes.
	animator.step(2.0, false, true, Vector3(3.0, 0.0, 0.0))
	animator.step(1.0 / 60.0, false, true, Vector3(3.0, 0.0, 0.0))
	assert_str(animator.get_current_clip()).is_equal(HeroAnimator.WADDLE)

	body.free()

extends SceneTree
func _initialize() -> void:
	var scene := load("res://worlds/coral_cove/world.tscn").instantiate() as Node3D
	var profile := preload("res://core/controller/channel_profile.gd").new()
	profile.source_path="res://worlds/coral_cove/channel_profile.json"
	var maximum := 0.0
	var point := Vector3.ZERO
	for volume: WaterVolume in scene.find_children("*","WaterVolume",true,false):
		for visual: MeshInstance3D in volume.find_children("*","MeshInstance3D",true,false):
			if not visual.mesh is ArrayMesh:
				continue
			var arrays := visual.mesh.surface_get_arrays(0)
			var verts: PackedVector3Array=arrays[Mesh.ARRAY_VERTEX]
			var ids: PackedInt32Array=arrays[Mesh.ARRAY_INDEX]
			for i in range(0,ids.size(),3):
				var center := volume.transform*visual.transform*((verts[ids[i]]+verts[ids[i+1]]+verts[ids[i+2]])/3.0)
				var deviation := absf(center.y-float(profile.sample(center)["surface"]))
				if deviation>maximum:
					maximum=deviation
					point=center
	print("MAX WATER MESH DEVIATION ",maximum," at ",point)
	scene.free()
	quit()

extends GdUnitTestSuite

## The test harness checking itself — REQ-026.
##
## This exists because the same bug bit twice. The assertion shim implements a
## subset of GdUnit4's API; when a suite calls a method the shim lacks, GDScript
## resolves it at RUNTIME (override_failure_message returns Variant), raises a
## script error, ABORTS the test function on the spot, and the runner sees an
## empty failure list and prints PASS. A test that never ran reports success,
## which is worse than having no test.
##
## Two guards already exist and neither is sufficient alone:
##
##   * The runner fails any test that evaluated ZERO assertions. That catches an
##     abort before the first assertion, but not one after — and a suite whose
##     helper asserts first (a tuning loader that checks for load errors, say)
##     has already scored one by the time the bad call lands. That is exactly how
##     the second occurrence slipped through.
##   * Running the suite and grepping the log for SCRIPT ERROR catches everything,
##     but only if someone looks.
##
## So this test closes the hole at the source: it reads every suite's code,
## extracts the assertion methods actually called on each assert_* entry point,
## and asserts the shim implements them. A missing method now fails as a normal
## red test naming the gap, before it can silently swallow a suite.
##
## TO REMOVE with the shim: once addons/gdUnit4 is vendored, the real library
## defines these and this file goes with gdunit_compat.gd.

const TEST_ROOT := "res://test"

## The chain shapes the suites actually use. A terminal assertion returns void,
## so a chain is at most `entry(...).method(...)` or
## `entry(...).override_failure_message(...).method(...)`.
const CHAIN_LIMIT := 2
const MESSAGE_HOOK := "override_failure_message"


func _entry_probes() -> Dictionary:
	# One live instance per entry point, so membership is checked by reflection
	# against the real class rather than against a list that could drift.
	# Constructing an assert object records nothing; only _check does.
	return {
		"assert_str": assert_str(""),
		"assert_int": assert_int(0),
		"assert_bool": assert_bool(true),
		"assert_float": assert_float(0.0),
		"assert_array": assert_array([]),
		"assert_dict": assert_dict({}),
		"assert_object": assert_object(null),
	}


func _suite_paths(root: String) -> PackedStringArray:
	var found := PackedStringArray()
	var dir := DirAccess.open(root)
	if dir == null:
		return found

	dir.list_dir_begin()
	var entry := dir.get_next()
	while entry != "":
		var path := root.path_join(entry)
		if dir.current_is_dir():
			if entry != "support":
				found.append_array(_suite_paths(path))
		elif entry.begins_with("test_") and entry.ends_with(".gd"):
			found.append(path)
		entry = dir.get_next()
	dir.list_dir_end()
	return found


## Source with line breaks collapsed, so a chain wrapped across lines reads as
## one statement.
func _flattened(path: String) -> String:
	var handle := FileAccess.open(path, FileAccess.READ)
	var text := handle.get_as_text()
	handle.close()

	var out := ""
	for line: String in text.split("\n"):
		out += line.strip_edges() + " "
	return out


## Index just past the ')' matching the '(' at [param open_at]; -1 when the
## parens do not balance, in which case the caller skips this occurrence rather
## than inventing a method name from the wreckage.
func _match_paren(text: String, open_at: int) -> int:
	var depth := 0
	var index := open_at
	while index < text.length():
		var character := text[index]
		if character == "(":
			depth += 1
		elif character == ")":
			depth -= 1
			if depth == 0:
				return index + 1
		index += 1
	return -1


## The method name of a chained call starting at [param from], and where it ends.
## Returns an empty name when the next thing is not a chained call.
func _next_call(text: String, from: int) -> Dictionary:
	var index := from
	while index < text.length() and text[index] == " ":
		index += 1
	if index >= text.length() or text[index] != ".":
		return {"name": "", "end": from}

	var name_start := index + 1
	var cursor := name_start
	while cursor < text.length() and (text[cursor].is_valid_identifier()
			or text[cursor] == "_" or text[cursor].is_valid_int()):
		cursor += 1
	if cursor >= text.length() or text[cursor] != "(":
		return {"name": "", "end": from}

	var closed := _match_paren(text, cursor)
	if closed < 0:
		return {"name": "", "end": -1}
	return {"name": text.substr(name_start, cursor - name_start), "end": closed}


## Every (entry point, method) pair the suites actually call.
func _collect_calls() -> Dictionary:
	var calls: Dictionary = {}
	for entry_name: String in _entry_probes():
		calls[entry_name] = PackedStringArray()

	for path: String in _suite_paths(TEST_ROOT):
		var text := _flattened(path)
		for entry_name: String in calls:
			var search := 0
			while true:
				var at := text.find(entry_name + "(", search)
				if at < 0:
					break
				search = at + 1

				var cursor := _match_paren(text, at + entry_name.length())
				if cursor < 0:
					break

				for _step: int in range(CHAIN_LIMIT):
					var call := _next_call(text, cursor)
					var method := String(call["name"])
					if method.is_empty():
						break
					var found: PackedStringArray = calls[entry_name]
					if found.find(method) == -1:
						found.append(method)
						calls[entry_name] = found
					cursor = int(call["end"])
					if cursor < 0 or method != MESSAGE_HOOK:
						break
	return calls


# --- The guard --------------------------------------------------------------

func test_req_026_the_shim_implements_every_assertion_the_suites_call() -> void:
	var probes := _entry_probes()
	var calls := _collect_calls()

	for entry_name: String in calls:
		var probe: Object = probes[entry_name]
		for method: String in (calls[entry_name] as PackedStringArray):
			assert_bool(probe.has_method(method)).override_failure_message(
				"REQ-026: suites call %s(...).%s(...) but the assertion shim does "
				% [entry_name, method]
				+ "not implement it. GDScript resolves that at runtime, aborts the "
				+ "test mid-way and the runner scores it PASS — add the method to "
				+ "test/support/gdunit_compat.gd."
			).is_true()


func test_req_026_the_shim_guard_actually_found_the_suites() -> void:
	# Without this the guard above passes for a parser that matched nothing,
	# which is the same vacuous-green failure it exists to prevent.
	assert_int(_suite_paths(TEST_ROOT).size()).override_failure_message(
		"the harness guard found no suites to scan"
	).is_greater(3)

	var calls := _collect_calls()
	var total := 0
	for entry_name: String in calls:
		total += (calls[entry_name] as PackedStringArray).size()

	assert_int(total).override_failure_message(
		"the harness guard extracted no assertion calls — the chain parser "
		+ "is broken and this test is proving nothing"
	).is_greater(15)

	# And it must be finding the real, distinctive ones.
	assert_array(calls["assert_bool"]).contains(["is_true", "is_false"])
	assert_array(calls["assert_float"]).contains(["is_equal_approx"])


func test_req_026_the_shim_guard_reports_a_method_that_does_not_exist() -> void:
	# Proves the membership check bites rather than passing for anything.
	assert_bool(assert_array([]).has_method("is_equal")).is_true()
	assert_bool(assert_array([]).has_method("no_such_assertion")).override_failure_message(
		"has_method must distinguish a real assertion from an absent one"
	).is_false()


